/* Ezber kartları. Fizik/Kimya/Biyoloji: TYT (2018 MEB programı, 9–10. sınıf); Edebiyat: AYT (kaynak: Limit Yayınları AYT Edebiyat El Kitabı, kendi cümlelerimizle). Herkes için ortak içerik; flashcards.js okur.
   Biçim: [{subject, units:[{id, name, cards:[{f: ön yüz, b: arka yüz}]}]}] */
window.ODAK_CARDS = [{"subject":"Edebiyat","units":[{"id":"edb-1","name":"Metin Türleri ve Şiir Bilgisi","cards":[{"f":"Sanat nedir?","b":"Bir duygunun, tasarımın, güzelliğin dışavurumunda kullanılan anlatım yöntemlerinin tümüdür; belli bir uygarlığın ve dönemin anlayışını yansıtan yöntemler bütünüdür."},{"f":"Güzel sanatlar hitap ettiği duyuya göre nasıl ayrılır?","b":"Görsel (plastik) sanatlar: mimari, heykel, resim. İşitsel (fonetik) sanatlar: musiki, edebiyat."},{"f":"Hem göze hem kulağa hitap eden sanatlar hangileridir?","b":"Tiyatro, opera, bale, sinema; bunlara 'dramatik (ritmik) sanatlar' da denir, harekete biçim verirler."},{"f":"Zanaat ile sanat arasındaki fark nedir?","b":"Zanaat, maddeye dayalı ihtiyaçları karşılamak için deneyim ve ustalık gerektiren iştir; sanatçı ise güzellik ve özgünlük peşindedir."},{"f":"Edebiyat (yazın) nasıl tanımlanır?","b":"Olay, düşünce, duygu ve imgelerin estetik duygular uyandıracak biçimde, dil aracılığıyla söz ve yazıyla anlatımını amaç edinen sanattır."},{"f":"Edebiyatın psikoloji bilimiyle ilişkisine örnek kim ve hangi eserdir?","b":"Dostoyevski, 'Suç ve Ceza' adlı romanında Raskolnikov'un ruh dünyasını psikoloji biliminden yararlanarak başarıyla anlatmıştır."},{"f":"Edebiyatın tarih ve sosyoloji bilimleriyle ilişkisi nedir?","b":"Yazar tarihi olduğu gibi yazmak zorunda değildir ama gerçeğe bağlı kalmalıdır; edebi yapıtlar da dönemin toplumsal yapısını ve göreneklerini yansıtır."},{"f":"Metin nedir?","b":"Bir yazıyı biçim, anlatım ve noktalama özellikleriyle oluşturan sözcüklerin bütününe verilen addır; bir iletişim aracıdır."},{"f":"Edebi (kurmaca) metnin gerçeklikle ilişkisi nasıldır?","b":"Somut olgularla doğrudan özdeşlik kurulamaz; sanatçı kendine özgü bir gerçeklik (kurmaca) yaratır ve dış dünyayı yeniden biçimlendirir."},{"f":"Sanatsal metin ile öğretici metin dil kullanımı bakımından nasıl ayrılır?","b":"Sanatsal metinde sözcükler mecazlı, yeni anlamlarla; öğretici metinde ise herkesçe bilinen gerçek anlamıyla, göndergesel işlevde kullanılır."},{"f":"Zihniyet nedir?","b":"Bir eserin yazıldığı dönemin sosyal, siyasi, dini, ekonomik, askeri ve kültürel özelliklerinin sanatçının eserine yansımasıdır."},{"f":"Şiirde tema (izlek) ile konu arasındaki fark nedir?","b":"Tema soyut, genel bir duygudur (ör. sevgi); konu bu temanın somutlaşmış, sınırlandırılmış halidir (ör. çocukta anne sevgisi)."},{"f":"İmge nedir?","b":"Duyularla algılanan varlık ve durumların zihinde uyandırdığı, şiire yansıyan 'düşünsel resim'dir; şiir diline özgünlük katar."},{"f":"Alışılmamış bağdaştırma nedir?","b":"Anlamca aralarında uyum bulunmayan sözcüklerin bir arada kullanılmasıyla oluşan sıra dışı birleştirmedir (ör. 'kumral göklerinde saçlarının')."},{"f":"Şiirde sapma (sözcüksel/biçimsel) nedir?","b":"Sözcüklerin alışılmış dil kurallarının, sıralanışının dışına çıkarılarak kullanılmasıdır (ör. 'yazdım sevgiledim')."},{"f":"Dize (mısra) nedir, mısra-ı azade ne demektir?","b":"Şiirin en küçük nazım birimidir. Bir şiire bağlı olmayan, tek başına anlamı olan dizeye 'mısra-ı azade' denir."},{"f":"Beyit nedir?","b":"Aynı ölçüyle söylenmiş, aralarında anlam bütünlüğü bulunan iki dizelik nazım birimidir."},{"f":"Nazım şekli ile nazım türü arasındaki fark nedir?","b":"Nazım şekli, şiirin nazım birimi ve kafiye örgüsüyle ortaya çıkan biçimidir; nazım türü ise şiirin konusuna göre isimlendirilmesidir."},{"f":"Halk edebiyatında görülen nazım şekilleri hangileridir?","b":"Koşma, semai, varsağı, destan, mani, türkü."},{"f":"Divan edebiyatında görülen nazım şekilleri hangileridir?","b":"Gazel, kaside, mesnevi, kıt'a, rubai."},{"f":"Batı etkisindeki Türk edebiyatında görülen nazım şekilleri hangileridir?","b":"Sone, terza-rima, serbest müstezat."},{"f":"Hece ölçüsü nedir?","b":"Dizelerdeki hece sayısının eşitliğine dayanan ölçüdür; şiirin birinci dizesindeki hece sayısı sonraki dizelerde de aynıdır."},{"f":"Hece ölçüsünde durak nedir?","b":"Dizelerdeki sözcüklerin gruplanışından doğan, sözcükler ortadan bölünmeden belirlenen ayrım yeridir."},{"f":"Aruz ölçüsü nedir, kökeni nereden gelir?","b":"Hecelerin uzunluk-kısalığına dayanan bir ölçüdür; Arap nazım ölçüsüdür, İran (Fars) edebiyatından Türk edebiyatına geçmiştir."},{"f":"Aruzda imale ile zihaf arasındaki fark nedir?","b":"İmale: kapalı hece gereken yerde açık heceyi uzatarak okumak. Zihaf: ölçü zorunluluğuyla Arapça/Farsça bir sözcükteki uzun heceyi kısa okumak."},{"f":"Aruzda med (çekme) nedir?","b":"İki kapalı hece arasında açık hece bulunması gerektiğinde, uzun bir ünlü ya da ünsüzle biten heceyi imaleden biraz daha uzun okumaktır."},{"f":"Aruzda ulama (vasl) nedir?","b":"Sessiz harfle biten bir sözcükten sonra gelen sözcük sesli harfle başlarsa yapılan, iki heceyi birleştirir gibi okuma işlemidir."},{"f":"Aruzda kasr (kısaltma) nedir?","b":"Arapça/Farsça uzun bir sözcüğü hafifleştirerek kısa okumaktır (ör. 'şah' yerine 'şeh'); özel adlarda da yapılır (İstanbul yerine Stanbul gibi)."},{"f":"Serbest nazım nedir, ilk örneklerini kim vermiştir?","b":"Belli bir ölçü ve uyağa bağlı kalınmayan nazımdır; ilk örneklerini Nazım Hikmet vermiş, Orhan Veli 1940'lardan sonra yaygınlaştırmıştır."},{"f":"Redif nedir?","b":"Dize sonlarında yazılışları, anlamları ve görevleri aynı olan eklerin, sözcüklerin tekrarına denir; uyaktan sonraki kısımda yer alır."},{"f":"Uyak (kafiye) nedir, temel şartı nedir?","b":"Dize sonlarında yazılışı aynı, anlam ve görevi farklı seslerin/eklerin tekrarıdır; sesler aynı yazılmalı ama anlam ve görevleri farklı olmalıdır."},{"f":"Yarım uyak ile tam uyak arasındaki fark nedir?","b":"Yarım uyak: son hecede tek ses benzerliği. Tam uyak: son hecede biri ünlü biri ünsüz olmak üzere iki ses benzerliği."},{"f":"Zengin uyak nedir?","b":"Üç ya da daha çok ses benzerliğine dayanan uyak türüdür."},{"f":"Tunç uyak nedir?","b":"Uyaklı sözcüklerden birinin diğerinin içinde aynen yer aldığı uyak türüdür."},{"f":"Cinaslı uyak nedir?","b":"Yazılışları aynı, anlamları farklı sözcüklerin oluşturduğu uyak türüdür."},{"f":"Düz uyak düzeni nasıldır?","b":"aa/bb/cc... şeklindedir; her beyit kendi arasında uyaklıdır. Divan şiirindeki mesnevinin uyak düzeniyle aynıdır."},{"f":"Çapraz uyak ile sarma uyak arasındaki fark nedir?","b":"Çapraz uyak (abab): dörtlüğün tek ve çift dizeleri kendi arasında uyaklıdır. Sarma uyak (abba): birinci-dördüncü, ikinci-üçüncü dizeler uyaklıdır."},{"f":"Örüşük uyak nerede kullanılır, düzeni nasıldır?","b":"Terza-rima nazım biçiminde kullanılır; aba/bcb/cdc... biçiminde uyaklanan, üçlü bentlerden oluşan bir düzendir."},{"f":"Aliterasyon nedir?","b":"Bir dize ya da beyitte ahenk oluşturacak biçimde aynı ünsüzün tekrarlanmasıdır."},{"f":"Asonans nedir?","b":"Şiirde ahenk sağlamak için aynı ünlü seslerin tekrarlanmasıdır."},{"f":"Halk şiiri geleneği ile divan şiiri geleneği arasındaki fark nedir?","b":"Halk şiirinde nazım birimi dörtlük, hece ölçüsü ve saz kullanılır; divan şiirinde Arapça-Farsça yüklü dil, aruz ölçüsü ve beyit/dörtlük birimleri kullanılır."},{"f":"Epik şiir nedir, halk edebiyatındaki temsilcileri kimlerdir?","b":"Savaş ve kahramanlık konularını işleyen, coşku uyandıran şiirdir; halk edebiyatında koçaklama türüyle Köroğlu ve Dadaloğlu temsilcileridir."},{"f":"Lirik şiir nedir, temsilcileri kimlerdir?","b":"Duygu ve düşünceleri coşkun bir dille anlatan şiirdir; ilk temsilcisi Sappho, divanda Fuzuli, halkta Yunus Emre, Batı etkisinde Yahya Kemal'dir."},{"f":"Pastoral şiir nedir, diğer adı ve kurucusu kimdir?","b":"Kır ve çoban yaşamını, doğa güzelliklerini anlatan şiirdir; 'bukolik şiir' de denir, kurucusu Theokritos'tur."},{"f":"Didaktik şiir nedir, Türk edebiyatındaki ilk örneği hangisidir?","b":"Bir düşünce ya da bilgiyi öğretme amacıyla yazılan, duygu yönü az, akla dayanan şiirdir; ilk örneği Yusuf Has Hacib'in 'Kutadgu Bilig'idir."},{"f":"Satirik şiir nedir, halk ve divan edebiyatındaki adları nelerdir?","b":"Kişi ya da toplumun kötülüklerini iğneli, alaylı bir dille eleştiren şiirdir; halkta 'taşlama', divanda 'hicviye' denir."},{"f":"Dramatik şiir nedir?","b":"Tiyatroda kullanılan, manzum biçimde yazılmış tiyatro yapıtlarının şiiridir; tragedya ve komedya bu türün örnekleridir."},{"f":"Mensur şiir nedir?","b":"Ölçü ve uyak zorunluluğu olmayan, düzyazıyla yazılan ama şiirsel iç ahenge sahip yazıdır; Türk edebiyatına Halit Ziya'yla girmiştir."},{"f":"Manzum hikaye (manzume) nedir?","b":"Olay örgüsü, kişi, zaman-mekan unsurları olan; ölçülü ve kafiyeli ama şiirden farklı olarak düzyazıya çevrilebilen anlatı türüdür."},{"f":"Anlatmaya bağlı metinlerde yapı üç bölüme ayrılır, bunlar nelerdir?","b":"Serim (giriş): kişi ve yer tanıtılır. Düğüm (gelişme): olay hızlanıp gelişir. Çözüm (sonuç): düğüm çözüme, sonuca ulaşır."},{"f":"Anlatmaya bağlı metinlerde 'tip' ile 'karakter' arasındaki fark nedir?","b":"Tip, bir sınıfı/zümreyi temsil eden genel özellikte kişidir; karakter kendine özgüdür, kimseye benzemez, sadece kendini temsil eder."},{"f":"Bakış açısı kaça ayrılır, hakim (ilahi) bakış açısı nedir?","b":"Üçe ayrılır: hakim, kahraman, gözlemci. Hakim bakış açısında anlatıcı sınırsızdır; her şeyi, kişilerin geçmiş ve geleceğini de bilir."},{"f":"Kahraman anlatıcının bakış açısı nedir?","b":"I. kişi (ben öyküsü) anlatımıdır; olaylar kahramanlardan birinin ağzından, onun bildiği ve hissettiği kadarıyla anlatılır."},{"f":"Gözlemci-anlatıcıya ait bakış açısı nedir?","b":"'Dıştan bakış açısı' da denir; anlatıcı olayın dışındadır, sadece gördüğünü nesnel biçimde aktarır, yorum yapmaz."},{"f":"Roman nedir?","b":"Yaşanmış ya da yaşanabilecek olayları yer ve zaman göstererek ele alan, serim-düğüm-çözüm bölümlerinden oluşan uzun düzyazı türüdür."},{"f":"Romanda bilinç akışı ve montaj teknikleri nedir?","b":"Bilinç akışı: insan bilincinin işleyişine uygun dağınık iç monologlarla anlatım (Joyce-Ulysses). Montaj: farklı metinlerin bir araya getirilmesi."},{"f":"Türk edebiyatında ilk yerli roman ve ilk edebi roman hangileridir?","b":"İlk yerli roman Şemsettin Sami'nin 'Taaşşuk-ı Talat ve Fitnat'ı; ilk edebi roman Namık Kemal'in 'İntibah'ıdır."},{"f":"Sosyal roman nedir, dünya edebiyatındaki ilk örneği hangisidir?","b":"Toplumsal konuları (göç, yoksulluk, sınıf kavgası) işleyen romandır; ilk örneği Victor Hugo'nun 'Sefiller'idir."},{"f":"Tarihi roman nedir, Türk edebiyatındaki ilk örneği hangisidir?","b":"Geçmişteki tarihsel olay ve kişilerden alınan romandır; Türk edebiyatındaki ilk örneği Namık Kemal'in 'Cezmi'sidir."},{"f":"Psikolojik roman nedir?","b":"'Tahlil (çözümleme) romanı' da denir; kahramanların ruh çözümlemeleri yapılır. İlk örneği Madam de La Fayette'in 'La Princesse de Cleves'idir."},{"f":"Nehir (ırmak) roman nedir?","b":"Bir kişinin, ailenin ya da toplumun uzun bir zaman dilimindeki yaşamını birbirini izleyen ciltlerle anlatan geniş hacimli romandır."},{"f":"Popüler (yığın) roman ile estetik yapıt arasındaki temel fark nedir?","b":"Popüler romanda kolay anlaşılırlık ve eylem öne çıkar, sanat kaygısı azdır; estetik yapıtta biçim, dil ve derinlik kaygısı esastır."},{"f":"Öykü (hikaye) nedir?","b":"Yaşanmış ya da yaşanabilecek olayları kısa yoldan, serim-düğüm-çözüm bölümleriyle anlatan kısa yazı türüdür."},{"f":"Dünya edebiyatında öykü türünün ilk örneği hangisidir?","b":"İtalyan yazar Boccaccio'nun 'Decameron' adlı yapıtıdır."},{"f":"Olay (klasik) öyküsü nedir, kim ile özdeşleşmiştir?","b":"Bir çatışma ya da olay etrafında kurulan öyküdür, 'Maupassant tarzı' denir; Türk edebiyatında temsilcisi Ömer Seyfettin'dir."},{"f":"Durum (kesit) öyküsü nedir, kim ile özdeşleşmiştir?","b":"Yaşamdan bir kesiti, olay örgüsüne dayanmadan anlatan öyküdür, 'Çehov tarzı' denir; Türk edebiyatında temsilcisi Sait Faik Abasıyanık'tır."},{"f":"Modern öykünün öncüsü kimdir?","b":"Franz Kafka; insanların gördükleri fakat üzerinde düşünmedikleri gerçekleri, olağan dışı durumlar içinde anlatır."},{"f":"Destan nedir?","b":"Bir ulusun yaşayışını ilgilendiren savaş, göç gibi olağanüstü olayları çok uzun manzum öykülerle anlatan türdür."},{"f":"Doğal destan ile yapma destan arasındaki fark nedir?","b":"Doğal destan anonimdir, sözlüdür, uzak geçmişi anlatır; yapma destanın yazarı bellidir, yazılıdır ve daha yakın tarihi anlatır."},{"f":"İslamiyet öncesi Türk destanları hangileridir?","b":"Saka: Alp Er Tunga ve Şu; Hun: Oğuz Kağan; Göktürk: Bozkurt ve Ergenekon; Uygur: Türeyiş ve Göç destanları."},{"f":"İslamiyet'ten sonraki Türk destanları hangileridir?","b":"Satuk Buğra Han, Cengiz Han, Battal Gazi, Danişment Gazi, Edige (Altınorda), Manas (Kırgız) destanları."},{"f":"Yunan ve Hint doğal destanları hangileridir, kim derlemiştir?","b":"Yunan: İlyada ve Odysseia (Homeros). Hint: Mahabarata ve Ramayana (Ramayana'yı Valmiki derlemiştir)."},{"f":"Masal nedir?","b":"Anonim, düş gücünün ürünü, gerçekle ilgisi olmayan, genellikle 'evvel zaman içinde' diye başlayan, eğitici yönü olan kısa hikayedir."},{"f":"Masalların konularına göre dört türü nedir?","b":"Hayvan masalları, asıl masallar (olağanüstü/gerçek), nükteli fıkralar-güldürücü hikayeler, zincirlemeli masallar."},{"f":"Fabl nedir, Doğu ve Batı edebiyatındaki öncüleri kimlerdir?","b":"Kahramanları hayvan/bitki olan, sonunda ahlak dersi (kıssadan hisse) verilen hikayedir; Doğu'da Beydaba, Batı'da La Fontaine öncüdür."},{"f":"Tiyatro (temaşa) nedir?","b":"Konuşma ve eylemin sahnede oyuncular tarafından canlandırıldığı gösteri sanatıdır; kaynağı Dionysos adına yapılan eski Yunan törenleridir."},{"f":"Tiyatroda 'üç birlik kuralı' nedir?","b":"Zaman birliği (olay 24 saatte geçmeli), yer birliği (aynı yerde geçmeli), olay birliği (tek bir ana olay etrafında gelişmeli)."},{"f":"Tragedya nedir?","b":"Seyircide acıma ve korku duyguları uyandırarak ruhu tutkulardan temizlemeyi amaçlayan; konuları mitolojiden/tarihten alınan ciddi tiyatro türüdür."},{"f":"Komedya (komedi) nedir?","b":"İnsanların ve olayların gülünç yönlerini alaylı biçimde ortaya koyan, güldürerek düşündürme amacı güden tiyatro türüdür."},{"f":"Karakter komedyası ve töre komedyası nedir?","b":"Karakter komedyası kişinin gülünç yönlerini işler (Moliere-Cimri); töre komedyası toplumun gülünç yönlerini işler (Şinasi-Şair Evlenmesi)."},{"f":"Vodvil ve fars nedir?","b":"Vodvil: entrikaları bulunan hafif bir komedi türü. Fars: halk komedisi; eğlenceli, basit, kaba olay ve yergilerle dolu, abartılı komedi."},{"f":"Dram nedir, tragedyadan farkı nedir?","b":"19. yüzyılda trajedinin katı kurallarını yıkmak için ortaya çıkan türdür; hem acıklı hem komik olaylar bir arada olabilir, üç birlik kuralı aranmaz."},{"f":"Epik tiyatro nedir, kurucusu kimdir?","b":"Seyirciyi oyuna kaptırmayı değil düşündürmeyi amaçlayan modern tiyatro türüdür; kurucusu Bertold Brecht'tir."},{"f":"Absürt tiyatro nedir?","b":"Geleneksel tiyatro kurallarını yok sayan, mantık ve gerçeklikten uzaklaşmayı işleyen modern tiyatro türüdür; temsilcisi Eugene Ionesco'dur."},{"f":"Türk edebiyatında ilk modern (Batılı) tiyatro yapıtı hangisidir?","b":"Şinasi'nin 'Şair Evlenmesi' adlı yapıtıdır."}]},{"id":"edb-2","name":"Öğretici Metinler ve Sözlü Anlatım","cards":[{"f":"Öğretici metinlerde 'ana düşünce' neyden çıkarılır?","b":"Metnin bütününden çıkarılır; ana düşünce giriş, gelişme, sonuç bölümlerinin tek başına değil tümünün ortak ürünüdür."},{"f":"Türk edebiyatında öğretici metin geleneği neyle başlamıştır?","b":"Gazete ile başlamıştır; Şinasi'nin Tercüman-ı Ahval gazetesinde yayımladığı 'Mukaddime' makalesiyle."},{"f":"Öğretici metinlerde dil hangi işlevde kullanılır?","b":"Göndergesel işlevde kullanılır; herkesçe bilinen, somut ve gerçek anlamlı sözcükler tercih edilir."},{"f":"Deneme nedir?","b":"Yazarın seçtiği bir konudaki düşüncelerini kesin sonuca varma ve ispatlama kaygısı gütmeden, kendi kendisiyle konuşuyormuş gibi anlattığı yazı türüdür."},{"f":"Deneme türünün dünya edebiyatındaki kurucusu kimdir?","b":"Fransız yazar Montaigne'dir; Batı'da bu türün diğer önemli ismi İngiliz F. Bacon'dır."},{"f":"'Deneme ben'in ülkesidir' sözü kime aittir?","b":"Nurullah Ataç'a aittir; Türk edebiyatında denemenin asıl başarılı örneklerini Cumhuriyet döneminde o vermiştir."},{"f":"Deneme ile makale arasındaki temel fark nedir?","b":"Denemede kesin hüküm ve ispat zorunluluğu yoktur, kişisel görüş ön plandadır; makalede bir tez kanıtlanır, dil daha kuralcı ve resmidir."},{"f":"Makale nedir?","b":"Bir konuda bilgi vermek, görüş öne sürmek ya da bir tezi savunmak için yazılan; açık, anlaşılır ve ciddi dilli bilimsel yazı türüdür."},{"f":"Türk edebiyatında ilk makale hangisidir?","b":"Şinasi'nin 22 Ekim 1860'ta 'Tercüman-ı Ahval' gazetesinde yayımlanan 'Mukaddime' başlıklı yazısıdır."},{"f":"Fıkra (köşe yazısı) nedir?","b":"Gazetelerin belirli köşelerinde genel bir başlık altında yazılan, kısa, yoğun, günübirlik ve kalıcılığı olmayan yazı türüdür."},{"f":"Fıkra ile makale arasındaki temel fark nedir?","b":"Fıkrada bilimsellik ve kanıtlama amacı yoktur, yalın ve günübirlik bir dil kullanılır; makalede kanıtlama ve bilimsellik esastır."},{"f":"Türk edebiyatında fıkra türünün en tanınmış yazarı kimdir?","b":"Ahmet Rasim'dir."},{"f":"Söyleşi (sohbet) nedir?","b":"Herhangi bir düşünceyi, konuyu; yazarın karşısında biri varmış gibi günlük, sıradan ve rahat bir dille anlattığı düşünce yazısıdır."},{"f":"Söyleşi (sohbet) türünün Servet-i Fünun dönemindeki adı nedir?","b":"'Musahabe' adı verilmiştir."},{"f":"Eleştiri (tenkit) nedir?","b":"Bir sanat ya da düşünce eserinin özünü, yapısını, değerli ve değersiz yanlarını belge ve örneklerle belirten yazı türüdür."},{"f":"Eleştiri kavramının Tanzimat'taki ve sonraki adları nelerdir?","b":"Tanzimat'ta 'muaheze', Servet-i Fünun'dan sonraki dönemlerde 'tenkit' sözcüğüyle karşılanmıştır."},{"f":"İzlenimsel (öznel) eleştiri nedir?","b":"Eleştirmenin sanat eseri karşısındaki tutumunu kendi zevk ölçütlerine göre öznel biçimde belirttiği eleştiridir; öncüsü Anatole France'dır."},{"f":"Nesnel (bilimsel) eleştiri nedir?","b":"Kişisel düşüncelerden kaçınan, belirli yasalara ve nesnel ölçütlere bağlı, bilimsel araştırmalardan yararlanan eleştiridir; öncüsü Hippolyte Taine'dir."},{"f":"Türk edebiyatında eleştiri özelliği taşıyan ilk yazı hangisidir?","b":"Namık Kemal'in 'Lisan-ı Osmaninin Edebiyatı Hakkında Bazı Mülahazatı Şamildir' adlı makalesidir."},{"f":"Anı (hatıra) nedir?","b":"Bir yazarın başından geçen ya da tanık olduğu olay ve olguları, bilgi ve gözlemlerine dayanarak anlattığı yazı türüdür."},{"f":"Anı ile günlük arasındaki temel fark nedir?","b":"Anı, olaylar bittikten sonra geçmişe dönük olarak kaleme alınır; günlük ise olayın yaşandığı gün, an be an yazılır."},{"f":"Türk edebiyatında anı türünün ilk örnekleri hangileridir?","b":"'Göktürk (Orhun) Yazıtları'dır; ilk edebi anı ise Babür Şah'ın 'Babürname'sidir."},{"f":"Dünya edebiyatında anı türünün ilk örneği hangisidir?","b":"Eski Yunan edebiyatından Ksenophon'un 'Anabasis' adlı eseridir."},{"f":"Gezi yazısı nedir?","b":"Bir yazarın yurt içinde ve yurt dışında gezip gördüğü yerlerin ilgi çekici özelliklerini anlattığı yazı türüdür."},{"f":"Gezi yazısına eskiden verilen ad nedir, gezen kişiye ne denir?","b":"'Seyahatname' denir; gezen kişiye 'seyyah' adı verilir."},{"f":"Türk edebiyatında en önemli gezi yazısı örneği hangisidir?","b":"Evliya Çelebi'nin 'Seyahatnamesi'dir."},{"f":"Dünya edebiyatında önemli gezi yazarları kimlerdir?","b":"Marco Polo (13. yüzyıl, Uzak Doğu) ve Arap gezgin İbni Batuta (14. yüzyıl, İslam dünyası)."},{"f":"Biyografi (yaşam öyküsü) nedir?","b":"Toplumda ilgiyle karşılanan, tanınmış kişilerin yaşamını üçüncü kişi ağzından, belge ve kanıtlara dayanarak anlatan yazı türüdür."},{"f":"Biyografi türünün ilk yazarı kabul edilen kimdir, divan edebiyatındaki karşılığı nedir?","b":"Plutarkhos ilk yazar sayılır; divan edebiyatında karşılığı 'tezkire'dir. İlk şairler tezkiresi Ali Şir Nevai'nin 'Mecalisü'n-Nefais'idir."},{"f":"Otobiyografi (öz yaşam öyküsü) nedir?","b":"Toplumsal yaşamda tanınmış kişilerin, yaşamlarını kendilerinin anlattığı yazı türüdür; birinci kişili anlatım kullanılır."},{"f":"Biyografi ile otobiyografi arasındaki temel fark nedir?","b":"Biyografi üçüncü kişi ağzından, nesnel ve belgeye dayalıdır; otobiyografi birinci kişi ağzından, öznel ve hafızaya dayalıdır."},{"f":"Günlük (günce) nedir?","b":"Yaşanan olayları ve bu olayların kişide bıraktığı izlenimleri, tarih atılarak günü gününe yazıya geçirilmesiyle oluşan yazı türüdür."},{"f":"Günlük türünde 'içe dönük günlük' ve 'dışa dönük günlük' ayrımı nedir?","b":"İçe dönük günlükte kişinin iç dünyası ve duyguları; dışa dönük günlükte dış olaylar ve gözlemler ağır basar."},{"f":"Röportaj nedir?","b":"Herhangi bir yerin ya da kurumun gezilerek, orada görülenlerin kişisel yorumlarla ve fotoğraflarla desteklenerek kaleme alındığı yazı türüdür."},{"f":"Amerikan röportajı ile Alman röportajı arasındaki fark nedir?","b":"Amerikan röportajında en çarpıcı bilgi girişte verilir (ters piramit); Alman röportajında yazar konuyu 'ben' ekseninde işler."},{"f":"Mülakat nedir?","b":"Tanınmış kişilerle yaşamları, çalışmaları ya da bir konuda sorulu cevaplı karşılıklı konuşmaların yazıya geçirilmesiyle oluşan yazı türüdür."},{"f":"Mülakatta alınan cevaplar nasıl aktarılmalıdır?","b":"Aynen ve yorumlanmadan aktarılmalıdır; görüşülen kişinin kim olduğu ve niçin konuşulduğu belirtilmelidir."},{"f":"Mektup nedir?","b":"Birbirinden farklı yerlerde bulunan kişi ve kurumlar arasında özel ya da resmi iletişim sağlayan yazı türüdür."},{"f":"Mektup türleri nelerdir?","b":"Resmi mektup, iş mektubu, özel mektup, edebi/felsefi mektup, açık mektup."},{"f":"Edebi (felsefi) mektup nedir, Türk edebiyatındaki ilk örneği hangisidir?","b":"Bir düşüncenin açıklanması ya da bir tezin savunulması için sanat amacıyla yazılan mektuptur; ilk örneği Fuzuli'nin 'Şikayetname'sidir."},{"f":"Açık mektup nedir?","b":"Bir kişiye seslenilen ama başkalarının okuması için gazete ve dergilerde yayımlanan mektup türüdür."},{"f":"Haber yazısı nedir, haber toplayana/yazana ne denir?","b":"Halka duyurulmak için gazete, dergi, radyo ve televizyonlarda yayımlanan yazı türüdür; haber toplayana ve yazana 'muhabir' denir."},{"f":"Haber çeşitleri nelerdir?","b":"Resmi haberler (yetkili kişilerden alınan), özel haberler (halk arasından toplanan), ajans haberleri (ajanslardan alınan)."},{"f":"Haber planı nasıl adlandırılır, neden?","b":"'Tersine dönmüş piramit' denir; giriş bölümünde olay özetlenir, gelişme bölümünde ayrıntı, sonuçta olayın etkisi anlatılır."},{"f":"Haberde '5N1K' kuralı neyi ifade eder?","b":"Ne, niçin, nasıl, nerede, ne zaman, kim sorularına yanıt verecek biçimde haberin oluşturulması kuralıdır."},{"f":"Asparagas haber nedir?","b":"Gerçek olmayan, sahte haberlere verilen isimdir."},{"f":"Monografi nedir?","b":"Bilim, sanat, siyaset gibi alanlardan birinde tanınan bir kişinin yaşamını, kişiliğini ve yapıtlarını derinlemesine inceleyen yazı türüdür."},{"f":"Monografi biyografiden nasıl ayrılır?","b":"Konuyu derinlemesine ele alması, inceleme ve araştırmaya dayanmasıyla ayrılır."},{"f":"Bibliyografya nedir, Türk edebiyatındaki ilk örneği hangisidir?","b":"Basılı malzemeyi tür ya da yıl gibi ölçütlere göre liste halinde tanıtan yapıttır; ilk örneği Katip Çelebi'nin 'Keşfü'z-Zünun'udur."},{"f":"Özdeyiş (vecize) nedir?","b":"Bireysel ya da toplumsal bir ilkeyi, görüşü ya da yargıyı en kısa yoldan anlatan bilgece sözdür."},{"f":"İslam büyüklerinin özdeyişlerine verilen ad nedir?","b":"'Kelam-ı kibar' denir."},{"f":"Tartışma nedir?","b":"Bir görüşün çeşitli yönleriyle ele alındığı, karşıt görüşlerin dile getirildiği grup konuşmalarıdır."},{"f":"Panel nedir?","b":"Değişik görüşlerdeki küçük bir konuşmacı grubunun, izleyici önünde sohbet havasında görüşlerini belirttiği toplantıdır; konuşmacı sayısı 3-6'dır."},{"f":"Forum nedir?","b":"Bir başkanın yönetiminde, toplumu ilgilendiren bir konuda, farklı gruplardan dinleyicilerin de söz alarak katıldığı tartışma türüdür."},{"f":"Sempozyum (bilgi şöleni) nedir?","b":"Bir konunun çeşitli yönleri üzerine, aynı oturumda, uzman kişilerce genellikle akademik ortamda yapılan seri konuşmalardır."},{"f":"Münazara nedir?","b":"Bir tezle antitezin, iki grup arasında bir hakem/jüri huzurunda tartışıldığı, birer fikir ve söz yarışması sayılan konuşma türüdür."},{"f":"Açık oturum nedir?","b":"Geniş halk kitlelerini ilgilendiren bir konunun, uzmanlarca bir başkan yönetiminde dinleyici grubu önünde tartışıldığı konuşma türüdür."},{"f":"Seminer nedir?","b":"Bir konuyla ilgili yapılan araştırma sonuçları hakkında bilgi vermek ve tartışmak amacıyla düzenlenen toplantıdır."},{"f":"Konferans nedir?","b":"Alanında uzman birinin bir konu hakkında, dinleyicileri bilgilendirmek ya da öğretmek amacıyla yaptığı konuşmadır."},{"f":"Söylev (nutuk/hitabet) nedir?","b":"Belli bir konuda bir topluluk önünde söz söyleme sanatına 'hitabet', bu konuşmaya 'söylev' ya da 'nutuk' denir; eskiden konuşana 'hatip' denirdi."},{"f":"Forum ile açık oturum arasındaki fark nedir?","b":"Forumda dinleyiciler serbestçe soru sorabilir; açık oturumda dinleyiciler sadece alkışlarla katılır, soru soramaz."}]},{"id":"edb-3","name":"Edebi Sanatlar","cards":[{"f":"Teşbih (benzetme) nedir, dört unsuru nelerdir?","b":"İki varlığı ortak özellikte benzetme sanatı. Unsurlar: benzeyen, kendisine benzetilen, benzetme edatı (gibi, sanki), benzetme yönü."},{"f":"Tam (ayrıntılı) teşbih nedir?","b":"Benzeyen, kendisine benzetilen, benzetme edatı ve benzetme yönü olmak üzere dört ögesi de bulunan teşbihtir."},{"f":"Pekiştirilmiş teşbih nedir?","b":"Benzetme edatının bulunmadığı teşbih çeşididir."},{"f":"Kısaltılmış teşbih nedir?","b":"Benzetme yönünün bulunmadığı teşbih çeşididir."},{"f":"Teşbih-i beliğ (yalın benzetme) nedir?","b":"Sadece benzeyen ve kendisine benzetilenle yapılan; benzetme edatı ve yönünün olmadığı teşbihtir."},{"f":"İstiare (eğretileme) nedir?","b":"Bir sözün benzetme amacıyla başka bir sözün yerine kullanılmasıdır; teşbihin temel unsurlarından sadece biri kullanılır."},{"f":"Açık istiare nedir?","b":"Sadece kendisine benzetilenin kullanıldığı, benzeyenin hiç söylenmediği istiaredir. Örn: gökyüzü kurşunla örtülüydü (bulut kastedilir)."},{"f":"Kapalı istiare nedir?","b":"Sadece benzeyenin kullanıldığı, kendisine benzetilenin söylenmediği istiaredir; genelde teşhisle birlikte görülür."},{"f":"Temsili istiare (alegori) nedir?","b":"Bir metnin bütününe yayılan, düşünce ve olayların sembollerle anlatıldığı istiaredir. Örn: Merdiven-Ahmet Haşim, Sessiz Gemi-Yahya Kemal."},{"f":"Mecazımürsel (ad aktarması) nedir?","b":"Benzetme amacı olmadan bir kavramın, ilgi yoluyla (parça-bütün, yer-insan vb.) başka bir kavram yerine kullanılmasıdır."},{"f":"Teşhis (kişileştirme) nedir?","b":"İnsan dışındaki canlı ya da cansız varlıkları düşünen, hareket eden bir insan kişiliğinde göstermektir."},{"f":"İntak (konuşturma) nedir?","b":"İnsan dışındaki varlıklara konuşma özelliği vermektir; kişileştirilen varlığın dize içinde konuşması gerekir."},{"f":"Teşhis ile intak arasındaki fark nedir?","b":"Her intak aynı zamanda teşhistir ama her teşhis intak değildir; varlık konuşmuyorsa sadece teşhis vardır."},{"f":"Tezat nedir?","b":"Anlamca birbirine karşıt sözcükleri bir arada kullanma sanatıdır. Örn: yüksek-alçak, yakın-uzak."},{"f":"Kinaye nedir?","b":"Bir sözü hem gerçek hem mecaz anlama gelecek biçimde kullanmaktır; asıl kastedilen mecaz anlamdır."},{"f":"Tevriye nedir?","b":"İki anlamlı bir sözcüğü iki anlama gelecek biçimde kullanıp yakın anlamı söyleyip uzak anlamı kastetmektir; genelde sesteş veya özel isimlerle yapılır."},{"f":"Tariz (iğneleme) nedir?","b":"Söylenen bir sözün tam tersini kastetme sanatıdır; genelde alaycı bir üslupla yapılır."},{"f":"Cinas (sesteşlik) nedir?","b":"Söylenişi ve yazılışı bir, anlamı farklı iki sözcüğü bir arada kullanma sanatıdır."},{"f":"Tam cinas ile ayrık cinas arasındaki fark nedir?","b":"Tam cinasta sesteşlik tek sözcükle sağlanır; ayrık cinasta birden fazla sözcüğün birleşimiyle sağlanır."},{"f":"Mübalağa (abartma) nedir?","b":"Bir durumu ya da olayı olduğundan büyük veya küçük göstermektir."},{"f":"Hüsnütalil (güzel nedene bağlama) nedir?","b":"Bir olayın gerçek nedenini bırakıp ona hayali, güzel bir başka neden bulmaktır."},{"f":"Tecahülüarif (bilmezlikten gelme) nedir?","b":"Bildiği bir şeyi bilmez görünerek anlatma sanatıdır."},{"f":"İstifham (soru sorma) nedir?","b":"Duygu ve anlatımı güçlendirmek için yanıt beklenmeden soru sorma sanatıdır."},{"f":"Telmih (hatırlatma) nedir?","b":"Bilinen bir geçmiş olaya, ünlü kişiye, atasözüne ya da bir şiire işaret etme sanatıdır."},{"f":"Tenasüp (uygunluk) nedir?","b":"Anlamca birbiriyle ilgili sözcükleri bir arada kullanma sanatıdır."},{"f":"İrsalimesel nedir?","b":"Şiirde anlatımı etkileyici kılmak için atasözü ya da özdeyiş kullanma sanatıdır."},{"f":"Seci nedir?","b":"Düz yazıda sözcüklerin uyaklı olabilecek biçimde kullanılmasıdır; özellikle divan nesrinde görülür."},{"f":"Leff ü neşr nedir?","b":"Bir dizede en az iki şey söylenip sonraki dizede bunlarla ilgili benzerlik ya da karşıtlıkların verilmesidir."},{"f":"Tekrir nedir?","b":"Anlatımı güçlendirmek için bir sözcüğün ya da söz öbeğinin tekrarlanmasıdır."},{"f":"Rücu nedir?","b":"Sözün etkisini artırmak için önce söylenen düşünceden dönüp tam tersini söylemektir."},{"f":"Sehlimümteni nedir?","b":"Söylenmesi kolay görünen ama aslında kolay söylenemeyecek dizeler söyleme sanatıdır."},{"f":"Akis nedir?","b":"Bir dizenin iki parçasını önce kurallı sonra devrik sırayla tekrar söyleme sanatıdır. Örn: Cennet gibidir ruyın, ruyın gibidir cennet."},{"f":"Nida nedir?","b":"Seslenme sanatıdır."},{"f":"Terdit nedir?","b":"Bir konuyu anlattıktan sonra sözü beklenmedik biçimde bitirme sanatıdır."},{"f":"Tedric (derecelendirme) nedir?","b":"Söylenecek sözleri belirli bir sırayla (artan ya da azalan) ortaya koyma sanatıdır."},{"f":"Akrostiş nedir?","b":"Dizelerin baş harflerinin birleşmesiyle anlamlı bir sözcük ya da isim oluşturma sanatıdır."},{"f":"İktibas nedir?","b":"Söze güç katmak için ayet ya da hadisten alıntı yapma sanatıdır."},{"f":"Teşbih ile istiare arasındaki temel fark nedir?","b":"Teşbihte benzetmenin temel iki unsuru (benzeyen, kendisine benzetilen) birlikte bulunur; istiarede sadece biri kullanılır."},{"f":"Kinaye ile tevriye arasındaki fark nedir?","b":"Kinayede sözcüğün tek anlamı vardır ama hem gerçek hem mecaz kastedilir; tevriyede sözcüğün iki anlamı vardır, uzak anlam kastedilir."},{"f":"Teşhisin olduğu yerde çoğu zaman hangi sanat da bulunur?","b":"Kapalı istiare; çünkü kapalı istiare genelde teşhisle birlikte görülür."},{"f":"Mecazlı atasözlerinde sık görülen edebi sanat hangisidir?","b":"Açık istiare. Örn: Yuvayı yapan dişi kuştur."},{"f":"İnsan bir yanınca Kerem misali yanmalı dizesindeki sanat hangisidir?","b":"Telmih; Kerem ile Aslı hikâyesine gönderme yapılmıştır."}]},{"id":"edb-4","name":"Nazım Biçimleri ve Türleri","cards":[{"f":"Sagu nedir?","b":"İslamiyet öncesi Türk edebiyatında yuğ (cenaze) törenlerinde söylenen, ölüm acısını ve ölenin iyi yönlerini anlatan şiirlerdir; hece ölçüsü ve yarım uyak kullanılır."},{"f":"Sagu türünün en önemli örneği hangisidir?","b":"Divanü Lügati't-Türk'te yer alan Alp Er Tunga Sagusu."},{"f":"Koşuk nedir, neye kaynaklık eder ve neye benzer?","b":"Sığır ve şölen törenlerinde kopuz eşliğinde söylenen; halk edebiyatında koşmaya kaynaklık etmiş, divan edebiyatında gazele benzeyen şiirlerdir."},{"f":"Mani nedir?","b":"Anonim halk edebiyatında en küçük nazım biçimidir; 7'li hece ölçüsüyle söylenen, aaxa kafiyeli dörtlüktür."},{"f":"Mani'de ilk iki dize ile asıl anlam arasındaki ilişki nedir?","b":"İlk iki dize hazırlık dizesidir, konuyla ilgisi yoktur; asıl anlatılmak istenen son dizede verilir."},{"f":"Düz mani nedir?","b":"Yedişer heceli dört dizeden oluşan, kafiyeleri çoğunlukla cinaslı olan mani çeşididir."},{"f":"Kesik mani nedir?","b":"Birinci dizesi 7 heceden az, anlamlı ya da anlamsız bir sözcük grubu olan; bu kısa dize cinaslı kafiyeyi hazırlar."},{"f":"Yedekli (artık) mani nedir?","b":"Düz maninin üçüncü dizesinden sonra aynı uyakta iki dize daha eklenerek oluşan manidir."},{"f":"Deyiş (mani türü) nedir?","b":"İki kişinin karşılıklı söylediği, soru-yanıt şeklinde düzenlenen manilerdir."},{"f":"Türkü nedir?","b":"Bir ezgiyle (besteli) söylenen, düzenleyicisi bilinmeyen ya da unutulmuş, genelde 7'li 8'li 11'li hece kalıplarıyla oluşturulan şiirlerdir."},{"f":"Türkünün yapısındaki bent ve kavuştak nedir?","b":"Asıl bölüm bent, bendin sonunda yinelenen nakarat bölümü ise kavuştak (bağlama) olarak adlandırılır."},{"f":"Ninni nedir?","b":"Annelerin bebeklerini uyutmak için belli bir ezgiyle söylediği parçalardır."},{"f":"Ağıt (halk edebiyatı) nedir?","b":"Sevilen bir kişinin ölümünden duyulan acıyı dile getiren, bir ezgiyle söylenen şiirlerdir."},{"f":"Ölüm temalı şiirlere dönemlere göre verilen adlar nelerdir?","b":"İslamiyet öncesinde sagu, halk edebiyatında ağıt, divan edebiyatında mersiye denir."},{"f":"Koşma nedir?","b":"Aşık edebiyatının en sevilen ve yaygın nazım biçimidir; halk edebiyatındaki koşuğun devamı niteliğindedir."},{"f":"Koşmanın dörtlük sayısı ve hece ölçüsü nedir?","b":"3-5(6) dörtlükten oluşur, 11'li hece ölçüsüyle (6+5 ya da 4+4+3 duraklı) yazılır."},{"f":"Koşmanın kafiye örgüsü nasıldır?","b":"abab/cccb/dddb... ya da xaxa/bbba/ccca... şeklindedir."},{"f":"Koşma konu yönünden divan edebiyatındaki hangi türlere benzer?","b":"Gazel ve şarkıya benzer."},{"f":"Güzelleme nedir?","b":"İnsan, hayvan ve doğa güzelliklerinin anlatıldığı koşmalardır; en ünlü şairi Karacaoğlan'dır."},{"f":"Koçaklama nedir?","b":"Yiğitçe bir anlatımla söylenen, kahramanlık ve savaş konulu koşmalardır; en başarılı sanatçıları Köroğlu ve Dadaloğlu'dur."},{"f":"Taşlama nedir?","b":"Toplumun ve insanların eksik yönlerinin eleştirildiği koşmalardır; bu türün ünlü ozanı Seyrani'dir."},{"f":"Karşılıklı, dedim-dedi biçiminde söylenen koşmalara ne denir?","b":"Müracaa denir."},{"f":"Semai (halk edebiyatı) nedir ve koşmadan farkı nedir?","b":"Koşmaya benzeyen, 8'li hece ölçüsüyle söylenen, kendine özgü bir ezgisi olan nazım biçimidir; bu iki özellikle koşmadan ayrılır."},{"f":"Varsağı nedir ve nasıl bir hava taşır?","b":"Güney Anadolu'daki Varsak Türklerinden gelişen, semaiye benzeyen bir biçimdir; meydan okuyan, babacan bir hava taşır, ilk dörtlükte bre-hey gibi ünlemler geçer."},{"f":"Varsağıyı en çok söyleyen şair kimdir?","b":"Karacaoğlan."},{"f":"Destan (aşık edebiyatı) nedir?","b":"Ulusların kahramanlık olaylarını anlatan destan (epope) ile karıştırılmaması gereken; halk şiirinin en uzun nazım biçimidir."},{"f":"Destanın (aşık edebiyatı) biçim özellikleri nelerdir?","b":"11'li ya da 8'li hece kalıbıyla söylenir; dörtlük sayısı 100'ü geçebilir; son dörtlükte şair mahlasını söyler."},{"f":"Destan türünün ünlü temsilcileri kimlerdir?","b":"Seyrani ve Aşık Ömer; Kayıkçı Kul Mustafa'nın Genç Osman Destanı en önemli örnektir."},{"f":"Aşık edebiyatında aruzla yazılan başlıca türler nelerdir?","b":"Divani, selis, satranç, vezn-i ahir, kalenderi ve aruzlu semai."},{"f":"Tekke edebiyatı nazım türlerinin ortak özelliği nedir?","b":"Bunlar ayrı bir nazım biçimi değil, tasavvufi/dinsel konuları işleyen türlerdir; genelde koşma biçiminde, 7-8-11'li hecelerle söylenirler."},{"f":"İlahi nedir?","b":"Herhangi bir tarikatın izini taşımaksızın Allah'ı öven şiirlerdir; divan şiirindeki tevhit ve münacata halk edebiyatındaki karşılığıdır."},{"f":"İlahiye tarikatlara göre verilen farklı adlar nelerdir?","b":"Mevleviler ayin, Bektaşiler nefes, Gülşeniler tapuğ, Halvetiler durak, öteki tarikatlar cumhur ya da ilahi der."},{"f":"İlahi türünün en ünlü şairi kimdir?","b":"Yunus Emre."},{"f":"Nefes nedir?","b":"Bektaşi şairlerinin yazdığı, vahdet-i vücut kavramını ve Hz. Muhammet-Hz. Ali için övgüleri anlatan tasavvufi şiirlerdir; Pir Sultan Abdal ile özdeşleşmiştir."},{"f":"Deme nedir?","b":"Alevi-Bektaşi tarikatından tasavvuf şiirlerinin tarikatlarını ve hareketlerini konu edinen şiirlerdir."},{"f":"Nutuk (tekke edebiyatı) nedir?","b":"Pirlerin/mürşitlerin tarikata yeni giren müritleri tarikat dereceleri ve kuralları konusunda bilgilendirmek için söylediği didaktik şiirlerdir."},{"f":"Devriye nedir?","b":"Evrendeki canlı cansız her şeyin Allah'tan geldiğini ve yine Allah'a döneceğini (devir teorisi) anlatan tekke şiirleridir."},{"f":"Şathiye nedir?","b":"Dini ve tasavvufi konuları mizahi, alaycı bir dille işleyen halk şiirleridir; en ünlü şairi Kaygusuz Abdal'dır."},{"f":"Gazel nedir?","b":"Divan edebiyatının en yaygın nazım biçimidir; kadınlar için söylenen güzel söz anlamına gelen, 5-15 beyitlik şiirdir."},{"f":"Gazelde matla, makta ve musarra beyit nedir?","b":"Matla ilk beyit, makta son beyittir; kafiyeli ilk beyite musarra denir. Şairin mahlası genelde son beyitte geçer."},{"f":"Hüsn-i matla ve hüsn-i makta nedir?","b":"İlk beyitten sonraki beyit ilk beyitten güzelse hüsn-i matla; son beyitten önceki beyit son beyitten güzelse hüsn-i makta denir."},{"f":"Yek-ahenk ve yek-avaz gazel nedir?","b":"Beyitleri arasında anlam bütünlüğü olan gazellere yek-ahenk; söyleyiş bakımından bütünlük olanlara yek-avaz gazel denir."},{"f":"Gazelin en güzel beytine ne ad verilir?","b":"Beytü'l-gazel ya da şah beyit."},{"f":"Musammat gazel nedir?","b":"Dize ortalarında da uyak bulunan gazellerdir."},{"f":"Aşıkane gazel nedir, temsilcisi kimdir?","b":"Aşkın verdiği mutluluk, sıkıntı, sevgiliden yakınma gibi duyguları anlatan gazeldir; temsilcisi Fuzuli'dir."},{"f":"Rindane gazel nedir, temsilcisi kimdir?","b":"İçkiyi, zevkini, hayattan zevk almayı konu alan gazeldir; temsilcisi Baki'dir."},{"f":"Şuhane gazel nedir, temsilcisi kimdir?","b":"Kadını ve aşkın zevklerini zarif, çapkın bir üslupla anlatan gazeldir; temsilcisi Nedim'dir."},{"f":"Hakimane gazel nedir, temsilcisi kimdir?","b":"Ahlakla ilgili öğütler veren, özdeyiş niteliğindeki sözlerin ağır bastığı gazeldir; temsilcisi Nabi'dir."},{"f":"Kaside nedir?","b":"Din ve devlet büyüklerini övmek için belli bir amaçla yazılan uzun şiirdir (genellikle 33–99 beyit)."},{"f":"Kasidenin en güzel beyti ve mahlas beyti nedir?","b":"En güzel beyte beytü'l-kasid, şairin mahlasının geçtiği beyte taç beyti denir."},{"f":"Kasidenin nesib (teşbib) bölümü nedir?","b":"Şiirin giriş bölümüdür; bahar, bayram gibi konularda betimlemeler yapılır; afakî bir konu işlenmişse teşbib de denir."},{"f":"Kasidenin girizgah bölümü nedir?","b":"Genelde tek beyittir; şair asıl konuya geçeceğini bildirir."},{"f":"Kasidenin methiye bölümü nedir?","b":"Asıl konunun, yani kasidenin sunulduğu kişinin övüldüğü bölümdür."},{"f":"Kasidenin tegazzül bölümü nedir?","b":"Kasidenin içinde gazel söylenen bölümdür."},{"f":"Kasidenin fahriye bölümü nedir?","b":"Şairin kendini ve sanatını övdüğü bölümdür."},{"f":"Kasidenin dua bölümü nedir?","b":"İyi dilek bölümüdür."},{"f":"Kaside kaç şekilde isimlendirilebilir?","b":"İşlediği konuya (tevhit, naat, methiye...), nesib bölümünün konusuna (bahariye, şitaiye...), redife (su kasidesi) veya kafiye harfine (raiyye) göre isimlendirilebilir."},{"f":"Mesnevi nedir?","b":"İran edebiyatından geçen, aruzun kısa kalıplarıyla yazılan, her beytin kendi arasında kafiyelendiği (aa/bb/cc...) nazım biçimidir."},{"f":"Mesnevilerin günümüzde hangi türün görevini üstlendiği söylenir?","b":"Hikâye ve romanın görevini üstlenmiştir; mekan, zaman, olay ve kişilerle anlatılır."},{"f":"Mesnevilerde konu bakımından neler işlenir?","b":"Destanlar, manzum tarihler, aşk hikâyeleri, ahlaki-didaktik konular, ilim, mizahi konular ve şehir güzellikleri (şehrengiz) işlenir."},{"f":"Türk edebiyatındaki ilk mesnevi hangisidir?","b":"Yusuf Has Hacip'in Kutadgu Bilig adlı yapıtı."},{"f":"Hamse nedir?","b":"Aynı yazarın yazdığı beş mesneviden oluşan mesnevi külliyatına verilen addır."},{"f":"Hamse sahibi ilk sanatçılar kimlerdir?","b":"İran edebiyatında Genceli Nizami, Osmanlı sahasında Hamdullah Hamdi, Türk edebiyatında ise ilk hamse sahibi Ali Şir Nevai'dir."},{"f":"Nergisi'nin hamsesi diğerlerinden nasıl farklıdır?","b":"Nergisi'nin hamsesi mensurdur, yani düzyazı ile yazılmıştır."},{"f":"Kıta nedir?","b":"En az iki beyitten oluşan nazım biçimidir; gazele benzer ama matla beyti ve mahlas yoktur."},{"f":"Kıta konu bakımından neleri işler?","b":"Yergi, nükte, övgü, hayat görüşü, hikmet gibi konuları işler; muamma ve hicviye de bu biçimle yazılabilir."},{"f":"Müstezat nedir?","b":"Gazelden türemiş, uzun bir dize ile ona eklenen kısa bir dizeden (ziyade) oluşan nazım biçimidir."},{"f":"Rubai nedir?","b":"Fars edebiyatından geçen, tek dörtlükten (aaxa kafiyeli) oluşan, tasavvuf-felsefe gibi konuları işleyen, genelde mahlassız bir nazım biçimidir."},{"f":"Rubai türünün önemli şairleri kimlerdir?","b":"İran'da Ömer Hayyam; Türk edebiyatında Azmizade Haleti, Kara Fazlı, Yahya Kemal, Arif Nihat, Ümit Yaşar."},{"f":"Tuyuğ nedir?","b":"Divan şiirine Türklerin kazandırdığı, sadece Türk edebiyatında görülen, tek dörtlükten oluşan nazım biçimidir; en çok Kadı Burhanettin yazmıştır."},{"f":"Şarkı (divan edebiyatı) nedir?","b":"Divan şiirine Türklerin kazandırdığı, bestelenmek için yazılan; halk edebiyatındaki türkünün karşılığı olan, 3-5 bentlik nazım biçimidir."},{"f":"Şarkıda miyan ve nakarat nedir?","b":"Her bendin üçüncü dizesine miyan (miyanhane), her bendin sonunda tekrarlanan dizeye nakarat denir."},{"f":"Şarkı türünün önemli şairleri kimlerdir?","b":"İlk örneklerini Naili, en güzel örneklerini Nedim, en çok şarkıyı Enderunlu Vasıf yazmıştır; Yahya Kemal de örnekler vermiştir."},{"f":"Terkibibent nedir?","b":"Hane adı verilen 5-10 beyitlik bentlerden (bent sayısı 5-15) oluşan; her bendin sonundaki vasıta beyti değişen nazım biçimidir."},{"f":"Terciibent nedir?","b":"Terkibibent gibi hane bentlerden oluşan ama vasıta beyti hiç değişmeyen nazım biçimidir."},{"f":"Terkibibent ile terciibent arasındaki fark nedir, önemli şairleri kimlerdir?","b":"Terkibibentte vasıta beyti her bentte değişir (en ünlüsü Bağdatlı Ruhi'nin terkibibendi); terciibentte hiç değişmez (en ünlüsü Ziya Paşa'nın terciibendi)."},{"f":"Musammat nedir?","b":"Dörtlük ya da daha fazla dizelik bentlerle kurulan divan edebiyatı nazım biçimlerine verilen genel addır."},{"f":"Murabba nedir?","b":"Dört dizelik bentlerden oluşan musammattır; övgü, yergi, mersiye, didaktik konularda yazılabilir."},{"f":"Muhammes nedir?","b":"Beş dizelik bentlerden oluşan musammattır; genelde felsefi düşünceler ve tasavvuf konusu işlenir."},{"f":"Tahmis ve tesdis nedir?","b":"Tahmis: bir gazelin beyitlerinin başına üçer dize eklenerek 5 dizeye çıkarılması. Tesdis: dört dize eklenerek 6 dizeye çıkarılmasıdır."},{"f":"Müseddes nedir?","b":"Altı dizelik bentlerden oluşan musammattır."},{"f":"Terzarima nedir?","b":"3 dizeli bentlerden ve sonda bir bağımsız dizeden oluşan, örüşük kafiyeli (aba/bcb/cdc...) bir biçimdir; ilk kez Dante kullanmıştır."},{"f":"Triyole nedir?","b":"Üçleme anlamına gelen, sekizer dizelik bir ya da birden fazla bentten oluşan; Türk edebiyatında fazla kullanılmamış bir biçimdir."},{"f":"Sone nedir?","b":"İki dörtlük ve iki üçlükten oluşan (4 bent, 14 dize) bir nazım biçimidir; kaynağı tartışmalıdır, hem İtalyanlar hem Fransızlar kendilerine ait sayar."},{"f":"Türk edebiyatında soneyi ilk kullanan ve ilk sone kitabını yayımlayan şairler kimlerdir?","b":"İlk kullanan Süleyman Nesip, ilk sone kitabını (106 sone) yayımlayan Edip Ayel'dir."},{"f":"Balad nedir?","b":"Halk şarkıları ya da romantik duygulu şarkı güftesi anlamına gelen, Türk edebiyatında pek görülmemiş bir batı nazım biçimidir."},{"f":"Serbest müstezat nedir?","b":"Geleneksel müstezatın bozulmasıyla oluşan, uzun-kısa dizelerin karışık kullanıldığı, kafiye düzeni sistemsiz bir biçimdir; Servetifünun'da kullanılmıştır."},{"f":"Mani, koşma, semai, varsağı hangi edebiyata aittir?","b":"Mani anonim halk edebiyatına; koşma, semai, varsağı ve destan aşık edebiyatına aittir."},{"f":"Gazel, kaside, mesnevi hangi edebiyata aittir?","b":"Üçü de divan edebiyatı nazım biçimidir; hepsi beyitten oluşan biçimler grubundandır."},{"f":"Sone, terzarima, triyole, balad hangi edebiyata aittir?","b":"Batı etkisindeki Türk edebiyatı nazım biçimleridir."},{"f":"İlahi, nefes, deme, nutuk, devriye, şathiye hangi edebiyata aittir?","b":"Tekke (tasavvuf) edebiyatına ait nazım türleridir; biçim olarak genelde koşmaya benzerler."}]},{"id":"edb-5","name":"İslamiyet Öncesi ve Geçiş Dönemi","cards":[{"f":"Edebiyat tarihi neyi inceleyen bilim dalıdır?","b":"Edebi yapıtları, ait olduğu milletin duygu ve düşüncesindeki değişimleri nesnel olarak inceleyen bilim dalı; hem tarihle hem edebiyatla ilişkilidir."},{"f":"Türk edebiyatı dönemlere ayrılırken hangi ölçütler kullanılır?","b":"Dil anlayışı, dil coğrafyası, dini hayat (Şamanizm/Maniheizm-Budizm/İslamiyet) ve kültürel farklılaşma (göçebe-destan, İslam, Batı kültürü)."},{"f":"Türk edebiyatının üç büyük dönemi nedir?","b":"İslamiyet Öncesi Türk Edebiyatı, İslami Dönem Türk Edebiyatı, Batı Etkisindeki Türk Edebiyatı."},{"f":"İslamiyet öncesi Türk edebiyatı hangi dönemlere ayrılır?","b":"Sözlü Dönem ve Yazılı Dönem."},{"f":"Destanları inceleyen bilim dalına ne denir?","b":"Mitoloji."},{"f":"Mit nedir?","b":"Doğaüstü varlıkların eylemlerinin öyküsü; gerçek ve kutsal kabul edilir, genellikle bir yaratılışla ilgilidir."},{"f":"Mitler konu bakımından nasıl sınıflandırılır?","b":"Yaratılışla ilgili mitolojik mitler, tufanla ilgili mitler, kıyamet ve dünyanın sonuyla ilgili mitler."},{"f":"Sözlü dönem destanlarının başlıca özellikleri nelerdir?","b":"Toplumun ortak görüşünü yansıtır, olağanüstü öğeler içerir, kahramanları han/kral gibi seçkinlerdir, milli dil ve nazım ölçüsü kullanılır, anonimdirler."},{"f":"Destanlarda Gök-Börü (Kurt) motifi nedir?","b":"Türklerin hayat ve savaş gücünün sembolüdür; Göktürklerin soyunun Bozkurt'tan geldiğine inanılır (Bozkurt, Ergenekon Destanı)."},{"f":"Destanlarda Işık motifi neyi ifade eder?","b":"Semavi-dini bir motiftir; kahramanları ve evlendikleri kadınları kutsal bir ışık doğurur, Tanrının kutsadığını gösterir."},{"f":"Destanlarda Ağaç motifi hangi olaylarla bağlantılıdır?","b":"Kahramanların doğuşuyla ilgili beş elementten biridir; Oğuz Kağan'ın ikinci karısı ağaç kovuğunda, Ergenekon'da meyve veren ağaçlar önemlidir."},{"f":"Destanlarda Kırklar motifi nedir?","b":"Kültüre özgü, kalıplaşmış bir sayı motifidir (ör. kırk yiğit gibi anlatımlarda geçer)."},{"f":"Destanlarda Ok-Yay motifinin anlamı nedir?","b":"Savaş aracı olmasının yanında hukuki bir sembol ve haberleşme aracıdır; \"gümüş ok\" ve \"altın ay\" olarak da geçer."},{"f":"Destanlarda Büyü (Sihir) motifi hangi destanda önemlidir?","b":"Uygur Destanı'nda sihirli \"Yada Taşı\" cihan hakimiyeti sağlamada etkilidir; İslamiyet sonrası destanlarda da sihir motifi görülür."},{"f":"Destanlarda Pir motifi kimdir?","b":"Kahramanlara yol gösteren, deneyimli ve bilgili yaşlı kişidir; Oğuz Kağan'ın akıl hocası, sonraki destanlarda \"Hızır-i fani\" olarak geçer."},{"f":"Destanlarda Demir-Demircilik motifi neyi simgeler?","b":"Demir kutsaldır, demircilik saygın bir sanattır; Ergenekon Destanı'nda önemli motiflerdendir."},{"f":"Destanlarda Hızır motifi ne işe yarar?","b":"Türk halk kültürünün önemli bir ögesi olan Hızır, destan kahramanına yol gösterip yardım eder."},{"f":"Destan tiplerinden Alp tipi kimdir?","b":"Yiğit, cesur, kahramanlık ve asalet gösteren kişidir; Oğuz Kağan idealize eder, İslamiyet sonrası \"Alp-Eren\" tipine dönüşür."},{"f":"Destan tiplerinden Bilge tipi kimdir?","b":"\"Ak sakallı\", topluma manevi liderlik yapan, yönlendiren, öğütleriyle bilinen yaşlı kişidir."},{"f":"Destan tiplerinden Kadın tipi nasıl tasvir edilir?","b":"Soyun devamının kaynağı, yuvayı yapan, fedakâr ve sadakatli; erkeğin en büyük destekçisi olan kadındır."},{"f":"Türk destanlarının başlıca kaynakları hangi eserlerdir?","b":"Firdevsi'nin Şehnâme'si, Kaşgarlı Mahmut'un Divânü Lügati't-Türk'ü, Reşidüddin'in Câmi'ü't-Tevârih'i, Cüveyni'nin Cihan-Güşa'sı, Yazıcıoğlu'nun Selçukname'si, Ebulgazi Bahadır Han'ın Şecere-i Terakime ve Şecere-i Türk'ü."},{"f":"Altay-Yakut Türklerinin destanı hangisidir?","b":"Yaradılış Destanı."},{"f":"Saka Türklerinin destanları hangileridir?","b":"Alp Er Tunga Destanı ve Şu Destanı."},{"f":"Hun Türklerinin destanları hangileridir?","b":"Oğuz Destanı (Oğuz Kağan Destanı) ve Attila Destanı."},{"f":"Göktürklerin destanları hangileridir?","b":"Bozkurt Destanı ve Ergenekon Destanı."},{"f":"Uygur Türklerinin destanları hangileridir?","b":"Türeyiş Destanı, Göç Destanı ve Mani Dininin Kabulü Destanı."},{"f":"Yaradılış Destanı'nda yaratıcı tanrının adı nedir?","b":"Bay-Ülgen; Altay-Yakut Türklerine ait destanda dünyayı kötü ruh Erlik ile mücadele ederek yaratır."},{"f":"Alp Er Tunga kimdir?","b":"M.Ö. 7. yy'da yaşamış Saka hükümdarı; Firdevsi'nin Şehname'sinde \"Efrasiyab\" adıyla anılır, İranlılarla uzun süre savaşmıştır."},{"f":"Şu Destanı neyi anlatır?","b":"M.Ö. 4. yy'da yaşamış Türk hükümdarı Şu'nun, Makedonyalı İskender'in Asya seferi sırasındaki mücadelesini ve barışını anlatır (Saka Türkleri)."},{"f":"Oğuz Kağan Destanı hangi hükümdarın hayatını anlatır?","b":"Hun hükümdarı Mete'nin (M.Ö. 209-174) hayatını ve Türk birliğini kuruşunu anlatır."},{"f":"Bozkurt Destanı kısaca neyi anlatır?","b":"Göktürklerin, düşman saldırısında yok olan soylarının bir dişi kurttan (bozkurt) türeyerek yeniden çoğalmasını anlatır."},{"f":"Ergenekon Destanı neyi anlatır?","b":"Göktürklerin Ergenekon denen kapalı yerde nasıl çoğaldıklarını ve demir dağı eriterek oradan nasıl çıktıklarını anlatır."},{"f":"Satuk Buğra Han Destanı neyi konu alır?","b":"Türklerin İslamiyet'i kabulünü anlatan, Karahanlılar döneminde oluşmuş ilk İslami destandır."},{"f":"Manas Destanı hangi milletin destanıdır, özelliği nedir?","b":"Kırgızların destanıdır; dünyanın en uzun destanı sayılır, 7 bölümden oluşur, yarım uyaklı 7'li-8'li hece ölçüsüyle söylenmiştir."},{"f":"Köroğlu Destanı'nın özelliği nedir?","b":"Anadolu, Rumeli, Azerbaycan, Türkmenistan ve Özbekistan'a yayılmıştır; Köroğlu'nun serüvenlerini 24 farklı kolda anlatır."},{"f":"Sözlü dönem Türk şiirinin dil ve ölçü özellikleri nelerdir?","b":"Hece ölçüsüyle (çoğunlukla 7'li, 8'li) yazılmıştır; öz Türkçe kullanılmış, kafiye/redif önemsenmeden çoğu yarım kafiyeli söylenmiştir."},{"f":"Koşuk nedir?","b":"Aşk, doğa, yiğitlik konularının işlendiği, genellikle dört dizelik bentlerden oluşan sözlü şiir türüdür; koşma ve koşmalara kaynaklık etmiştir."},{"f":"Sav nedir?","b":"İslamiyet öncesi Türk edebiyatında atasözünün karşılığıdır; bir düşünce ya da deneyimi az sözcükle anlatan sözlerdir (bugünkü \"darb-ı mesel\")."},{"f":"Yenisey Yazıtları neden ilk yazılı ürün sayılmaz?","b":"Göktürk alfabesiyle yazılmış, Kırgızlara ait daha eski yazıtlardır ama tarihleri kesin değildir; bu yüzden ilk ürün olarak Orhun Yazıtları kabul edilir."},{"f":"Orhun (Göktürk) Yazıtları hangi üç anıttan oluşur?","b":"Kül Tigin, Bilge Kağan ve Tonyukuk anıtları (8. yüzyıl, II. Göktürk Devleti)."},{"f":"Orhun Yazıtları'nın Türk edebiyatındaki önemi nedir?","b":"Türk edebiyatının ilk yazılı ürünleri ve ilk söylev örneğidir; 38 harfli Göktürk alfabesiyle yazılmıştır, dili öz ve ulusaldır."},{"f":"Kül Tigin ve Bilge Kağan yazıtlarını kim yazmıştır?","b":"Yolluğ Tigin; Tonyukuk Yazıtı'nı ise Tonyukuk kendisi yazdırmıştır."},{"f":"Uygur döneminin bilinen ilk şairi kimdir?","b":"Aprınçur Tigin."},{"f":"Uygur dönemi eserlerinin genel özelliği nedir?","b":"Daha çok dini içeriklidir (Maniheizm ve Budizm esaslı), 18 harfli Uygur alfabesiyle yazılmıştır, çoğu Çinceden çevrilmiştir."},{"f":"Altun Yaruk nedir?","b":"Uygur dönemi eseri; Çinceden çevrilmiş, Budizm'in ilkelerini ve öykülerini anlatan on kitaplık dini-ahlaki bir yapıttır."},{"f":"Irk Bitig nedir?","b":"Göktürk (Runik) alfabesiyle yazılmış, 65 paragraftan oluşan Uygur dönemi fal kitabıdır."},{"f":"Kutadgu Bilig'i kim, kime sunmuştur?","b":"Yusuf Has Hacip; 11. yüzyılda Karahanlı hükümdarı Tabgaç Buğra Han'a sunmuştur."},{"f":"Kutadgu Bilig'in edebiyat tarihindeki önemi nedir?","b":"İslamiyet dönemi Türk edebiyatının ilk yapıtıdır; ilk mesnevi ve ilk siyasetnamedir, aruzla yazılmıştır, 6645 beyittir."},{"f":"Kutadgu Bilig'deki dört sembolik kahraman kimi temsil eder?","b":"Kün Togdı (hükümdar): adalet-hukuk; Ay Toldı (vezir): saadet-mutluluk; Ögdilmiş (vezirin oğlu): akıl-zekâ; Odgurmış (derviş): kanaat-akıbet."},{"f":"Divanü Lügati't-Türk'ü kim, ne amaçla yazmıştır?","b":"Kaşgarlı Mahmut; Araplara Türkçe öğretmek ve Türkçenin Arapçayla boy ölçüşebilecek bir dil olduğunu göstermek için yazmıştır."},{"f":"Divanü Lügati't-Türk hangi tarihte tamamlanmıştır, önemi nedir?","b":"1072-1077 yıllarında tamamlanmıştır; Türkçenin ilk sözlüğüdür, sav-sagu-koşuk örnekleri ve destan parçaları da içerir."},{"f":"Atabetü'l Hakayık'ı kim yazmıştır?","b":"Edip Ahmet Yükneki; \"Hakikatlerin Eşiği\" anlamına gelir, dini-ahlaki, dörtlüklerden oluşan didaktik bir yapıttır."},{"f":"Divan-ı Hikmet'in yazarı ve konusu nedir?","b":"Ahmet Yesevi; tasavvuf edebiyatının ilk örneğidir, dörtlük nazım birimiyle yazılmıştır, şiirlerine \"hikmet\" denir."},{"f":"Kitab-ı Dede Korkut nedir?","b":"Oğuz Türklerinin yaşayışını anlatan, bir önsöz ve 12 hikayeden oluşan; yazarı bilinmeyen, 15. yy'da yazıya geçirilmiş destansı halk hikayeleridir."},{"f":"Battalname neyi anlatır?","b":"8. yy'da yaşayan Battal Gazi'nin İslamiyet uğruna Bizanslılarla yaptığı savaşları anlatan anonim bir halk hikayesidir."},{"f":"Danişmentname neyi konu alır?","b":"Battal Gazi torunlarından Danişment Gazi Ahmet Ali'nin Anadolu seferlerini ve savaşlarını anlatan 14. yy eseridir."},{"f":"Nasrettin Hoca kimdir, fıkralarının özelliği nedir?","b":"13. yy'da Sivrihisar'da yaşamış mutasavvıf; fıkraları güldürücü, düşündürücü ve öğreticidir, hepsi ona ait olmayıp zamanla eklenmiştir."}]},{"id":"edb-6","name":"Halk Edebiyatı","cards":[{"f":"Halk edebiyatının başlıca üç ana başlığı nedir?","b":"Anonim (Ortak) Halk Edebiyatı, Aşık Edebiyatı, Tekke (Dini-Tasavvufi) Halk Edebiyatı."},{"f":"Halk edebiyatının genel dil ve ölçü özellikleri nelerdir?","b":"Dil yalın, açık, akıcıdır; aruz kullanan olsa da hece ölçüsü yaygındır; yarım ve cinaslı uyak sıkça görülür, şiir düzyazıdan önde gelir."},{"f":"Anonim halk edebiyatı ürünlerinin ortak özelliği nedir?","b":"Kim tarafından yaratıldığı bilinmeyen, ağızdan ağza kuşaktan kuşağa aktarılan sözlü ürünlerdir; nazım birimi dörtlüktür."},{"f":"Anonim halk edebiyatının başlıca ürünleri nelerdir?","b":"Maniler, türküler, masallar, halk hikayeleri, ninniler, ağıtlar, bilmeceler, tekerlemeler, atasözleri, deyimler, meddah ve karagöz gibi oyunlar."},{"f":"Efsane nedir?","b":"Kendine özgü kalıplaşmış bir biçimi olmayan, düz konuşma diliyle anlatılan, gerçek olduğuna inanılan sözlü anlatı türüdür."},{"f":"Efsaneler konu bakımından nasıl sınıflandırılır?","b":"Yaratılış ve dünyanın sonuyla ilgili, tarihi/medeniyet tarihiyle ilgili, olağanüstü varlık ve güçlerle ilgili, dini efsaneler."},{"f":"Halk hikayesi nedir, ne zaman ortaya çıkmıştır?","b":"16. yüzyıldan itibaren destanın yerini alan, nazım-nesir karışık, olağanüstülüğü sınırlı, mutlu sonla biten anlatı türüdür."},{"f":"Halk hikayelerinde kahramanlar genellikle nasıl aşık olur?","b":"Bade içerek, resimde görüp, ilk görüşte ya da aynı evde büyüyüp kardeş olmadıklarını sonradan öğrenerek aşık olurlar."},{"f":"Aşk konulu halk hikayelerine örnekler nelerdir?","b":"Aşık Garip, Tahir ile Zühre, Kerem ile Aslı, Ferhat ile Şirin, Leyla ile Mecnun (bir kısmı divan mesnevilerinden alınmıştır)."},{"f":"Kahramanlık konulu halk hikayelerine örnekler nelerdir?","b":"Köroğlu, Battal Gazi, Dede Korkut Hikayeleri; tarihi-dini nitelik taşırlar."},{"f":"Fıkra nedir?","b":"Kıssadan hisse anlayışına dayanan, sözlü edebiyatta nesir diliyle anlatılan, kısa ve yoğun bir anlatım gücüne sahip mizahi hikayelerdir."},{"f":"Fıkra, hangi yönüyle halk hikayesine benzer?","b":"Bir olaya bağlı olarak anlatıldıkları için güldürücü unsurlar taşımaları yönünden halk hikayesine benzerler."},{"f":"Türk edebiyatında ünlü fıkra tipleri kimlerdir?","b":"Nasrettin Hoca, İncili Çavuş, Bekri Mustafa ve Bektaşi tipi fıkralar yaygındır."},{"f":"Atasözü (sav) nedir?","b":"Uzun deneyimlere dayanan yargıları genel kural, bilgece düşünce ya da öğüt olarak düsturlaştıran, kalıplaşmış özlü sözlerdir."},{"f":"Deyim nedir?","b":"Bir kavramı, durumu çekici bir anlatımla ya da özel bir yapı içinde belirten, çoğunun gerçek anlamından ayrı bir anlamı olan kalıplaşmış sözcük öbeğidir."},{"f":"Atasözü ile deyim arasındaki temel fark nedir?","b":"Atasözleri bir yargı ya da öğüt bildiren tam cümlelerdir; deyimler en az iki sözcükten oluşur, genellikle mastar biçimindedir ve çekimlenebilir."},{"f":"Geleneksel Türk halk tiyatrosunun türleri nelerdir?","b":"Orta oyunu, karagöz (gölge oyunu), köy seyirlik oyunları ve meddah."},{"f":"Meddah nedir?","b":"Tek kişilik bir oyuncunun, canlandırma ve benzetme yoluyla çeşitli kişileri taklit ederek öykü anlattığı gösteri sanatıdır; dekor kullanmaz."},{"f":"Meddah oyunu nasıl biter?","b":"Meddah, oyun sonunda \"kıssadan hisse\" vererek anlatısını tamamlar."},{"f":"Ünlü meddahlara örnek verir misin?","b":"Tıflî Ahmet Çelebi, Kız Ahmed, Aşkî, Sürûrî, Kör Hasan, Hacı Kıssahan, Meddah Eğlence, Çokyedi Reis."},{"f":"Karagöz oyunu (gölge oyunu) nedir?","b":"Deriden kesilen \"tasvir\" denen figürlerin ışıklandırılmış beyaz bir perdeye yansıtılmasına dayanan geleneksel gösteri oyunudur."},{"f":"Karagöz oyununu oynatan sanatçıya ne denir?","b":"Karagözcü (hayali/hayalbaz); yardımcısına çırak, çırağın yardımcısına sandıkar denir."},{"f":"Karagöz ve Hacivat karakterleri nasıl temsil edilir?","b":"Karagöz saf, zeki, okumamış halk tipini; Hacivat bildikleriyle gösteriş yapan, Arapça-Farsça sözcük kullanan sahte aydını simgeler."},{"f":"Karagöz oyunu kaç bölümden oluşur, isimleri nedir?","b":"Dört bölümden oluşur: Mukaddime (giriş), Muhavere (karşılıklı konuşma), Fasıl (asıl konu), Bitiş."},{"f":"Karagöz oyununun Fasıl bölümü ne işe yarar?","b":"Oyunun asıl konusunun anlatıldığı bölümdür; Ağalık, Yalova Sefası, Kanlı Kavak gibi çeşitli isimler alır."},{"f":"Orta oyunu nedir?","b":"Halkın etrafını çevrelediği bir meydanda, ezbersiz ve suflörsüz oynanan; kol oyunu, meydan oyunu, zuhuri de denen bir gösteri türüdür."},{"f":"Orta oyununun iki temel kişisi kimdir?","b":"Kavuklu (Karagöz'ün karşılığı) ve Pişekar (Hacivat'ın karşılığı)."},{"f":"Orta oyunu kaç bölümden oluşur?","b":"Dört bölümden oluşur: Mukaddime, Muhavere (Arzbar ve Tekerleme diye ikiye ayrılır), Fasıl, Bitiş."},{"f":"Köy seyirlik oyunları nedir?","b":"Yılın belli günlerinde, düğünlerde, bayramlarda oynanan; taklide dayanan, yazılı metni olmayan, halkın hazırlıksız oynadığı oyunlardır."},{"f":"Aşık edebiyatı nedir, nasıl ortaya çıkmıştır?","b":"Aşık adı verilen halk ozanlarının din dışı konuları işleyip sazıyla söylediği şiirlerden oluşur; İslamiyet öncesi ozan geleneğinin devamıdır."},{"f":"Aşıkların şiirlerinin toplandığı deftere ne ad verilir?","b":"Cönk."},{"f":"Aşık edebiyatının başlıca nazım şekilleri nelerdir?","b":"Koşma, semai, destan, varsağı."},{"f":"Aşık, şiirinin son dörtlüğünde ne yapar?","b":"\"Tapşırma\" adı verilen mahlasını (adını) söyler."},{"f":"Kalem şuarası kimdir?","b":"Hece ve aruz ölçüsünü bilen ama saz çalmayı bilmeyen, öğrenim görmüş halk şairleridir (ör. Bayburtlu Zihni, Çankırılı Zahmi)."},{"f":"Saz şairi (aşık) kimdir?","b":"Genellikle saz eşliğinde doğaçlama şiir söyleyen, çoğu okuma yazma bilmeyen ya da öğrenim görmemiş şairdir; şiirlerini hece ölçüsüyle söyler."},{"f":"Köroğlu hangi konularda şiir yazmıştır?","b":"16-17. yy; yiğitlik ve kahramanlık konularını işlediği koçaklamalarıyla ünlenmiştir; kimliği kesin bilinmez, hece ölçüsünü kullanmıştır."},{"f":"Kayıkçı Kul Mustafa'nın en ünlü şiiri hangisidir?","b":"17. yy; Bağdat'ın kuşatılması sırasında şehit düşen Genç Osman için yazdığı \"Genç Osman\" destanıdır."},{"f":"Aşık Ömer kimdir?","b":"17. yy; ordu ve gezici saz şairidir; hem hece hem aruz kullanmış, \"Şairname\" adlı uzun şiiriyle edebiyat tarihine kaynaklık etmiştir."},{"f":"Karacaoğlan'ın şiirlerinin başlıca özelliği nedir?","b":"16-17. yy, göçebe Türkmen aşiretinden; aşk, tabiat, ayrılık, güzeller gibi konularda güzellemeleriyle tanınan en lirik aşık şairidir."},{"f":"Gevheri kimdir?","b":"18. yy aşık şairi; divan tarzında da eser vermiş, hem hece hem aruz ölçüsünü kullanmıştır, şiirlerinde aşk acısını anlatmıştır."},{"f":"Bayburtlu Zihni'nin dikkat çeken özelliği nedir?","b":"19. yy; halk şairi olmasına rağmen kaside, gazel gibi divan nazım şekillerini de kullanmış, koşma ve taşlamalarıyla tanınmıştır."},{"f":"Dertli hangi edebiyat geleneklerini birleştirmiştir?","b":"19. yy; hem aruz hem hece ölçüsünü kullanmış Bektaşi bir şairdir; tekke ve divan edebiyatını iyi bilen bir aşık şairidir."},{"f":"Dadaloğlu'nun şiirlerinde işlediği temel tema nedir?","b":"19. yy; Türkmenlerin özgürlük sembolüdür, koçaklama türündeki şiirleriyle tanınır, iskan politikasına karşı isyan teması işler."},{"f":"Erzurumlu Emrah'ın özelliği nedir?","b":"19. yy; kendi adıyla anılan bir aşık kolunun kurucusudur, gezgin bir derviş-saz şairidir, koşma ve semailerde başarılıdır."},{"f":"Seyrani hangi tür şiirleriyle tanınmıştır?","b":"19. yy; taşlamalarıyla tanınmıştır, yergi ve gülmece şiirleri halk edebiyatında bu türün en başarılı örnekleri sayılır."},{"f":"Aşık Veysel kimdir?","b":"1894-1971; çocukken gözlerini kaybetmiştir, aşık edebiyatının son büyük temsilcisi sayılır; toprak sevgisi, Atatürk, kardeşlik konularını işlemiştir."},{"f":"Aşık Veysel'i edebiyata kim tanıtmıştır?","b":"Ahmet Kutsi Tecer."},{"f":"Aşık Mahzuni Şerif'in şiirlerinin özelliği nedir?","b":"Siyasal içerikli şiirleri yüzünden kovuşturmaya uğramıştır; \"İşte Gidiyorum\", \"Bizden Geriler\" gibi eserleri ünlüdür."},{"f":"Neşet Ertaş hangi gelenekle özdeşleşmiştir?","b":"Saz ustası Muharrem Ertaş'ın geleneğini sürdürerek \"Bozkırın Tezenesi\" olarak anılmıştır."},{"f":"Tekke edebiyatı (dini-tasavvufi halk edebiyatı) nedir?","b":"İslamiyet'in ilkelerine dayanarak nefsi arıtıp ahlakı güzelleştirerek Allah'a ulaşma düşüncesi olan tasavvufu konu alan edebiyattır."},{"f":"Tekke edebiyatının nazım birimi ve ölçüsü nedir?","b":"Nazım birimi dörtlüktür, gazel biçiminde ilahiler de vardır; hem hece hem aruz ölçüsü kullanılmıştır."},{"f":"Tekke edebiyatının başlıca nazım türleri nelerdir?","b":"İlahi, nefes, deme, şathiye, devriye, nutuk."},{"f":"Tasavvufta \"aşk\" kavramı ne ifade eder?","b":"Allah'ı bilme isteğidir; hakiki aşk Allah aşkıdır, insana ve dünyaya duyulan aşk ise mecazi (beşeri) aşktır."},{"f":"Tasavvufta \"fenafillah\" ne demektir?","b":"\"Ölmeden önce ölmek\"; kişinin nefsini yenip Allah'ın varlığında kendi varlığını yok etmesi, Allah'a dönüşmesidir."},{"f":"Tasavvufta \"vahdet-i vücut\" ne demektir?","b":"Bütün varlıkların Allah'ın birliğinden ibaret olduğu, O'nun dışında gerçek bir varlık olmadığı inancıdır."},{"f":"Tasavvufta mürit ve mürşit kimdir?","b":"Mürit, bir şeyhe bağlanıp Allah'a ulaşmaya çalışan kişidir. Mürşit, müritlere yol gösteren tarikat piridir (şeyh)."},{"f":"Yunus Emre kimdir?","b":"1240/41-1320; Tapduk Emre'ye bağlanan mutasavvıf şairdir; sade Türkçeyle hem hece hem aruzla yazmıştır, Divan ve Risaletü'n-Nushiyye'si vardır."},{"f":"Hacı Bektaş-ı Veli'nin edebiyattaki yeri nedir?","b":"13. yy; Bektaşi tarikatının kurucusudur; düzyazı türünde \"Makalat\" adlı dini-tasavvufi yapıtıyla tanınır."},{"f":"Hacı Bayram Veli kimdir?","b":"1352-1429; Ankara'da \"Bayramiye\" tarikatını kurmuştur; elimizde aruzla iki, heceyle üç şiiri vardır."},{"f":"Kaygusuz Abdal'ın şiirlerindeki dikkat çeken özellik nedir?","b":"15. yy; Alevi-Bektaşi edebiyatının önde gelen şairlerindendir; nefeslerinde mizahi motiflerle sofuları alaya almıştır."},{"f":"Pir Sultan Abdal kimdir?","b":"16. yy; Sivas Banaz köyünden, Sivas valisi Hızır Paşa tarafından asıldığı söylenir; Alevi-Bektaşi şiirinin en büyük ustalarındandır."},{"f":"Erzurumlu İbrahim Hakkı'nın ünlü yapıtı hangisidir?","b":"1703-1772; ansiklopedik nitelikte \"Marifetname\" adlı yapıtıyla tanınan araştırmacı-mutasavvıf bir şairdir."},{"f":"Dini-tasavvufi türlerden tevhit ve münacat ne anlatır?","b":"Tevhit, Allah'ın birliğini anlatan şiirdir. Münacat, Allah'a yalvarış ve dua şiiridir."}]},{"id":"edb-7","name":"Divan Edebiyatı","cards":[{"f":"Divan edebiyatı hangi yüzyıllar arasında var olmuştur?","b":"13. yüzyılda başlamış, 19. yüzyıl sonunda sona ermiştir."},{"f":"Divan edebiyatına verilen diğer isimler nelerdir?","b":"Saray edebiyatı, yüksek zümre edebiyatı, medrese edebiyatı, havas edebiyatı, klasik Türk edebiyatı."},{"f":"Divan şiirinde nazım birimi ve ölçü nedir?","b":"Nazım birimi genellikle beyittir (dörtlük ve bent de kullanılır); ölçü aruzdur."},{"f":"Divan şiirinde mahlas nedir?","b":"Şairlerin genellikle son beyit veya dörtlükte kullandığı takma isimdir."},{"f":"Divan şiirinde 'konu' ile ilgili temel anlayış nedir?","b":"Konu değil, konunun işlenişi önemlidir; bütünlük aranmaz, her beyit ayrı konu işleyebilir."},{"f":"Divan edebiyatında nazire ve tehzil nedir?","b":"Nazire, bir şiire aynı ölçü ve kafiyeyle yazılan başka şiirdir; alay amaçlı yazılan nazireye tehzil denir."},{"f":"Divan edebiyatının kaynakları nelerdir?","b":"Kur'an, hadis, tasavvuf, şehname, İslam-Türk tarihi ve kültürü, halk edebiyatı unsurlarıdır."},{"f":"Divan nesri kaça ayrılır, nelerdir?","b":"Sade (nesir), orta düzyazı ve sanatlı (süslü nesir/inşa) olmak üzere üçe ayrılır."},{"f":"Süslü nesrin (inşa) kurucusu ve önemli temsilcileri kimlerdir?","b":"Kurucusu Sinan Paşa'dır (Tazarruname); Nergisi ve Veysi diğer önemli temsilcileridir."},{"f":"Tevhit ve münacat nedir?","b":"Tevhit Allah'ın birliğini ve yüceliğini anlatan; münacat Allah'a yalvarış ve yakarışı konu alan şiirdir."},{"f":"Naat nedir, en önemli örneği hangisidir?","b":"Hz. Muhammed'i öven şiirdir; Fuzuli'nin 'Su Kasidesi' en önemli örneğidir."},{"f":"Methiye ve fahriye arasındaki fark nedir?","b":"Methiye başkasını, fahriye şairin kendini övdüğü şiirdir; ikisinde de en ünlü isim Nefi'dir."},{"f":"Hicviye nedir, en önemli şairi kimdir?","b":"Bir kişi ya da kurumu yeren şiirdir; edebiyatımızın en önemli hiciv şairi Nefi'dir."},{"f":"Mersiye nedir, önemli bir örneği hangisidir?","b":"Ölüm üzerine duyulan üzüntüyü anlatan şiirdir; Baki'nin 'Kanuni Mersiyesi' önemli bir örneğidir."},{"f":"Mevlit nedir?","b":"Hz. Muhammed'in doğumunu ve hayatını öven, genellikle mesnevi biçiminde yazılan şiirdir."},{"f":"Hilye nedir, en önemli örneği kimindir?","b":"Hz. Muhammed'in güzelliklerini anlatan şiirdir; en önemlisi Hakani Mehmet Bey'in 712 beyitlik Hilye'sidir."},{"f":"Şehrengiz nedir, ilk örneğini kim yazmıştır?","b":"Bir şehrin güzelliklerini anlatan mesnevidir; ilk örneğini 16. yüzyılda Mesihi yazmıştır."},{"f":"Surname nedir?","b":"Şehzade sünnet düğünleri ile hanım sultan evliliklerini konu alan şiir veya düzyazıdır."},{"f":"Kıyafetname nedir, en önemli örneği hangisidir?","b":"Kişilerin dış görünüşünden karakterleri hakkında yorum yapan yapıttır; Erzurumlu İbrahim Hakkı'nın Marifetname'sinde de bu tür bir bölüm vardır."},{"f":"Siyer nedir, Türk edebiyatındaki ilk örneği hangisidir?","b":"Hz. Muhammed'in hayatını anlatan yapıttır; ilk örneği Erzurumlu Darir'in 'Siretü'n-Nebi' çevirisidir."},{"f":"Tezkire nedir?","b":"Edebiyatçıların hayat hikâyelerini ve eserlerini anlatan biyografik eserdir."},{"f":"Türk edebiyatındaki ilk şairler tezkiresi kimindir?","b":"Ali Şir Nevai'nin 'Mecalisü'n-Nefais' adlı eseridir."},{"f":"Osmanlı sahasında yazılan ilk şair tezkiresi hangisidir?","b":"Sehi Bey'in 'Heşt Behişt' (Tezkire-i Sehi) adlı eseridir."},{"f":"Cumhuriyet döneminde tezkire geleneğini sürdüren eser hangisidir?","b":"İbnülemin Mahmut İnal'ın 'Son Asır Türk Şairleri' adlı eseridir."},{"f":"Münşeat ve letaifname nedir?","b":"Münşeat mektup ve resmî yazıların, letaifname fıkra ve mizahi metinlerin bir araya toplandığı yapıttır."},{"f":"Seyahatname nedir, en önemli örneği kimindir?","b":"Gezilen yerleri anlatan yapıttır; en önemli örneği Evliya Çelebi'nin 'Seyahatname'sidir."},{"f":"Sefaretname nedir, karakteristik örneği hangisidir?","b":"Elçi olarak gidilen ülkeyi anlatan yapıttır; Yirmisekiz Çelebi Mehmet'in 'Fransa Sefaretnamesi' örnektir."},{"f":"Siyasetname ve fütüvvetname nedir?","b":"Siyasetname devlet yönetimine öğüt veren, fütüvvetname ahilik esaslarını ve esnaf ahlakını anlatan yapıttır."},{"f":"Türki-i Basit akımının öncüsü ve amacı nedir?","b":"Öncüsü Aydınlı Visali'dir; Arapça-Farsça sözcüklerden kaçınıp sade Türkçe kullanmayı amaçlamıştır."},{"f":"Sebk-i Hindi ne demektir, ne zaman görülmüştür?","b":"'Hint üslubu' anlamına gelir; Türk şiirinde 17. yüzyılda görülmeye başlamış, en çok gazelde etkili olmuştur."},{"f":"Sebk-i Hindi'nin temsilcileri kimlerdir?","b":"Naili, Neşati, Fehim ve Şeyh Galip'tir."},{"f":"Mahallileşme akımının en önemli temsilcisi kimdir?","b":"Nedim; İstanbul hayatını, eğlence yerlerini ve konuşma dilini şiire taşımıştır."},{"f":"Encümen-i Şuara ne zaman, nerede kurulmuştur?","b":"1861'de Hersekli Arif Hikmet'in Aksaray'daki evinde kurulmuştur."},{"f":"Hoca Dehhani kimdir?","b":"Din-dışı divan edebiyatının kurucusu kabul edilir; aşk, şarap ve tabiat konularını işlemiştir."},{"f":"Mevlana hangi dilde yazmıştır, mahlası nedir?","b":"Eserlerini Farsça yazmıştır; Divan-ı Kebir'de kendi mahlası yerine çoğunlukla hocası Şems-i Tebrizi'nin adını kullanmıştır."},{"f":"Mevlana'nın en önemli eseri hangisidir?","b":"'Mesnevi' (Mesnevi-i Manevi); altı ciltlik tasavvufi bir mesnevidir."},{"f":"Sultan Veled kimdir?","b":"Mevlana'nın oğludur; Mevlevilik tarikatını sistemleştiren, Türkçe-Farsça şiirler yazan şairdir."},{"f":"Şeyyad Hamza kimdir, eseri nedir?","b":"14. yüzyıl mutasavvıf şairidir; 'Yusuf u Züleyha' Türk edebiyatındaki ilk aşk konulu mesnevidir."},{"f":"Ahmet Fakih kimdir?","b":"Eski Anadolu Türkçesinin bilinen en eski şairidir; 'Çarhname' adlı eseriyle tanınır."},{"f":"Seyyid Nesimi kimdir, nasıl ölmüştür?","b":"Hurufilik tarikatına mensup şairdir; görüşleri yüzünden Halep'te derisi yüzülerek öldürülmüştür."},{"f":"Gülşehri kimdir, eseri nedir?","b":"Kırşehirli mevlevi şairdir; 'Mantıku't-Tayr' adlı vahdet-i vücut konulu alegorik mesnevisiyle tanınır."},{"f":"Aşık Paşa kimdir, eseri nedir?","b":"Anadolu'da Türkçe eser veren ilk mutasavvıf şairlerdendir; 'Garipname' adlı ünlü mesnevisi vardır."},{"f":"Ahmedi kimdir, eseri nedir?","b":"Divan edebiyatının kurucularından biridir, din-dışı şiirler yazmıştır; 'İskendername' adlı eseriyle tanınır."},{"f":"Kadı Darir kimdir, eseri nedir?","b":"Doğuştan kör Erzurumlu bir şairdir; 'Siyer-i Nebi', nesirle yazılan ilk siyer örneğidir."},{"f":"Ali Şir Nevai kimdir, önemi nedir?","b":"Çağatay edebiyatının ünlü şairidir; Çağatay Türkçesini büyük bir edebiyat diline dönüştürmüş, edebiyatımızın ilk hamse sahibidir."},{"f":"Şeyhi kimdir, eseri nedir?","b":"15. yüzyıl şairidir; 'Harname' adlı hiciv türünde alegorik-sembolik mesnevisiyle tanınır."},{"f":"Ahmet Paşa kimdir?","b":"Fatih'in veziriyken idama mahkûm edilmiş, 'Kerem Kasidesi'ni yazarak kurtulmuştur."},{"f":"Süleyman Çelebi kimdir, eseri nedir?","b":"'Vesiletü'n-Necat' (Mevlit) adlı ünlü eseri 1409'da yazmıştır."},{"f":"Necati Bey kimdir?","b":"Divan şiirinde atasözü ve deyimleri kullanan ilk şairlerdendir; sade bir dil kullanmıştır."},{"f":"Hamdullah Hamdi kimdir?","b":"Hamse sahibi bir şairdir; Türk edebiyatındaki en güzel 'Yusuf u Züleyha' mesnevisini yazmıştır."},{"f":"Yazıcıoğlu Mehmet kimdir, eseri nedir?","b":"Hacı Bayram-ı Veli'ye bağlı şairdir; 'Muhammediye' adlı 10 bin beyitlik dini mesnevisiyle tanınır."},{"f":"Mercimek Ahmet kimdir?","b":"II. Murad'ın buyruğuyla 'Kabusname'yi Türkçeye çevirmiş, kattığı yorum ve açıklamalarla adeta telif eser hâline getirmiştir."},{"f":"Fuzuli'nin şiirlerindeki aşk anlayışı nasıldır?","b":"Beşeri aşktan yola çıkıp ilahi aşka ulaşır; tasavvufi bir aşk anlayışı taşımakla birlikte mutasavvıf değildir."},{"f":"Fuzuli'nin en ünlü mesnevisi hangisidir?","b":"'Leyla vü Mecnun'dur; beşeri aşktan ilahi aşka geçişi anlatan Türkçe mesnevisidir."},{"f":"Fuzuli'nin \"Şikayetname\"si nedir?","b":"Bağlanan maaşını alamayınca Nişancı Celalzade Mustafa Çelebi'ye yazdığı, edebiyatımızın en ünlü mektuplarından olan yergili düzyazısıdır."},{"f":"Baki'nin lakabı ve şairlik anlayışı nedir?","b":"'Sultanü'ş-şuara' olarak anılır; rint bir şairdir, şiirlerinde tasavvufa hemen hiç yer vermez."},{"f":"Baki'nin en ünlü şiiri hangisidir?","b":"Kanuni Sultan Süleyman'ın ölümü üzerine yazdığı terkib-i bent, 'Kanuni Mersiyesi'dir."},{"f":"Bağdatlı Ruhi kimdir?","b":"Toplumsal bozuklukları terkib-i bentle eleştiren şairdir; bu şiirine en ünlü nazireyi Ziya Paşa yazmıştır."},{"f":"Nefi kimdir, hangi türde en önemlidir?","b":"Erzurumlu şairdir; divan edebiyatının en önemli kaside ve hiciv şairidir."},{"f":"Nefi'nin 'Sihâm-ı Kazâ' adlı eseri ve olayı nedir?","b":"Hicivlerini topladığı bu eseri okuyan Sultan Murad'ın yakınına yıldırım düşmüş, Nefi hicivden men edilip Edirne'ye sürülmüştür."},{"f":"Nabi kimdir, getirdiği şiir tarzı nedir?","b":"Şiire düşünce unsurunu getiren didaktik şairdir; hikemi tarzda 'Nabi Mektebi'ni kurmuştur."},{"f":"Nabi'nin önemli eserleri nelerdir?","b":"Hayriyye (oğluna öğüt), Hayrabad (aşk konulu mesnevi), Tuhfetü'l-Haremeyn (hac izlenimleri)."},{"f":"Naili (Naili-i Kadim) kimdir?","b":"Sebk-i Hindi tarzını benimseyen 17. yüzyıl gazel şairidir; imge ve hayallerle yüklü, anlaşılması güç bir üslubu vardır."},{"f":"Neşati kimdir?","b":"Mevlevi şeyhi olan gazel şairidir; Nefi'yi üstat kabul edip ona nazireler yazmıştır."},{"f":"Katip Çelebi kimdir, önemli eseri nedir?","b":"Hacı Kalfa olarak da bilinir; 'Keşfü'z-Zünun', yaklaşık 15 bin Arapça yapıtı tanıtan bibliyografya eseridir."},{"f":"Naima kimdir?","b":"Vakanüvis (resmî tarihçi) olarak 'Naima Tarihi'ni yazmış, 1591-1659 olaylarını tarafsız biçimde anlatmıştır."},{"f":"Peçevi kimdir?","b":"'Peçevi Tarihi' adlı, Kanuni'den IV. Murad dönemine kadarki olayları anlatan tarih yazarıdır."},{"f":"Evliya Çelebi kimdir, eseri nedir?","b":"Türk edebiyatının en büyük gezi yazarıdır; 10 ciltlik 'Seyahatname'siyle tanınır."},{"f":"Veysi kimdir, eseri nedir?","b":"Süslü nesrin temsilcisidir; en meşhur eseri 'Siyer-i Veysi' (Dürretü't-Tac)'dır."},{"f":"Nergisi kimdir?","b":"Süslü nesrin (münşi) ünlü temsilcisidir; edebiyatımızda ilk mensur 'hamse'yi yazmıştır."},{"f":"Nedim kimdir, hangi dönemin şairidir?","b":"Lale Devri'nin şairidir; mahallileşme akımının en önemli temsilcisidir."},{"f":"Nedim hangi nazım türüyle öne çıkmıştır?","b":"Şarkı türüyle; 'Nedim'in Türküsü' hece ölçüsüyle yazılmış bir şiiridir."},{"f":"Şeyh Galip kimdir?","b":"Divan edebiyatının son büyük şairidir; Sebk-i Hindi akımının en önemli temsilcisidir."},{"f":"Şeyh Galip'in başyapıtı hangisidir?","b":"'Hüsn ü Aşk'; alegorik-sembolik, tasavvufi bir mesnevidir."},{"f":"Enderunlu Fazıl kimdir?","b":"Enderun'da yetişen, mesnevi tarzında manzum hikâyeler yazan şairdir (Hubanname, Zenanname)."},{"f":"Keçecizade İzzet Molla kimdir, eseri nedir?","b":"Şeyh Galip ve Nabi etkisindeki 19. yüzyıl şairidir; sürgün yaşamını anlatan 'Mihnet-i Keşan' ile tanınır."},{"f":"Enderunlu Vasıf kimdir?","b":"Mahallileşme akımının Nedim'den sonraki en büyük takipçisidir; günlük dili ve argoyu şiire taşımıştır."},{"f":"Kanuni, Fatih ve Yavuz Sultan Selim'in şiirde kullandığı mahlaslar nelerdir?","b":"Kanuni 'Muhibbi', Fatih Sultan Mehmet 'Avni', Yavuz Sultan Selim 'Selimi' mahlasını kullanmıştır."}]},{"id":"edb-8","name":"Tanzimat Edebiyatı","cards":[{"f":"Tanzimat edebiyatı hangi olayla başlar?","b":"1839'da Mustafa Reşit Paşa'nın ilan ettiği Tanzimat Fermanı (Gülhane Hattı Hümayunu) ile."},{"f":"Türk edebiyatının ilk özel gazetesi hangisidir?","b":"Tercüman-ı Ahval (1860, Şinasi ve Agâh Efendi çıkarmıştır)."},{"f":"Osmanlı'nın ilk resmî gazetesi hangisidir?","b":"Takvim-i Vakayi (1831, II. Mahmut döneminde, Tanzimat'tan önce çıkarılmıştır)."},{"f":"Tanzimat'ta öğretici metinlerde ilk kez hangi türler görülür?","b":"Makale, eleştiri, fıkra gibi Batılı düzyazı türleri."},{"f":"Türk edebiyatındaki ilk makale örneği nedir?","b":"Şinasi'nin Tercüman-ı Ahval gazetesindeki \"Mukaddime\" başlıklı yazısı."},{"f":"Türk edebiyatındaki ilk eleştiri kitabı nedir?","b":"Namık Kemal'in \"Tahrib-i Harabat\" adlı yapıtı (Ziya Paşa'nın Harabat'ına karşı yazılmıştır)."},{"f":"Tanzimat 1. Dönem şiirinde biçim ve içerik nasıldır?","b":"Biçim divan şiirinden devam eder (aruz, eski nazım şekilleri); içerik yenilenir (vatan, hürriyet, adalet gibi konular)."},{"f":"Tanzimat 1. Dönem şiirinde tek biçimsel yenilik nedir?","b":"Kasidenin klasik giriş bölümlerinin kaldırılıp doğrudan konuya geçilmesi."},{"f":"Tanzimat 2. Dönem şiiri 1. dönemden nasıl ayrılır?","b":"Konu bireyselleşir (ölüm, aşk, hiçlik, doğa); romantizm etkisi artar, biçimde yeni denemeler yapılır."},{"f":"Türk edebiyatının ilk çeviri romanı hangisidir?","b":"\"Telemak\" — Yusuf Kamil Paşa'nın 1859'da Fenelon'dan çevirdiği roman."},{"f":"Türk edebiyatının ilk yerli romanı hangisidir?","b":"\"Taaşşuk-ı Talat ve Fitnat\" — Şemsettin Sami, 1872."},{"f":"Türk edebiyatının ilk edebi (roman değeri taşıyan) romanı hangisidir?","b":"Namık Kemal'in \"İntibah\" adlı romanı."},{"f":"Türk edebiyatının ilk öykü örneği hangisidir?","b":"Ahmet Mithat Efendi'nin \"Letaif-i Rivayet\" adlı yapıtı."},{"f":"Batılı anlamda ilk öykü örnekleri kime aittir?","b":"Sami Paşazade Sezai'nin \"Küçük Şeyler\" adlı yapıtına."},{"f":"Tanzimat 1. Dönem romanlarının ortak kusuru nedir?","b":"Teknik açıdan zayıftır; olay akışı kesilerek uzun açıklamalara, gereksiz tasvirlere yer verilir."},{"f":"Tanzimat 2. Dönem roman ve öykülerinde ne değişmiştir?","b":"Realizm etkisi artmış, gözlem yoluyla gerçekçi betimlemeler yapılmış, olağanüstülükten kaçınılmıştır."},{"f":"Türk edebiyatının yazılan ilk yerli tiyatro yapıtı hangisidir?","b":"Şinasi'nin \"Şair Evlenmesi\" adlı komedisi."},{"f":"Türk edebiyatında sahnelenen ilk tiyatro yapıtı hangisidir?","b":"Namık Kemal'in \"Vatan yahut Silistre\" adlı dramı."},{"f":"I. Dönem Tanzimat sanatçıları kimlerdir?","b":"Şinasi, Namık Kemal, Ziya Paşa, Ahmet Mithat Efendi, Ahmet Vefik Paşa, Şemsettin Sami."},{"f":"II. Dönem Tanzimat sanatçıları kimlerdir?","b":"Abdülhak Hamit Tarhan, Recaizade Mahmut Ekrem, Sami Paşazade Sezai, Nabizade Nazım, Muallim Naci."},{"f":"Tanzimat 1. Dönem'in temel sanat görüşü nedir?","b":"\"Sanat, toplum içindir\"; halkı eğitmek ve bilinçlendirmek amaçlanır."},{"f":"Şinasi kimdir?","b":"Batı etkisindeki Türk ve Tanzimat edebiyatının kurucusu sayılır; klasisizm akımından etkilenmiştir."},{"f":"Şinasi Türk edebiyatına hangi ilkleri kazandırmıştır?","b":"İlk özel gazete (Tercüman-ı Ahval), ilk tiyatro yapıtı (Şair Evlenmesi), ilk makale, noktalama işaretlerinin ilk kullanımı."},{"f":"Şinasi şiirde neyi korumuş, neyi değiştirmiştir?","b":"Nazım şeklini ve aruz ölçüsünü divan şiirinden almış; konuyu akıl, hak, adalet, kanun gibi yeni kavramlarla genişletmiştir."},{"f":"\"Durub-u Emsal-i Osmaniye\" nedir?","b":"Şinasi'nin atasözlerini derlediği, halk edebiyatına yönelik ilk çalışma."},{"f":"Şinasi'nin şiir ve gazete yapıtları nelerdir?","b":"Tercüme-i Manzume (çeviri şiirler), Müntahabat-ı Eş'ar (şiir seçkisi); Tercüman-ı Ahval ve Tasvir-i Efkâr gazeteleri."},{"f":"Namık Kemal edebiyatımızda hangi sıfatla anılır?","b":"\"Vatan şairi\" — hürriyet kavramını şiirde ilk kez kullanan şairdir."},{"f":"Namık Kemal'in şiirinde kaç dönem vardır?","b":"Üç dönem: ilki biçim ve konuca eski (gazeller); ortası biçimce eski konuca yeni (Hürriyet Kasidesi); sonu biçim ve konuca yeni (Vaveyla)."},{"f":"Namık Kemal'e göre tiyatronun işlevi nedir?","b":"\"Tiyatro bir eğlencedir; fakat eğlencelerin en faydalısıdır\" — halkı eğitim aracıdır."},{"f":"Namık Kemal'in romanlarının ortak özelliği nedir?","b":"Aile kurumu ve sosyal fayda amaçlanır; kahramanlar tek yönlüdür (iyiler çok iyi, kötüler çok kötü), teknik kusurludur."},{"f":"\"Vatan yahut Silistre\" neyi anlatır?","b":"Namık Kemal'in, 1853-56 Osmanlı-Rus savaşını konu alan, sahnelenen ilk Türk tiyatro yapıtı (4 perdelik dram)."},{"f":"\"Celaleddin Harzemşah\" nedir?","b":"Namık Kemal'in, Harzemşah hükümdarının kahramanlıklarını ve \"İslam düşüncesi\"ni anlattığı 15 perdelik dramı."},{"f":"Namık Kemal'in başlıca yapıtları nelerdir?","b":"Roman: İntibah, Cezmi; Tiyatro: Vatan yahut Silistre, Akif Bey, Gülnihal; Eleştiri: Tahrib-i Harabat, Takip."},{"f":"Ziya Paşa'nın kişiliğindeki temel çelişki nedir?","b":"Düşüncede yenilikçi olup Batı ve halk şiirini övmesine karşın, kendi şiirlerinde divan şiiri biçimini sürdürmesi."},{"f":"Ziya Paşa hangi nazım biçimlerinin en önemli şairi sayılır?","b":"Terkib-i bent ve terci-i bent."},{"f":"\"Harabat\" nedir?","b":"Ziya Paşa'nın Türkçe, Farsça, Arapça şiirlerden oluşturduğu, edebiyat tarihimizde ilk edebiyat tarihi taslağı sayılan üç ciltlik antoloji."},{"f":"Ziya Paşa \"Şiir ve İnşa\" makalesinde ne savunmuştur?","b":"Divan şiirini kabul etmeyip halk şiirini övmüştür (kendi şiirlerinde ise divan tarzını sürdürmüştür)."},{"f":"Ziya Paşa'nın diğer önemli yapıtları nelerdir?","b":"Zafername (hiciv), Rüya (düzyazı eleştiri), Defter-i Amal (Türk edebiyatında ilk anı örneği sayılır)."},{"f":"Ahmet Mithat Efendi'nin edebiyat anlayışının temel ilkesi nedir?","b":"\"Halk için roman\" — halka okuma alışkanlığı kazandırmak."},{"f":"Ahmet Mithat Efendi'ye neden \"yazı makinesi\" denir?","b":"Roman, öykü, tarih, coğrafya gibi çok sayıda alanda olağanüstü miktarda eser vermesi nedeniyle."},{"f":"\"Letaif-i Rivayet\" nedir?","b":"Ahmet Mithat Efendi'nin, Türk edebiyatındaki ilk öykü örneklerini içeren 25 cilt 28 hikayelik yapıtı."},{"f":"Ahmet Mithat Efendi Servetifünun yazarlarına ne ad takmıştır?","b":"\"Dekadanlar\" (soysuzlaşmış) — onları eleştirerek."},{"f":"\"Esrar-ı Cinayet\" neyle bilinir?","b":"Ahmet Mithat Efendi'nin, Türk edebiyatında ilk polisiye roman sayılan yapıtı."},{"f":"Ahmet Vefik Paşa neyle tanınır?","b":"Moliere'den yaptığı çeviri ve adaptelerle; Bursa'da ilk Türk tiyatro binasını kurmuştur."},{"f":"Ahmet Vefik Paşa'nın dil ve tarih alanındaki önemi nedir?","b":"Türkçülük akımının öncülerindendir; \"Lehçe-i Osmani\" sözlüğünü ve \"Şecere-i Türk\" çevirisini yapmıştır."},{"f":"Şemsettin Sami hangi alanlarda tanınır?","b":"Dil, sözlük, ansiklopedi ve çeviri alanlarında; \"dilci\" olarak tanınır."},{"f":"Şemsettin Sami'nin başlıca yapıtları nelerdir?","b":"Taaşşuk-ı Talat ve Fitnat (ilk yerli roman), Kamus-ı Türki (sözlük), Kamusü'l Âlâm (ansiklopedi)."},{"f":"Direktör Ali Bey neyle tanınır?","b":"Moliere'den sade dille uyarlamalar yapmıştır; Batılı anlamda ilk günlüğü (Seyahat Jurnali) yazmıştır."},{"f":"Mizancı Mehmet Murat'ın ünlü romanı hangisidir?","b":"\"Turfanda mı Yoksa Turfa mı\" — Tanzimat döneminin gerçekçi panoramasını yansıtır."},{"f":"Abdülhak Hamit Tarhan'a hangi unvan verilmiştir?","b":"\"Şair-i Âzam\" (büyük şair) — Süleyman Nazif tarafından verilmiştir."},{"f":"Abdülhak Hamit Tarhan'a neden \"tezatlar şairi\" denir?","b":"Şiirlerinde karmaşık ve basit duygu-düşüncelerin bir arada, düzensiz biçimde yer almasından."},{"f":"Abdülhak Hamit Tarhan'ın şiirlerindeki başlıca temalar nelerdir?","b":"Tabiat, aşk, ölüm, yokluk, hiçlik, yurt sevgisi ve metafizik konular."},{"f":"\"Sahra\" adlı yapıtın önemi nedir?","b":"Batılı anlamda ilk pastoral şiir örneklerini içerir; kır ve köy hayatını över."},{"f":"\"Makber\" neyle bilinir?","b":"Abdülhak Hamit'in eşinin ölümü üzerine yazdığı ağıt; Türk şiirinde metafizik düşüncenin başlangıcı sayılır."},{"f":"\"Validem\" ve \"Belde\" adlı yapıtların önemi nedir?","b":"Validem ilk duraksız şiir örneğidir; Belde, Paris'teki şehir hayatını anlatır."},{"f":"Recaizade Mahmut Ekrem edebiyat tarihimizde nasıl anılır?","b":"Tanzimat 2. dönemini başlatan \"üstat\"; Servet-i Fünun'un oluşmasını sağlamıştır."},{"f":"Recaizade M. Ekrem ile Muallim Naci arasındaki kafiye tartışması nedir?","b":"Recaizade Mahmut Ekrem \"kafiye kulak içindir\" diyerek yazılışı değil söylenişi esas almış; Muallim Naci ise geleneksel \"göz için kafiye\"yi savunmuştur."},{"f":"Recaizade Mahmut Ekrem'in şiir görüşü nedir?","b":"\"Güzel olan her şey şiirin konusu olabilir.\""},{"f":"\"Araba Sevdası\" nedir?","b":"Recaizade Mahmut Ekrem'in, Bihruz Bey'in yanlış Batılılaşmasını anlattığı ilk realist roman örneği."},{"f":"Recaizade Mahmut Ekrem'in diğer yapıtları nelerdir?","b":"Muhsin Bey (öykü), Afife Anjelik, Atala (tiyatro), Zemzeme (şiir/eleştiri önsözleriyle ünlü)."},{"f":"Sami Paşazade Sezai neyle tanınır?","b":"Öykülerinde realizme yönelen, Türk edebiyatında Batılı anlamda ilk öykü örneklerini yazan sanatçı."},{"f":"\"Sergüzeşt\" nedir?","b":"Sami Paşazade Sezai'nin, romantizmden realizme geçişte köprü sayılan, esaret temalı romanı."},{"f":"Nabizade Nazım hangi akımlardan etkilenmiştir?","b":"Natüralizm ve realizmden; roman/hikaye konularını ilk kez İstanbul dışına taşımıştır."},{"f":"\"Karabibik\" ve \"Zehra\" neyle bilinir?","b":"Karabibik ilk köy romanı denemesi; Zehra ilk psikolojik roman denemesidir."},{"f":"Muallim Naci edebiyat tarihimizde nasıl konumlanır?","b":"Tanzimat döneminde yaşamasına rağmen eski (divan) şiirinin temsilcisi sayılır; kafiye tartışmasında \"göz için kafiye\"yi savunmuştur."},{"f":"\"Köylü Kızların Şarkısı\" neyle önemlidir?","b":"Edebiyatımızda köyden söz eden ilk şiir sayılır (Muallim Naci)."},{"f":"Ahmet Cevdet Paşa kimdir?","b":"Tanzimat'ın önemli devlet adamı, tarihçi-hukukçu; ilk Türk kadın romancı Fatma Aliye'nin babasıdır."},{"f":"Fatma Aliye Hanım neyle tanınır?","b":"İlk Türk kadın romancı; roman, felsefe, tarih, biyografi türlerinde yazmış ve çeviriler yapmıştır."},{"f":"Beşir Fuat kimdir?","b":"Türk edebiyatında ilk kez gerçekçilik ve doğalcılık akımlarını tanıtan, pozitivizme bağlı yazar."},{"f":"Şair Eşref neyle tanınır?","b":"Hiciv şairi; özellikle II. Abdülhamit'e yönelik hicivleriyle ünlüdür."},{"f":"Teodor Kasap kimdir?","b":"Türk edebiyatında ilk mizah dergisi olan \"Diyojen\"i çıkarmıştır."},{"f":"Ali Suavi kimdir?","b":"Tanzimat dönemi fikir ve eylem adamı, gazeteci (Muhbir gazetesi); 1878'de Çırağan Vakası'nda öldürülmüştür."}]},{"id":"edb-9","name":"Servetifünun ve Fecriati","cards":[{"f":"Servetifünun edebiyatı nasıl oluştu?","b":"\"Edebiyatıcedide\" de denir; 1896'da Tevfik Fikret'in Servet-i Fünun dergisinin yönetimini üstlenmesiyle oluşan topluluktur."},{"f":"Servetifünun dergisi/topluluğu ne zaman ve neden kapatıldı?","b":"16 Ekim 1901'de; Hüseyin Cahit'in \"Edebiyat ve Hukuk\" makalesi nedeniyle II. Abdülhamit'in sıkıyönetimince kapatıldı."},{"f":"Servetifünun'un oluşumunda en etkili iki isim kimdir?","b":"Recaizade Mahmut Ekrem ve Abdülhak Hamit Tarhan."},{"f":"Servetifünun sanatçıları neden bir köyde çiftlik hayatı planlamıştır?","b":"İstibdat (baskı) döneminde toplumsal/siyasi konulardan uzak kalmak zorunda kaldıkları, Yeni Zelanda'ya gitme hayalleri gerçekleşmediği için."},{"f":"Servetifünun şiirinde \"abes-muktebes\" tartışması nedir?","b":"Göz için mi kulak için mi uyak kullanılacağı tartışması; sonunda Recaizade M. Ekrem öncülüğünde Türkçe kulak kafiyesi benimsenmiştir."},{"f":"Servetifünun'da anı türünde en önemli isim kimdir?","b":"Halit Ziya Uşaklıgil (Mehmet Rauf ve Hüseyin Cahit de anı yazmıştır)."},{"f":"Servetifünun'da gezi türünde öne çıkan isim kimdir?","b":"Cenap Şahabettin."},{"f":"Servetifünun'da eleştiri türünde tanınan isim kimdir?","b":"Ahmet Şuayb."},{"f":"Servetifünun şiirinde hangi akımlar etkilidir?","b":"Sembolizm ve parnasizm."},{"f":"Servetifünun şiirinin içeriği nasıldır?","b":"Bireysel duygular (aşk, acı, üzüntü, melankoli) işlenmiştir; toplumsal konulara neredeyse hiç yer verilmemiştir."},{"f":"Servetifünun şairleri aruzu nasıl kullanmıştır?","b":"Türkçe sözcükleri aruza zorlamadan, aruzu Türkçeye başarıyla uydurmuşlardır."},{"f":"Servetifünun şiirinde \"anjambman\" nedir?","b":"Bir dizede tamamlanmayan anlamın bir sonraki dizeye/dizelere taşınmasıdır; şiirde sıkça kullanılmıştır."},{"f":"Servetifünun şiirinde nazım-nesir ilişkisi nasıldır?","b":"Nazım nesre yaklaştırılmış, biçim kurallarından çok anlam ve konu bütünlüğüne önem verilmiştir."},{"f":"Servetifünun'un geliştirdiği yeni nazım biçimleri nelerdir?","b":"Fransız edebiyatından \"terza-rima\" ve \"sone\"; divan edebiyatındaki müstezat geliştirilerek \"serbest müstezat\" oluşturulmuştur."},{"f":"\"Göz için mi kulak için mi uyak\" tartışması nasıl sonuçlanmıştır?","b":"Servetifünuncular, Türkçe telaffuza dayalı kulak uyağını benimsemiştir."},{"f":"Servetifünun şiirinde hangi sözcük ve ünlemler sık kullanılmıştır?","b":"\"ki\" ve \"evet\" gibi bağlaçlar; \"oh, of, ey\" gibi ünlemler; \"meleğim, güzelim\" gibi hitaplar."},{"f":"Servetifünun'da tiyatro türü neden gelişmemiştir?","b":"Sanatçılar salon edebiyatına yönelmiş, tiyatroyla pek ilgilenmemiştir; dönemde daha çok resim sanatının etkisi görülür."},{"f":"Servetifünun döneminde gazetecilik durumu nasıldır?","b":"Neredeyse yoktur; bunun yerine edebiyat/sanat dergileri (Servetifünun, Hazine-i Fünun, Malumat) önemlidir."},{"f":"Servetifünun roman ve öykülerinde hangi akımlar etkilidir?","b":"Realizm ve natüralizm; Fransız yazarlar Zola, Balzac, Flaubert, Daudet, Goncourt örnek alınmıştır."},{"f":"Servetifünun romanlarında sosyal çevre nasıl sınırlıdır?","b":"\"Aile ortamı\" ile sınırlıdır; aydın kesimin bireysel yaşamı ve iç dünyası konu edilir."},{"f":"Servetifünun roman ve öykülerinde dil nasıldır?","b":"Ağır, süslü; Arapça-Farsça sözcük ve tamlamalarla yüklüdür."},{"f":"Servetifünun romanlarında mekan genellikle neresidir?","b":"İstanbul; öykülerde az da olsa İstanbul dışına çıkılmıştır."},{"f":"Servetifünun edebiyatının genel dil/üslup anlayışı nedir?","b":"\"Sanat, sanat içindir\"; ağır ve süslü dil, hiç duyulmamış yeni tamlamalar türetilmiştir (saat-i semenfam, lerziş-i baran gibi)."},{"f":"Tevfik Fikret Servetifünun'da nasıl nitelendirilir?","b":"\"Fikri, irfanı ve vicdanı hür bir şair\" olarak nitelendirilir; topluluğun en büyük temsilcisidir."},{"f":"Tevfik Fikret'in şiir yaşamı kaç döneme ayrılır?","b":"İki döneme: Servetifünun dönemi (1885-1901, sanat için sanat) ve sonrası (1901-1915, toplumsal konulara yönelme)."},{"f":"Tevfik Fikret'in şiirde getirdiği biçimsel yenilik nedir?","b":"Beyit bütünlüğünü kırmış, nazmı nesre yaklaştırmıştır."},{"f":"Tevfik Fikret hangi akımdan etkilenmiştir?","b":"Parnasizm (biçime verdiği önemle)."},{"f":"Tevfik Fikret'in \"manzum hikaye\" türündeki şiirleri hangileridir?","b":"Balıkçılar, Nesrin, Ramazan Sadakası, Hasta Çocuk."},{"f":"\"Sis\" şiiri neyi anlatır?","b":"İstanbul'u istibdat döneminin karanlığıyla birlikte eleştirir; Yahya Kemal buna \"Siste Söyleniş\" şiiriyle karşılık vermiştir."},{"f":"\"Tarih-i Kadim\" ve \"Doksan Beşe Doğru\" şiirleri neyi eleştirir?","b":"Tarih-i Kadim din kurumunu eleştirir (Mehmet Akif'le tartışmasına yol açmıştır); Doksan Beşe Doğru İttihat ve Terakki'nin Meclisi kapatmasını eleştirir."},{"f":"Tevfik Fikret'in başlıca yapıtları nelerdir?","b":"Rübab-ı Şikeste (ilk şiir kitabı), Haluk'un Defteri, Şermin."},{"f":"Cenap Şahabettin Servetifünun şiirinde nasıl bir yere sahiptir?","b":"Tevfik Fikret'ten sonraki en önemli isimdir; müzikaliteye çok önem vermiştir."},{"f":"Cenap Şahabettin'in şiir anlayışı nedir?","b":"\"Tablo şiir\" yazmıştır; şiiri sözcüklerle yapılmış bir resim olarak görür."},{"f":"Cenap Şahabettin hangi akımlardan etkilenmiştir?","b":"Hem sembolizm hem parnasizmden; ancak sembolizme daha yakındır."},{"f":"\"Elhan-ı Şita\" neyi anlatır?","b":"Kış mevsimini ve kar yağışının bıraktığı izlenimleri anlatan, Cenap Şahabettin'in önemli şiiridir."},{"f":"Cenap Şahabettin'in düzyazı yönü nasıldır?","b":"Aynı zamanda düzyazı ustasıdır; düzyazıları şiirlerine göre daha sadedir (Evrak-ı Eyyam, Nesr-i Harp, Nesr-i Sulh)."},{"f":"Halit Ziya Uşaklıgil roman-öykü alanında nasıl anılır?","b":"\"Modern anlamda Türk romanının kurucusu\" olarak anılır."},{"f":"Halit Ziya Uşaklıgil'in dil özelliği nedir?","b":"Arapça-Farsça sözcük ve tamlamalara sıkça yer vermiştir (Cumhuriyet'ten sonra dilini sadeleştirmiştir)."},{"f":"Halit Ziya Uşaklıgil'in romanlarında hangi konular işlenir?","b":"Bireysel konular; sürekli yakınma, karamsarlık, hayal kırıklığı, mutluluğu arayıp bulamama."},{"f":"\"Mai ve Siyah\" ve \"Aşk-ı Memnu\" kime aittir?","b":"Halit Ziya Uşaklıgil'e; ayrıca Türk edebiyatında ilk mensur şiir örneklerini de vermiştir."},{"f":"Halit Ziya Uşaklıgil'in başlıca yapıtları nelerdir?","b":"Mai ve Siyah, Aşk-ı Memnu, Kırık Hayatlar (roman); Kırk Yıl (anı)."},{"f":"Mehmet Rauf hangi romanıyla tanınır?","b":"\"Eylül\" — Türk edebiyatının ilk psikolojik romanı sayılır."},{"f":"Mehmet Rauf'un roman özellikleri nelerdir?","b":"Romantik aşklar, duygular, kişilerin iç dünyası ve hüzün işlenir; psikolojik tahlillere önem vermiştir."},{"f":"Hüseyin Cahit Yalçın hangi konuda tanınmıştır?","b":"Servetifünun döneminde eleştiri yazılarıyla; \"Edebiyat ve Hukuk\" makalesi derginin kapanmasına yol açmıştır."},{"f":"Hüseyin Cahit Yalçın'ın sanat anlayışı nedir?","b":"\"Sanat için sanat\"; edebiyatın amacının sanat olduğunu, bir araç olmadığını savunmuştur."},{"f":"Süleyman Nazif neyle tanınır?","b":"Sürgün yaşadığı Malta'da yazdığı \"vatan\" konulu şiirlerle; \"Kara Bir Gün\" yazısı İstanbul'un işgalini konu alır."},{"f":"Ali Ekrem Bolayır kimdir?","b":"Namık Kemal'in oğludur; Servetifünun şairlerindendir, sonradan toplumsal ve millî konulara yönelmiştir (Ordunun Defteri)."},{"f":"Celal Sahir Erozan'ın şiirlerindeki başlıca teması nedir?","b":"\"Kadın\" — şiirlerinin başlıca ve değişmez konusu kadındır."},{"f":"Hüseyin Rahmi Gürpınar neyle tanınır?","b":"Ahmet Mithat'ın halk için roman yazma geleneğini sürdüren, natüralizmin başarılı temsilcisi; \"sokağı edebiyata taşıyan yazar.\""},{"f":"Hüseyin Rahmi Gürpınar'ın romanlarında tipler nasıldır?","b":"Aşırı ihtiraslı, aptal, sahte batılılaşmış, batıl inançlı kişilerdir; mizah yoluyla toplumsal eleştiri yapar."},{"f":"Hüseyin Rahmi Gürpınar'ın \"Şık\" ve \"Şıpsevdi\" romanları neyi işler?","b":"Yanlış Batılılaşma konusunu işler."},{"f":"Ahmet Rasim kimdir?","b":"Hiçbir edebi topluluğa katılmamış; fıkra türünün edebiyatımızdaki ilk önemli ustası; şehir yaşamını sohbet ve anılarıyla anlatmıştır."},{"f":"Servetifünun'un bağımsız sanatçıları aynı zamanda hangi dönemin de bağımsız sanatçısı sayılır?","b":"Milli Edebiyat döneminin."},{"f":"Fecr-i Ati topluluğu ne zaman ve neden kuruldu?","b":"1901'de Servetifünun'un dağılmasından sonra oluşan boşluğu doldurmak için genç sanatçılarca kuruldu."},{"f":"Fecr-i Ati, Türk edebiyat tarihinde ilk kez neyi yapmıştır?","b":"İlk beyanname (bildiri) yayımlayan edebi topluluktur."},{"f":"Fecr-i Ati Beyannamesi'nin temel görüşü nedir?","b":"Sanatın \"şahsi ve muhterem\" (kişisel ve saygıdeğer) olduğudur."},{"f":"Fecr-i Ati'nin Servetifünun'a benzerlik ve farkı nedir?","b":"Sanat/dil/üslup anlayışı benzer; ancak Servetifünun'a tepki olarak çıkmışlar, edebiyata yenilik getirememişlerdir."},{"f":"Fecr-i Ati'nin sanat yaşamı neden kısa sürmüştür?","b":"Ortak bir sanat anlayışında bütünlük olmadığı için topluluk kısa sürede dağılmıştır."},{"f":"Fecr-i Ati'nin en önemli temsilcisi kimdir?","b":"Ahmet Haşim; topluluk dağıldıktan sonra da sanat yaşamını bağımsız sürdürmüştür."},{"f":"Fecr-i Ati dağıldıktan sonra bazı sanatçılar hangi harekete katılmıştır?","b":"Milli Edebiyat hareketine (M. Fuat Köprülü, Refik Halit, Yakup Kadri, Ali Canip, Hamdullah Suphi, Şahabettin Süleyman)."},{"f":"Ahmet Haşim şiirinde hangi akımların etkisi görülür?","b":"Sembolizm (empresyonizmin de etkisi vardır)."},{"f":"Ahmet Haşim \"akşam şairi\" olarak neden anılır?","b":"Şiirlerinde akşam, şafak, gurup, mehtap gibi hayal kurmaya uygun zaman ve doğa görüntülerini sıkça işlemesinden."},{"f":"Ahmet Haşim'e göre şiirin özelliği nedir?","b":"\"Şiir, anlaşılmak için değil, duyulmak için yazılır\"; şiirin dili müziğe yakındır, düz yazıya çevrilemez."},{"f":"Ahmet Haşim'in düzyazı türü eserleri nasıldır?","b":"Fıkra, sohbet, gezi türünde özgün bir üsluba sahiptir (Gurabahane-i Laklakan, Bize Göre)."},{"f":"Ahmet Haşim'in başlıca yapıtları nelerdir?","b":"Göl Saatleri, Piyale (şiir); Frankfurt Seyahatnamesi (gezi)."},{"f":"Emin Bülent Serdaroğlu kimdir?","b":"Fecr-i Ati'nin ilk kurucularından; epik şiirler yazmıştır, \"Kin\" şiiriyle tanınır."},{"f":"İzzet Melih (Devrim) neyle tanınır?","b":"Fecriati sanatçısı; roman ve öykü yazarıdır (Leyla, Tezad, Sermed, Hüzün, Tebessüm yapıtları arasındadır)."},{"f":"Müfit Ratip kimdir?","b":"Fecriaticiler arasında tiyatro türünde en başarılı sanatçı; teknik bakımından iyi eserler ve eleştiri yazıları yazmıştır."}]},{"id":"edb-10","name":"Milli Edebiyat","cards":[{"f":"«Milli edebiyat» adı ilk hangi dergide kullanıldı?","b":"Genç Kalemler dergisinde; «halka doğru» ilkesine dayanan Türkçülük yönelimi bu adı doğurmuştur."},{"f":"Genç Kalemler dergisini kimler, ne zaman çıkardı?","b":"1910'da Selanik'te çıkmaya başladı; 1911'de Ömer Seyfettin ve Ali Canip'in \"Yeni Lisan\" makalesiyle Milli Edebiyat'ın öncüsü oldu (Ziya Gökalp de yazarıdır)."},{"f":"Yeni Lisan makalesinin savunduğu görüşlerden ikisini yaz.","b":"Arapça-Farsça dil bilgisi kurallarının kaldırılması ve konuşmada İstanbul ağzına uyulması."},{"f":"Milli Edebiyat'ın temel amaçlarından üçünü say.","b":"Dilde yalınlık, roman/öyküde yerli konuları işleme, şiirde hece ölçüsünü kullanma."},{"f":"Milli Edebiyat dönemi şiiri kaç anlayışa ayrılır?","b":"Üçe: saf (öz) şiir, halkın yaşayışını anlatan şiir, sade dil-hece ile yazılmış milli şiir."},{"f":"Saf (öz) şiir anlayışını benimseyen iki şair kimdir?","b":"Yahya Kemal Beyatlı ve Ahmet Haşim."},{"f":"Halkın yaşayışını anlatan şiir anlayışını hangi şairler benimsemiştir?","b":"Mehmet Akif Ersoy ve Mehmet Emin Yurdakul."},{"f":"Nev-Yunanilik (Havza Edebiyatı) nedir?","b":"Türk edebiyatını Eski Yunan/Akdeniz kültürüne dayandırarak batılılaştırma anlayışı; Yahya Kemal ve Yakup Kadri benimsemiştir."},{"f":"Milli Edebiyat döneminde roman ve öykü hangi ilkeyle yazılmıştır?","b":"«Halka doğru» ilkesiyle; Anadolu mekân, memleket gerçekleri konu edinilmiştir."},{"f":"Milli Edebiyat dönemi roman-öyküsü genelde hangi akıma bağlıdır?","b":"Realizme (gerçekçilik); bazı sanatçılar natüralizme de bağlı kalmıştır."},{"f":"Türk tiyatrosunda ilk resmi tiyatro kurumu hangisidir, ne zaman kurulmuştur?","b":"Darülbedayi; 1914'te İstanbul Belediyesi'ne bağlı olarak Fransız tiyatrocu André Antoine'ın desteğiyle kurulmuştur."},{"f":"Ömer Seyfettin edebiyatımızda hangi türü bağımsız hale getirmiştir?","b":"Küçük hikâyeyi; hikâyeciliği meslek haline getirmiş, 140 kadar hikâye yazmıştır."},{"f":"Edebiyatımızda «olay öyküsü» (Maupassant Tarzı) türünün en önemli temsilcisi kimdir?","b":"Ömer Seyfettin."},{"f":"Ömer Seyfettin'in «içtimai roman» olarak anılan uzun öyküsü hangisidir?","b":"Efrûz Bey."},{"f":"Ömer Seyfettin'in Türkçülük düşüncesini işlediği hikâyelerinden birini yaz.","b":"Primo Türk Çocuğu (ya da Aşhab-ı Kehfimiz)."},{"f":"Ziya Gökalp'in Türkçülük düşüncesini sistemleştirdiği yapıtı hangisidir?","b":"Türkçülüğün Esasları."},{"f":"Ziya Gökalp'in Turancılık düşüncesini ortaya koyan şiiri hangisidir?","b":"Turan."},{"f":"Ziya Gökalp'in şiir anlayışının belirgin özelliği nedir?","b":"Didaktiktir; sanatı toplum ve düşünce için bir araç olarak görmüş, sade dille manzum destanlar da yazmıştır."},{"f":"Mehmet Emin Yurdakul'a «Türk şairi» unvanını kazandıran dize hangi şiirdendir?","b":"Cenge Giderken şiirinin «Ben bir Türk'üm dinim cinsim uludur» dizesinden."},{"f":"Mehmet Emin Yurdakul'un şiir dili ve ölçüsü nasıldır?","b":"Bütün şiirlerini hece ölçüsüyle, didaktik ve halkçı bir söyleyişle yazmıştır."},{"f":"Ali Canip Yöntem Genç Kalemler dergisinde hangi görevi üstlenmiştir?","b":"Derginin başyazarlığını yapmış, Yeni Lisan anlayışının savunuculuğunu üstlenmiştir."},{"f":"Ali Canip Yöntem kiminle edebiyat tarihçiliği üzerine tartışmıştır?","b":"Cenap Şahabettin ile."},{"f":"Mehmet Fuat Köprülü'nün edebiyat tarihindeki önemi nedir?","b":"Türk edebiyatı tarihiyle ilgili ilk bilimsel çalışmaları yapmıştır."},{"f":"Mehmet Fuat Köprülü'nün Türk tasavvuf edebiyatı üzerine ünlü araştırması hangisidir?","b":"Türk Edebiyatında İlk Mutasavvıflar; Yunus Emre ve öncesini bilimsel yöntemle incelemiştir."},{"f":"Hamdullah Suphi Tanrıöver hangi özelliğiyle «milli hatip» olarak bilinir?","b":"Hitabet ve nutuklarıyla; Kurtuluş Savaşı sırasında halkı aydınlatan konuşmalar yapmıştır."},{"f":"Ahmet Hikmet Müftüoğlu'nun en ünlü, monolog türündeki eseri hangisidir?","b":"Yeğenim; Türk edebiyatının en ünlü ve güzel monologlarından sayılır."},{"f":"Ahmet Hikmet Müftüoğlu Milli Edebiyat'a geçmeden önce hangi akıma bağlıydı?","b":"Servetifünun; o dönem eserlerinde ağır ve süslü bir dil kullanmıştır."},{"f":"Yakup Kadri Karaosmanoğlu'nun romanlarında işlediği temel konu nedir?","b":"Tanzimat'tan Cumhuriyet'e Türk toplumunun yaşam tarzı ve değişimi."},{"f":"Yakup Kadri'nin Kiralık Konak romanı neyi anlatır?","b":"Tanzimat'la başlayan Batılılaşmanın üç kuşak arasında yarattığı çatışmayı."},{"f":"Yakup Kadri'nin Yaban romanı neyi konu edinir?","b":"Kurtuluş Savaşı döneminde Anadolu köylüsü ile aydın arasındaki çatışmayı."},{"f":"Reşat Nuri Güntekin'in en tanınmış romanı hangisidir?","b":"Çalıkuşu; İstanbullu öğretmen Feride'nin Anadolu'yu dolaşmasını anlatır."},{"f":"Reşat Nuri'nin Yaprak Dökümü romanının konusu nedir?","b":"Dürüst bir memur olan Ali Rıza Bey'in ailesinin Batılılaşma özentisiyle dağılması."},{"f":"Halide Edip Adıvar hangi türlerde eser vermiştir?","b":"Roman, hikâye ve anı; ayrıca İngiliz dili ve edebiyatı profesörüdür."},{"f":"Halide Edip'in Kurtuluş Savaşı'nı işleyen romanlarından ikisini say.","b":"Ateşten Gömlek ve Vurun Kahpeye."},{"f":"Refik Halit Karay hangi hikâyecilik türünü başlatmıştır?","b":"Memleket hikâyeciliğini; Anadolu kadınları, kasaba memurları ve köylüleri işlemiştir."},{"f":"Refik Halit Karay'ın siyasal mizah yazılarını topladığı eseri hangisidir?","b":"Kirpinin Dedikleri; «Kirpi» takma adıyla yazmıştır."},{"f":"Beş Hececiler hangi dönemde şöhret kazanmıştır?","b":"I. Dünya Savaşı ve Mütareke yıllarında; milli kaynaklara dönmeyi ilke edinmişlerdir."},{"f":"Beş Hececiler kimlerdir?","b":"Orhan Seyfi Orhon, Faruk Nafiz Çamlıbel, Halit Fahri Ozansoy, Enis Behiç Koryürek, Yusuf Ziya Ortaç."},{"f":"Beş Hececiler'in şiirlerinin ortak zayıf yönü neydi?","b":"Halkın niteliklerini yeterince tanımadıkları için gerçekçilikten çok romantik bir milliyetçilik taşırlardı."},{"f":"Faruk Nafiz Çamlıbel'in Anadolu'yu gerçekçi anlattığı ünlü şiiri hangisidir?","b":"Han Duvarları."},{"f":"Yusuf Ziya Ortaç'ın 1922'de çıkardığı mizah dergisi hangisidir?","b":"Akbaba."},{"f":"Yusuf Ziya Ortaç'ın hece ölçüsüyle yazılmış ilk başarılı manzum piyesi hangisidir?","b":"Binnaz."},{"f":"Halit Fahri Ozansoy'un aruzdan heceye geçişini gösteren şiiri hangisidir?","b":"Aruza Veda."},{"f":"Enis Behiç Koryürek'in Türk denizciliğini destanlaştıran manzum hikâyeleri hangi başlık altındadır?","b":"Eski Korsan Hikâyeleri."},{"f":"Orhan Seyfi Orhon'un serbest müstezat biçimindeki uzun şiiri hangisidir?","b":"Fırtına ve Kar."},{"f":"Yahya Kemal Beyatlı neden Milli Edebiyat akımına dahil edilmez?","b":"Şiirleri Ok dışında hep aruzla yazılmıştır; akımı sadece makale ve konferanslarıyla desteklemiştir."},{"f":"Yahya Kemal'in hece ölçüsüyle yazdığı tek şiiri hangisidir?","b":"Ok."},{"f":"Yahya Kemal Beyatlı'nın şiir anlayışının adı nedir?","b":"Neoklasisizm; eski Divan şiiriyle çağdaş Batı şiirini birleştirmiştir."},{"f":"Yahya Kemal'in İstanbul'u konu alan şiir kitaplarından biri hangisidir?","b":"Aziz İstanbul (ya da Kendi Gök Kubbemiz)."},{"f":"Mehmet Akif Ersoy'un yazdığı milli marş hangisidir, hangi yıl kabul edilmiştir?","b":"İstiklal Marşı; 1921'de Milli Eğitim Bakanlığı'nın açtığı yarışmayla kabul edilmiştir."},{"f":"Mehmet Akif'in şiirlerindeki temel sanat anlayışı nedir?","b":"Toplum için sanat; dini lirizm taşır, İstanbul'un yoksul semtlerini gerçekçi anlatır."},{"f":"Mehmet Akif'in Safahat adlı yapıtı kaç bölümden oluşur?","b":"Yedi bölümden (Safahat, Süleymaniye Kürsüsünde, Hakkın Sesleri, Fatih Kürsüsünde, Hatıralar, Asım, Gölgeler)."},{"f":"Mehmet Akif'in Asım adlı eseri neyi konu edinir?","b":"I. Dünya Savaşı'ndan tablolar ve ideal gençlik tipini."},{"f":"Rıza Tevfik Bölükbaşı hangi lakapla tanınır?","b":"Feylesof Rıza; Batı felsefesini Türkiye'de tanıtmaya çalışmıştır."},{"f":"Ebubekir Hazım Tepeyran'ın Küçük Paşa romanı neyle tanınır?","b":"Köy gerçeğini ele alan ikinci köy romanı olmasıyla."},{"f":"Neyzen Tevfik hangi şiir türüyle tanınır?","b":"Hiciv; 20. yüzyılın önde gelen hiciv şairlerindendir."},{"f":"Musahipzade Celal'in oyunları genelde neyi konu edinir?","b":"Osmanlı tarihindeki sosyal hayatı, töreleri ve inançları güldürü öğeleriyle anlatır."},{"f":"İbnürrefik Ahmet Nuri Sekizinci hangi türle tanınır?","b":"Fransızcadan uyarladığı güldürü (komedi) oyunlarıyla; Türk tiyatrosuna çok oyun kazandırmıştır."},{"f":"Ali Ekrem Bolayır kimin oğludur?","b":"Namık Kemal'in oğludur; Milli Edebiyat dönemi şairlerindendir."}]},{"id":"edb-11","name":"Cumhuriyet Dönemi Şiiri","cards":[{"f":"Cumhuriyet Dönemi Türk edebiyatının genel dil anlayışı nedir?","b":"İstanbul Türkçesine dayalı, sade ve konuşma diline yakın bir dil; Millî Edebiyat geleneğinden yararlanılmış, gerçekçilik ve yerlilik esas alınmıştır."},{"f":"Cumhuriyet dönemini şekillendiren dille ilgili üç önemli gelişme nedir?","b":"Latin harflerinin kabulü, Türk Dil Kurumu'nun kurulması ve dilde sadeleşme çalışmaları."},{"f":"Cumhuriyet dönemi öğretici metinlerinin dil özelliği nedir?","b":"Sade, halkın anlayabileceği, konuşma diline yakın bir dil kullanılmış; Türkçe sözcükler ve halk söyleyişleri tercih edilmiştir."},{"f":"Nurullah Ataç hangi türde en başarılı temsilci sayılır, dile katkısı nedir?","b":"Deneme; Türkçenin özleşmesine öncülük etmiş, öz Türkçe sözcükleri kullanmış, belli bir dönemden sonra 've' bağlacını hiç kullanmamıştır."},{"f":"Suut Kemal Yetkin hangi türde ve nasıl bir üslupla tanınır?","b":"Deneme; estetik, sanat ve edebiyat konularında gözlemci, açık ve yalın bir üslupla yazmıştır."},{"f":"Fethi Naci edebiyatımızda hangi yönüyle öne çıkar?","b":"Eleştirmen ve denemeci; toplumcu sanat anlayışını benimseyip bilimsel yöntemlerle roman incelemeleri yazmıştır."},{"f":"Cemil Meriç'in yapıtlarındaki temel ilgi alanı nedir?","b":"Doğu-Batı kültür karşılaştırması; makale, deneme, inceleme ve sosyoloji alanında eser vermiştir."},{"f":"Mehmet Kaplan hangi alanda profesör olan bir yazardır?","b":"Yeni Türk Edebiyatı; araştırma-inceleme-deneme türünde eser vermiş, \"Şiir Tahlilleri\" adlı çalışmasıyla tanınır."},{"f":"Salah Birsel asıl ününü hangi türde sağlamıştır?","b":"Deneme; ayrıca şiir, günlük ve anı türünde de eserleri vardır."},{"f":"Falih Rıfkı Atay hangi türde en çok eser vermiştir?","b":"Gezi yazısı; Atatürk'le ilgili anılarını \"Çankaya\" adlı yapıtında toplamıştır."},{"f":"Ruşen Eşref Ünaydın'ı tanınır kılan yapıtı nedir?","b":"Mustafa Kemal'i Türk okuyucusuna ilk kez tanıtan \"Anafartalar Kumandanı Mustafa Kemal'le Mülakat\" adlı röportajı."},{"f":"Nihat Sami Banarlı hangi alanda tanınan bir yazardır?","b":"Edebiyat tarihi; \"Resimli Türk Edebiyatı Tarihi\" adlı eseriyle bilinir."},{"f":"Şevket Rado hangi türle tanınmıştır?","b":"Sohbet; \"Eşref Saat\" gibi yapıtlarıyla bilinir, son döneminde Türk Dili konusunda da yazılar yazmıştır."},{"f":"Eflatun Cem Güney hangi alanda çalışmalarıyla ün kazanmıştır?","b":"Folklor; geleneksel halk hikayelerini ve masallarını derleyen \"Masalcı Baba\" olarak tanınır."},{"f":"Cumhuriyet dönemi şiirinde ölçü nasıl değişmiştir?","b":"Aruz yerine hece ölçüsü yaygınlaşmış (Ahmet Haşim ve Yahya Kemal aruzu sürdürmüştür); 1940'tan sonra serbest şiir yaygınlaşmıştır."},{"f":"Cumhuriyet dönemi Türk şiiri için en önemli kaynak hangi gelenektir?","b":"Halk şiiri geleneği; şiirler sade bir dille yazılmıştır."},{"f":"Saf (öz) şiir anlayışını sürdüren şairlerin ortak özelliği nedir?","b":"1930'larda toplu bir harekete bağlanmadan Yahya Kemal ve Ahmet Haşim'i izleyip hece ölçüsünü modernleştiren, \"sanat sanat içindir\" anlayışındaki şairlerdir."},{"f":"Saf şiir anlayışının dayandığı Fransız şairler kimlerdir?","b":"Valery, Verlaine ve Mallarme."},{"f":"Saf şiir anlayışının temsilcileri kimlerdir?","b":"Ahmet Hamdi Tanpınar, Cahit Sıtkı Tarancı, Ahmet Muhip Dıranas, Necip Fazıl Kısakürek, Asaf Halet Çelebi."},{"f":"Cahit Sıtkı Tarancı'nın en çok işlediği tema ve onu üne kavuşturan şiiri nedir?","b":"Ölüm teması; \"Otuz Beş Yaş\" adlı şiiriyle bir yarışmada birincilik kazanmıştır."},{"f":"Ahmet Muhip Dıranas hangi akımdan etkilenmiş, hangi şiiriyle tanınır?","b":"Sembolizm; \"Fahriye Abla\" adlı şiiriyle tanınır."},{"f":"Necip Fazıl Kısakürek \"mistik şair\" olarak neyi işlemiş, hangi unvanı almıştır?","b":"Madde-ruh çatışmasını ve insanın iç dünyasını işlemiştir; ilk kitabı \"Örümcek Ağı\"dır, Cumhuriyet döneminde \"Sultanü'ş-şuara\" unvanını almıştır."},{"f":"Asaf Halet Çelebi hangi konularla \"sezgi şairi\" olarak bilinir?","b":"Masallar, dinler, Mevlana ve tasavvuf/Hint mistisizminden gelen sembollerle soyut bir alem anlatmıştır."},{"f":"Yedi Meşaleciler topluluğu hangi yılda, hangi kitapla ortaya çıkmıştır?","b":"1928'de \"Yedi Meşale\" adlı ortak kitapla; Cumhuriyet döneminin ilk edebi topluluğudur."},{"f":"Yedi Meşaleciler kime tepki olarak doğmuş, ilkeleri nelerdir?","b":"Beş Hececiler'e tepki olarak doğmuşlardır; \"samimiyet, canlılık, içtenlik ve daima yenilik\" ilkelerini benimsemişlerdir."},{"f":"Yedi Meşaleciler amaçlarına ulaşabilmiş midir?","b":"Hayır; topluluk dağıldıktan sonra sanatçılar bağımsız birer isim olarak çalışmalarını sürdürmüştür."},{"f":"Yedi Meşaleciler kimlerdir?","b":"Yaşar Nabi Nayır, Vasfi Mahir Kocatürk, Ziya Osman Saba, Muammer Lütfi, Kenan Hulusi Koray, Sabri Esat Siyavuşgil, Cevdet Kudret Solok."},{"f":"Yedi Meşaleciler içinde şiire en sadık kalan isim ve teması nedir?","b":"Ziya Osman Saba; anılara düşkünlük, çocukluk özlemi, ev-aile sevgisi ve ölüm yakınlığı gibi temaları işlemiştir."},{"f":"Yedi Meşaleciler içinde düzyazı (öykü) yazarı olarak öne çıkan kimdir?","b":"Kenan Hulusi Koray; topluluğun şiirden çok öyküleriyle tanınan üyesidir."},{"f":"Serbest nazım ve toplumcu şiirin öncüsü kimdir, dünya görüşü nedir?","b":"Nazım Hikmet; materyalist ve Marksist dünya görüşüne dayanır, toplumsal gerçekleri yansıtmayı amaçlar."},{"f":"Nazım Hikmet'in Türkiye'de yayımlanan ilk şiir kitabı hangisidir?","b":"\"835 Satır\" (1929)."},{"f":"Nazım Hikmet hangi akımdan etkilenmiş, kimin izini sürmüştür?","b":"Fütürizmden (gelecekçilik) etkilenmiş, özellikle Rus şair Mayakovski'nin etkisinde kalmıştır."},{"f":"Nazım Hikmet'in Kurtuluş Savaşı'nı anlatan destanı hangisidir?","b":"\"Kuvayı Milliye Destanı\"."},{"f":"Ahmet Arif'in şiirlerinin beslendiği kaynaklar ve konusu nedir?","b":"Halk türküsü, ağıt ve masallar; Doğu Anadolu insanının sorunlarını Marksist bir bakışla anlatmıştır."},{"f":"Ercüment Behzat Lav hangi akımlardan etkilenmiş, hangi eseriyle tanınır?","b":"Fütürizm ve dadaizm; toplumcu gerçekçi bir şairdir, \"Üç Anadolu\" adlı kitabıyla tanınır."},{"f":"Gülten Akın'ın şiir anlayışı zamanla nasıl değişmiştir?","b":"1970'lerden sonra bireysel duyarlıktan toplumsallığa yönelmiş, halk şiiri geleneği ile Nazım Hikmet çizgisini birleştirmiştir."},{"f":"Hasan Hüseyin Korkmazgil ve Hasan İzzettin Dinamo'nun ortak yönü nedir?","b":"İkisi de Marksist/toplumcu gerçekçi anlayışla şiir yazan şairlerdendir."},{"f":"Milli edebiyat zevkini sürdüren (memleketçi) şiirin özellikleri nelerdir?","b":"Halk şiiri kaynaklıdır, hece ölçüsü ve dörtlüklerle yazılmıştır; memleket sevgisi ve Anadolu insanını konu edinir."},{"f":"Kemalettin Kamu neden \"gurbet şairi\" olarak anılır?","b":"Gurbet duygusunu bizzat yaşamış ve şiirlerinde yansıtmıştır; \"Bingöl Çobanları\" ünlü şiiridir."},{"f":"Ahmet Kutsi Tecer'in halk şiirine en büyük katkısı nedir?","b":"Aşık Veysel'i keşfedip edebiyatımızda tanınmasını sağlamıştır."},{"f":"Arif Nihat Asya'nın lakabı ve ünlü şiirleri nelerdir?","b":"\"Bayrak şairi\"; \"Bayrak\" ve \"Fetih Marşı\" adlı şiirleriyle tanınır, rubai biçimini sıkça kullanmıştır."},{"f":"Mithat Cemal Kuntay'ın edebiyat tarihindeki yerini belirleyen romanı hangisidir?","b":"\"Üç İstanbul\"; II. Abdülhamit, II. Meşrutiyet ve Mütareke dönemlerini anlatır."},{"f":"Behçet Kemal Çağlar'ın Faruk Nafiz'le birlikte yazdığı eser hangisidir?","b":"\"Onuncu Yıl Marşı\"."},{"f":"Orhan Şaik Gökyay'ın en tanınmış şiirleri ve araştırma alanı nedir?","b":"\"Bu Vatan Kimin\" ve \"Yas\" şiirleri; ayrıca Dede Korkut üzerine önemli araştırmaları vardır."},{"f":"Necmettin Halil Onan'ın hamaset edebiyatının en güzel örneklerinden şiiri hangisidir?","b":"\"Bir Yolcuya (Dur Yolcu)\"."},{"f":"Maviciler topluluğu hangi dergi etrafında, kime tepki olarak oluşmuş ve akıbeti nedir?","b":"1952-56 arası \"Mavi\" dergisi etrafında, Garipçilere tepki olarak oluşmuş; akım kimliği kazanamadan dağılmıştır."},{"f":"Maviciler kısa süre sonra hangi anlayışın temsilcisi olmuştur?","b":"Toplumcu gerçekçiliğin temsilcisi olmuşlardır."},{"f":"Attila İlhan'ın edebiyatımızdaki özgün yönü nedir?","b":"Hem eski Türk şiirini hem Batı şiirini iyi bilen şair; toplumcu gerçekçilik ile divan şiiri esintili neoklasik özellikleri birleştirmiştir, \"Ben Sana Mecburum\" ile tanınmıştır."},{"f":"Hisar dergisi çevresindekilerin (Hisarcılar) genel sanat anlayışı nedir?","b":"Gelenekçidirler; ölçü-uyak-nazım biçimlerini sürdürmüş, sanatın ideolojinin emrine girmesine (Marksizme) karşı çıkmışlardır."},{"f":"Hisarcıların savunduğu dört temel ilke nedir?","b":"Sanatçının dili yaşayan dil olmalı, sanatçı bağımsız olmalı, sanat millî olmalı, sanatta yenilik esastır (gelenek reddedilmeden)."},{"f":"Hisar grubu şiirde hangi akımlara karşı çıkmıştır?","b":"Nazım Hikmet'in başlattığı toplumcu gerçekçiliğe, Orhan Veli'nin Garip'ine ve İkinci Yeni'ye karşı çıkmışlardır."},{"f":"Garip akımı kimler tarafından, ne zaman başlatılmıştır?","b":"1941'de Orhan Veli, Oktay Rifat ve Melih Cevdet'in ortak yayımladığı \"Garip\" adlı kitapla; \"Birinci Yeni\" olarak da anılır."},{"f":"Garipçilerin şiir anlayışındaki temel ilke nedir?","b":"Şiirde anlaşılmazlığı ve şairaneliği reddetmişler; hece-aruz ölçüsünü gereksiz görüp serbest şiiri benimsemişlerdir."},{"f":"Garipçiler şiirlerinde kimleri konu edinmiştir?","b":"Sıradan, küçük insan tipini; \"şiir halka seslenmelidir\" anlayışıyla günlük yaşamı şiire aktarmışlardır."},{"f":"Orhan Veli Kanık'ın şiirlerindeki dikkat çeken ortak öge nedir?","b":"Derin bir \"ironi\"; sıradan insanları, İstanbul sevgisini ve bireysel özlemi sade dille anlatmıştır."},{"f":"Melih Cevdet Anday'ın 1946 sonrası şiiri nasıl değişmiştir?","b":"Romantik ögelerden uzaklaşıp düşünceye ve akla dayanan şiirler yazmış, Yunan mitolojisinden yararlanmıştır."},{"f":"Oktay Rifat Horozcu'nun \"Perçemli Sokak\" kitabındaki yönelimi nedir?","b":"İkinci Yeni'ye (imgeci şiire) yönelmiş, soyut ve anlamca kapalı şiirler yazmıştır."},{"f":"Garip dışında yeniliği sürdüren şiirin özelliği nedir?","b":"Garip'in şairanelikten uzak sade diline bağlı kalıp kendi kişiliklerini de şiirlerine yansıtan şairlerin şiiridir."},{"f":"Fazıl Hüsnü Dağlarca'nın şiirindeki en belirgin özellik nedir?","b":"Her konuda kendine özgü bir şiir dili yaratmıştır; \"Çocuk ve Allah\" ve Kurtuluş Savaşı'nı anlatan \"yapma destanlar\"ıyla tanınır."},{"f":"Behçet Necatigil edebiyatımızda hangi lakapla anılır?","b":"\"Evler şairi\"; ev-aile-yakın çevre temalı, Divan şiiri unsurlarıyla Batı şiirini birleştiren kapalı şiirleriyle bilinir."},{"f":"Özdemir Asaf'ın şiir dilindeki dikkat çeken özellik nedir?","b":"Dize sayısını aza indirip \"sen-ben ikilemi\"ni işlemiş; ironik, anlamsız görünen söyleyişlere yer vermiştir."},{"f":"1960 sonrası mistik duyarlılık şiirinin kaynakları kimlerdir?","b":"Necip Fazıl, Mehmet Akif, Yunus Emre, Fuzuli ve Şeyh Galip; geleneksel değerlerle Batılı değerlerin çatışmasını işlerler."},{"f":"Sezai Karakoç'un edebiyatımızdaki yeri nedir?","b":"\"Diriliş\" dergisini çıkarıp kendine özgü İslami-mistik şiir anlayışını başlatmıştır; İkinci Yeni ile aynı dönemde fakat ayrı bir çizgidedir."},{"f":"Hilmi Yavuz şiirinde hangi unsurları birleştirmiştir?","b":"Divan şiiri kültürü ile modern şiirin serbestliğini; muhtevasında Doğu kültüründen pek çok unsur kullanmıştır."},{"f":"Cahit Zarifoğlu'nun şiirlerindeki temel çatışma nedir?","b":"Madde-ruh ikilemi ve Batı hegemonyasına karşı Doğu protestosu; İkinci Yeni etkisi ve İslami motifler taşır."},{"f":"İkinci Yeni akımı hangi akıma tepki olarak, kim tarafından adlandırılmıştır?","b":"Garip akımına tepki olarak ortaya çıkmıştır; adının isim babası Muzaffer Erdost'tur, \"Soyutçular\" da denir."},{"f":"İkinci Yeni şiirinin temel özelliği nedir?","b":"Anlamdan çok ses güzelliğine, imgeye ve çağrışıma önem verilmiş; sözcükler arası anlamsal bağ koparılarak kapalı bir dil kurulmuştur."},{"f":"İkinci Yeni temsilcileri kimlerdir?","b":"Cemal Süreya, Edip Cansever, Sezai Karakoç, Ece Ayhan, Turgut Uyar, İlhan Berk (baş harfleriyle \"CESETİ\")."},{"f":"Cemal Süreya'nın şiirindeki öne çıkan iki özellik nedir?","b":"Lirizm ve erotizm; şiirinde resim önemli rol oynar, mizah ve ironiye sıkça yer verir."},{"f":"Edip Cansever'in şiirlerindeki dikkat çeken teknik nedir?","b":"Dize alışkanlığını kırıp öyküye, tasvire ve diyaloglara yer vermiştir; tiyatrodan da yararlanmıştır."},{"f":"Turgut Uyar'ın İkinci Yeni içindeki özel konumu nedir?","b":"Şiirle düzyazı arasındaki ayrımı kaldıran öncü isimlerdendir; sonraki dönemde kapalı şiirler de yazmıştır."},{"f":"İlhan Berk'in şiir anlayışındaki temel görüşü nedir?","b":"\"Şiir anlam için yazılmaz\" görüşünü ısrarla savunmuş, soyut şiiri uç noktalara taşımıştır."},{"f":"Ece Ayhan'ın önerdiği ve kullandığı kavram nedir?","b":"\"Sivil şiir\"; sıkı şiir, etik ve marjinallik kavramları üzerinde durmuş, sürrealizmi çağrıştıran kurgusal bir bakışı vardır."},{"f":"İkinci Yeni sonrası toplumcu şiirin (1960-1980) genel özelliği nedir?","b":"Marksizm ve komünizm felsefesine dayalı, slogan ağırlıklı ve sert bir söyleyişle yazılan şiirdir."},{"f":"İsmet Özel'in şiir anlayışı zaman içinde nasıl değişmiştir?","b":"İlk şiirlerinde Marksist/toplumcuydu; 1974'te \"Amentü\" şiiriyle İslami-mistik anlayışa yönelmiştir."},{"f":"Ataol Behramoğlu hangi dergileri çıkarmıştır?","b":"İsmet Özel ile \"Halkın Dostları\", kardeşi Nihat Behram ile \"Militan\" dergilerini çıkarmıştır."},{"f":"1980 sonrası şiirin genel özelliği nedir?","b":"Özgün imgeler kullanılmış, anlaşılma kaygısı taşınmamış, şiir düzyazıya yaklaştırılmış, birey esas konu olmuştur."},{"f":"1980 sonrası şiirde \"imgeci şiir\" temsilcisi kimdir?","b":"Haydar Ergülen; ölüm, yalnızlık ve yabancılaşma temalarını geniş imgelerle işlemiştir."},{"f":"1980 sonrası şiirde \"mistik-metafizikçi şiir\" temsilcisi kimdir?","b":"Hüseyin Atlansoy; bedenden çok ruhu ön plana çıkararak görünenin ardındaki özü aramıştır."},{"f":"Cumhuriyet dönemi halk şiirinin genel özelliği nedir?","b":"Geleneksel konu ve biçimler sürdürülmüş, konuşma dili kullanılmış, şiirler saz eşliğinde söylenmeye devam etmiştir."},{"f":"Abdürrahim Karakoç hangi türle tanınmıştır?","b":"Taşlamalarıyla; halk şiiri geleneğiyle yazmış, sonra İslami anlayışa yönelmiştir; \"Mihriban\" ünlü şiiridir."}]},{"id":"edb-12","name":"Cumhuriyet Dönemi Roman, Öykü ve Tiyatro","cards":[{"f":"Cumhuriyet dönemi (1923 sonrası) roman ve öykünün genel bir özelliği nedir?","b":"Gerçekçi ve gözleme dayalı anlatım öne çıkmış, insan gerçekliği işlenmiş; roman-öykü konu ve üslup bakımından yeni boyutlar kazanmıştır."},{"f":"1923-1946 yılları arası roman ve hikayelerde hangi konular ağırlıktadır?","b":"Anadolu ve Anadolu halkı, Milli Mücadele ve inkılapların anlatılması, psikolojik yapıtlarla bireye dönüş."},{"f":"1946-1980 arası Türk romanına eklenen yeni temalar nelerdir?","b":"Demokratikleşme süreci ve siyasi partiler, ihmal edilen köy, kadın konusu, aydın-halk farkı, dini yaşayışı telkin eden romanlar."},{"f":"1980 sonrası roman-öyküde hangi anlatım yöntemi öne çıkmıştır?","b":"Günlük hayatın karmaşıklığını anlatmak için postmodern yöntem; ayrıca Avrupa'daki yazarların siyasi hesaplaşmaları ve eski İstanbul'a özlem işlenmiştir."},{"f":"Milli edebiyat zevkini sürdüren sanatçılar romanlarında hangi ortak yaklaşımı benimsemiştir?","b":"Batı ölçülerine göre teknik olarak başarılı roman-öyküler yazmış; Anadolu insanını, Milli Mücadele'yi ve Atatürk ilke-inkılaplarını konu edinmişlerdir."},{"f":"Milli edebiyat zevkini sürdüren sanatçılardan üç isim söyleyin.","b":"Yakup Kadri Karaosmanoğlu, Reşat Nuri Güntekin, Halide Edip Adıvar (ayrıca Refik Halit Karay, Emine Işınsu, Sevinç Çokum)."},{"f":"Emine Işınsu'nun romanlarının ana teması nedir?","b":"Köklerinden koparılmak istenen Türk insanının kimlik mücadelesi; Cumhuriyet sınırları dışındaki Türklerin yaşama mücadelesi."},{"f":"Sevinç Çokum'un romanlarında hangi konular işlenir?","b":"Türk toplumunun 1980 sonrası hızlı değişimi, yalnızlaşma; tarihi romanlarında dış Türklerin kimlik ve kültür mücadelesi."},{"f":"Toplumcu gerçekçi (köy edebiyatı) akımı 1930'lardan itibaren hangi konuları işler?","b":"Köylü ve işçi sorunları; ağa-köylü çatışması, imam-öğretmen karşıtlığı, zengin-fakir ve güçlü-güçsüz karşıtlığı."},{"f":"Köy edebiyatı akımının anlatım ve amaç özelliği nedir?","b":"Gözleme dayalı, tezli (güdümlü) bir anlatım; romanın ahlaki-sosyal bir amacı olduğu savunulur, siyasi ideoloji ön plandadır."},{"f":"Köy Enstitüsü çıkışlı yazarlardan üç isim sayın.","b":"Talip Apaydın, Mahmut Makal, Fakir Baykurt (Dursun Akçam, Mehmet Başaran da Köy Enstitülüdür)."},{"f":"Talip Apaydın'ın romanlarının genel konusu nedir?","b":"Yoksul köylünün su, toprak, eğitim, parasızlık, ortakçılık gibi sorunları; köyden kasabaya-kente göç."},{"f":"Talip Apaydın'ın \"Sarı Traktör\" ve \"Yoz Davar\" adlı eserlerinin konusu nedir?","b":"Sarı Traktör'de tarımda makineleşmeyle gelen sorunlar; Yoz Davar'da hayvancılıkla ilgili sorunlar işlenir."},{"f":"Yakup Kadri Karaosmanoğlu'nun \"Yaban\" romanı Türk edebiyatı için neden önemlidir?","b":"Bu romanla Türk romanı köy gerçekçiliğine yönelmiş; aydın-köylü çatışması ele alınmıştır."},{"f":"Mahmut Makal'ın \"Bizim Köy\" adlı eseri hangi özelliğiyle öne çıkar?","b":"Köy Enstitülü ilk yazarlardandır; röportaj özelliği taşıyan bu eseriyle köy yazıları çığırını başlatmıştır."},{"f":"Sadri Ertem edebiyatımızda nasıl tanınır?","b":"İlk toplumcu roman ve hikaye yazarlarındandır; ağa-tüccar sömürüsünü ve fabrika-işçi ilişkisini anlatmıştır."},{"f":"Kemal Bilbaşar'ın yapıtlarının konusu nedir?","b":"Anadolu kasabalarının ruhunu, halkın inanç-gelenek-törelerini yansıtır; \"Cemo\" ve \"Memo\"da ağa-köylü-memur ilişkileri içinde bir aşk öyküsü anlatılır."},{"f":"Necati Cumalı'nın şiir ve öykülerinde hangi bölge ve konular öne çıkar?","b":"Ege Bölgesi'ndeki kasaba ve kırsal kesim insanlarının sorunları; sevgi, özlem, sevinç ve toplumsal sorunlar birlikte işlenir."},{"f":"Abbas Sayar hangi bölge insanını anlatır?","b":"Orta Anadolu köylüsünün doğasını ve yaşam tarzını; politikacı-aydınlara Türk köylüsünü tanıtmayı amaçlar."},{"f":"Sabahattin Ali hangi öykü tarzında yazmıştır, önemli romanları nelerdir?","b":"Köy ve kasaba insanını gerçekçi bir bakışla anlatan Maupassant tarzı öykücüdür; romanları: Kuyucaklı Yusuf, İçimizdeki Şeytan, Kürk Mantolu Madonna."},{"f":"Rıfat Ilgaz hangi eseriyle ve hangi yönüyle tanınır?","b":"\"Hababam Sınıfı\" serisiyle tanınır; Türk edebiyatının gülmece (mizah) ustalarındandır."},{"f":"Fakir Baykurt hangi edebi harekete öncülük eder ve romanlarında ne işler?","b":"\"Köy edebiyatı hareketi\"nin önde gelen temsilcisidir; köy yaşamını, köylünün bilinçaltı çelişkilerini ve göç sorununu işler."},{"f":"Fakir Baykurt'un \"Yılanların Öcü\" romanının konusu nedir?","b":"Burdur'a bağlı Karataş köyünde toprak ve ağalık çevresinde çatışan insanların hayatından bir kesit sunar."},{"f":"Kemal Tahir'in roman anlayışı nasıldır?","b":"\"Türk romanı işçimizle köylümüzün gerçeklerinden çıkar\" görüşüyle törelere bağlı köy düzenini bilimsel yöntemle incelemiştir."},{"f":"Kemal Tahir'in \"Devlet Ana\" romanı neyi anlatır?","b":"Osmanlı Devleti'nin kuruluş sürecini; Osmanlı toplum yapısının kölecilik ve feodalizmden farklı, insancıl temelini savunur."},{"f":"Orhan Kemal Türk edebiyatına neyi getiren yazar olarak bilinir?","b":"İşçi sınıfını getiren yazardır; Çukurova'daki işçileri, köyden kente göç eden yoksul insanları anlatmıştır."},{"f":"Orhan Kemal'in \"Babaevi\" ve \"Avare Yıllar\" adlı romanları neyi anlatır?","b":"Babaevi çocukluk yıllarını anlatan ilk romanıdır; Avare Yıllar gençliğini anlatır."},{"f":"Yaşar Kemal'in gerçek adı nedir ve dünya çapında üne kavuşmasını sağlayan eseri hangisidir?","b":"Gerçek adı Kemal Sadık Gökçeli'dir; \"İnce Memed\" romanıyla dünya çapında üne kavuşmuştur."},{"f":"Yaşar Kemal'in romanlarında hangi bölge ve konular öne çıkar?","b":"Toroslar ve Çukurova; toprak sorunu, ağalık, ezilme ve kan davası; destan, efsane, masal ve ağıtlardan yararlanır."},{"f":"Aziz Nesin'in mizah anlayışının özelliği nedir?","b":"İlk şiir yazmış, sonra mizah öğeleri ağır basan öykülere yönelmiştir; toplumun aksayan yönlerini, çürümüş tipleri abartarak eleştirir."},{"f":"Muzaffer İzgü hangi tür öyküleriyle tanınır?","b":"Köy-kasabadan şehre göçün doğurduğu sıkıntıları mizahi bir tarzda anlatan, taşlama ve yergi arası öyküleriyle tanınır."},{"f":"Bekir Yıldız'ın eserlerinin konusu nedir?","b":"Güneydoğu Anadolu'dan ve Almanya'ya göç eden Türklerin hayatlarından alınmış konulardır."},{"f":"Erdal Öz'ün eserlerinde hangi tema işlenir?","b":"Baskı karşısında bireylerin yalnızlığı, direnci ve umudu."},{"f":"Tarık Dursun K. hangi konuları işlemiştir?","b":"Gençlik serüvenleri, fabrika ve deniz işçileri, esnaf ve küçük memur sınıfının hayat mücadeleleri; şiirli, yoğun duyarlılıklı bir dille."},{"f":"\"Bireyin iç dünyasını esas alan sanatçılar\" hangi konuları işler?","b":"Kimlik sorunları, bilinçaltı, ahlak bunalımları, yalnızlık, vicdan azabı, Doğu-Batı sorunsalı, geçmiş-şimdi çatışması."},{"f":"Bireyin iç dünyasını esas alan sanatçılardan dört isim söyleyin.","b":"Peyami Safa, Ahmet Hamdi Tanpınar, Abdülhak Şinasi Hisar, Tarık Buğra (Samiha Ayverdi, Mustafa Kutlu da bu gruptandır)."},{"f":"Peyami Safa hangi anlatım tekniğinin ustasıdır?","b":"Bilinç akışı, iç konuşma gibi tekniklerle psikolojik roman türünün ustasıdır."},{"f":"Peyami Safa'nın \"Fatih-Harbiye\" romanı neyi işler?","b":"Doğu-Batı çatışmasını, iki farklı kültürü simgeleyen Fatih ve Harbiye semtlerini karşı karşıya getirir."},{"f":"Peyami Safa hangi takma adla polisiye roman yazmıştır?","b":"\"Server Bedi\" takma adıyla."},{"f":"Tarık Buğra'nın \"Küçük Ağa\" romanı neyi anlatır?","b":"Kurtuluş Savaşı'na katılan Anadolu halkını yükseltici bir bakış açısıyla ele alır."},{"f":"Ahmet Hamdi Tanpınar hangi şairlerin etkisinde kalmıştır ve hangi türlerde eser vermiştir?","b":"Yahya Kemal ve Ahmet Haşim'in etkisinde kalmıştır; roman, öykü, deneme, makale, edebiyat tarihi ve şiir türlerinde eser vermiştir."},{"f":"Tanpınar'ın şiirlerinde önem verdiği üç kavram nedir?","b":"Rüya, bilinçaltı ve zaman."},{"f":"Tanpınar'ın \"Huzur\" romanı neyi anlatır?","b":"II. Dünya Savaşı arifesinde (1939) İstanbul'da Mümtaz ile Nuran'ın aşkı üzerinden Doğu-Batı, gelenek ve medeniyet sorgulanır."},{"f":"Tanpınar'ın \"Saatleri Ayarlama Enstitüsü\" romanı neyi eleştirir?","b":"Uygarlık (Batılılaşma) değişiminin birey üzerindeki sancılarını; dengesiz, arayış içindeki kişiler aracılığıyla dönemi eleştirir."},{"f":"Samiha Ayverdi'nin romanlarında hangi öğeler önemli yer tutar?","b":"Tasavvufi mesajlar; şeyh, tekke, tarikat, cami, cemaat gibi dinsel öğeler ve eski İstanbul kültürü."},{"f":"Abdülhak Şinasi Hisar hangi türde tanınmıştır?","b":"Roman ve anı (hatıra) türünde; geçmişe özlem, tasvir ve kültür onun yapıtlarında en önemli ögelerdir."},{"f":"Mustafa Kutlu'nun hikayelerinin anlatım özelliği nedir?","b":"İç konuşmalar ve diyaloglar canlıdır; farklı metinlerden alınmış parçalarla zenginleştirilmiştir."},{"f":"Memduh Şevket Esendal Türk edebiyatında hangi öykü tarzının ilk temsilcisidir?","b":"\"Çehov tarzı\" durum öykünün ilk temsilcisidir; kişilerin günlük yaşamdaki dikkat çekmeyen yönlerini anlatır."},{"f":"Modernizmin roman-öyküye getirdiği anlatım yeniliği nedir?","b":"Geleneksel yapı ve anlatım bırakılmış, bilinç akışı tekniği kullanılmış; olay-karakter yerine imge ve simgeler öne çıkmıştır."},{"f":"Modernizmi etkileyen düşünürlerden üç isim sayın.","b":"Darwin, Marx, Freud (ayrıca Hegel ve Jung)."},{"f":"Postmodernizm ne zaman ve hangi düşünceyle gelişmiştir?","b":"II. Dünya Savaşı'ndan sonra, modernizmin sorgulanması gerektiği düşüncesiyle gelişmiştir."},{"f":"Postmodern romanda \"üstkurmaca\" ne demektir?","b":"Yazarın, anlattığının bir kurmaca olduğunu okuyucuya açıkça ifade etmesidir."},{"f":"Postmodern romanda \"metinlerarasılık\" ne demektir?","b":"Yazarın başka metinlerden yararlanmasıdır; alıntı (kolaj), montaj, pastiş, eklektisizm gibi tekniklerle yapılır."},{"f":"Modernizm/postmodernizm temsilcilerinden dört isim sayın.","b":"Oğuz Atay, Yusuf Atılgan, Orhan Pamuk, Adalet Ağaoğlu (Latife Tekin, Bilge Karasu de bu gruptandır)."},{"f":"Orhan Pamuk hangi ödülü kazanan ilk Türk yazardır?","b":"2006'da Nobel Edebiyat Ödülü'nü kazanmıştır."},{"f":"Orhan Pamuk'un \"Kara Kitap\" romanının özelliği nedir?","b":"Simgesel değerlerle yüklü postmodern bir romandır."},{"f":"Yusuf Atılgan'ın romanlarının teması nedir?","b":"Yalnızlık ve psikolojik yabancılaşma; \"Aylak Adam\" ve \"Anayurt Oteli\" başlıca romanlarıdır."},{"f":"Oğuz Atay'ın \"Tutunamayanlar\" romanı neden önemlidir?","b":"İç monolog, bilinç akışı gibi yeni anlatım tekniklerini kullanır; postmodern romanın yolunu açan eserdir."},{"f":"Adalet Ağaoğlu'nun anlatımdaki yeniliği nedir?","b":"\"Tek anlatıcıya son vermek\", yer-zaman ögelerine değişiklik getirmek; bilinç akışı ve iç monolog gibi tekniklerden yararlanmıştır."},{"f":"Haldun Taner Türk tiyatrosuna hangi türün ilk örneğini kazandırmıştır?","b":"\"Keşanlı Ali Destanı\" ile ilk epik tiyatro örneğini kazandırmıştır; kabare tiyatrosunun kuruluşuna da öncülük etmiştir."},{"f":"Nezihe Meriç'in eserlerinde hangi konu işlenir?","b":"Genç kız ve kadınların iç yalnızlığı; örf ve adetlerin sıktığı kadınların psikolojisi."},{"f":"Füruzan'ın eserlerinde hangi konular işlenir?","b":"Orta sınıfın acısı; İstanbul'un kenar semtlerindeki yoksul insanlar, göçmenler ve kuşak çatışmaları."},{"f":"Vüs'at O. Bener'in anlatım özelliği nedir?","b":"Çehov tarzı öykü anlayışını benimsemiştir; sonraki hikayelerinde soyut bir dünya kurar, hikayenin içine kendisi de girer."},{"f":"Bilge Karasu'nun eserlerinde öne çıkan tema nedir?","b":"Bireyin yalnızlığı ve iletişim kuramayışı; yapıtlarında yorumu okuyucuya bırakır."},{"f":"Ferit Edgü hangi akımdan etkilenmiştir?","b":"Varoluşçuluk akımından etkilenmiştir; aydın kesimin uyumsuzluğunu ve yalnızlığını anlatır."},{"f":"Hasan Ali Toptaş hangi anlatım tekniğini kullanır?","b":"Bilinç akışı tekniğini kullanır; sözcüklerle oynayarak şiirsel bir dille yazar."},{"f":"İhsan Oktay Anar romanlarında neyi bir arada verir?","b":"Felsefeyi edebiyata sokar; kurguyu felsefi söylemlerle birleştirir, konularını tarihten alır."},{"f":"Rasim Özdenören'in hikayelerinde işlenen konular nelerdir?","b":"Bireyin yalnızlığı, yabancılaşması, kuşak çatışması; kültür şokuna karşı kişinin tasavvufa yönelmesi."},{"f":"Nazlı Eray'ın hikayelerinin ayırt edici özelliği nedir?","b":"Fantastik hikayeleriyle tanınır; düş ile gerçek arasında gizemli ve düşsel bir dünya anlatır."},{"f":"Leyla Erbil hangi temaları işler?","b":"Varoluşçu temalar; alışılmış toplum düzenine başkaldırıyı, dilin ve cümle yapısının değiştirilmesiyle anlatır."},{"f":"Latife Tekin'in romanlarındaki özgün anlatım nasıldır?","b":"Şiirsel üslup ve geleneksel anlatımdan yararlanarak oluşturduğu özgün bir tekniktir; \"Berci Kristin Çöp Masalları\"nda yoksulluğu masal ögeleriyle anlatır."},{"f":"Elif Şafak'ın romanlarında hangi temalar öne çıkar?","b":"\"Bit Palas\"ta yalnızlık-yabancılık-zaman; \"Araf\"ta kimlik bunalımı; \"Baba ve Piç\"te bir İstanbul ailesindeki kadın kuşakları."},{"f":"Selim İleri roman ve öykülerinde neyi amaçlar?","b":"İstanbul'da yaşamış edebiyatçıları canlandırmayı, üzeri tozla örtülmüş anıları hafızalarda yeniden harekete geçirmeyi amaçlar."},{"f":"Halikarnas Balıkçısı'nın gerçek adı nedir ve hangi türle tanınır?","b":"Cevat Şakir Kabaağaçlı'dır; deniz öyküleriyle tanınır ve \"mavi hümanizma\" akımını başlatmıştır."},{"f":"Oktay Akbal'ın yapıtlarındaki anlatım özelliği nedir?","b":"Deneme tarzına yakın şiirsel bir üslup; okurda biyografik roman izlenimi uyandıran \"ben merkezli\" bir anlatım."},{"f":"Tahsin Yücel'in \"Peygamberin Son Beş Günü\" adlı eseri neyi anlatır?","b":"İdeolojilerin insanları robotlaştırıp tabuların esiri etmesini alaycı bir üslupla anlatır."},{"f":"Tomris Uyar hangi ödülü iki kez kazanmıştır?","b":"Sait Faik Hikaye Armağanı'nı iki kez kazanmıştır."},{"f":"Ahmet Ümit hangi tür romanlarıyla tanınır?","b":"Polisiye roman yazarıdır (\"Sis ve Gece\", \"Kar Kokusu\", \"Beyoğlu Rapsodisi\" vb.)."},{"f":"Mustafa Necati Sepetçioğlu hangi tarihi konuları romanlaştırmıştır?","b":"Anadolu'nun Türkleşme-İslamlaşma sürecini ve Çanakkale Savaşı'nı (\"Çanakkale\" serisi) romanlaştırmıştır."},{"f":"Nihal Atsız hangi akımın önemli temsilcisidir?","b":"Türkçülük akımının önemli temsilcilerindendir; \"Bozkurtların Ölümü\", \"Bozkurtlar Diriliyor\" romanlarıyla tanınır."},{"f":"Cumhuriyet dönemi tiyatro yapıtlarının konu kaynağı nedir?","b":"Batılılaşmanın yarattığı değerler karmaşası, ekonomik sorunlar, aile içindeki olumsuz etkiler, aydınla halk arasındaki kopukluk."},{"f":"Cumhuriyet dönemi tiyatro yapıtları konularına göre nasıl sınıflandırılabilir?","b":"Köy oyunları, aile dramları-kadın, politik hiciv, tarihi oyunlar, felsefi (yalnızlık) oyunlar, kasaba/kenar mahalle oyunları, Almanya'ya giden işçiler."},{"f":"Orhan Asena'nın tiyatro anlayışının kaynağı nedir?","b":"Mitolojiden ve tarihten yararlanmıştır; \"Tiyatro tarihin sustuğu yerde başlar\" görüşündedir; toplumcu bir tiyatro yazarıdır."},{"f":"Güngör Dilmen hangi tiyatro alanında ve hangi üçlemesiyle tanınır?","b":"Absürt (uyumsuz) tiyatro alanında; \"Midas'ın Kulakları, Altınları, Kördüğümü\" üçlemesiyle tanınır."},{"f":"Cevat Fehmi Başkut'un tiyatro yapıtlarının konusu nedir?","b":"İnsanlar arasındaki çatışmalar; kişileri çoğunlukla ahlak bakımından eleştiren günlük toplum sorunları."},{"f":"Turan Oflazoğlu hangi konuları işler?","b":"Özellikle Osmanlı tarihinden yararlandığı tarihi konuları (\"Kösem Sultan\", \"Cem Sultan\", \"IV. Murat\")."},{"f":"Turgut Özakman'ın oyunlarının konusu nedir?","b":"Günlük yaşamın çelişkileri ve gülünç yönleri, nesiller arası çatışmalar; yakın tarih ve Kurtuluş Savaşı."},{"f":"Muhsin Ertuğrul neden \"çağdaş Türk tiyatrosunun kurucusu\" sayılır?","b":"Batı tiyatrosunu Türkiye'de kurumsallaştırmış, sadece tiyatrocu değil bu alanda fikir yazıları da yazmıştır."},{"f":"Haldun Taner tiyatro yapıtlarını kaç evreye ayırır ve son evre hangi türdür?","b":"Üç evreye ayrılır; son evre (1962 sonrası) \"kabare\" türündeki oyunlardır (Devekuşu Kabare Tiyatrosu 1967)."}]},{"id":"edb-13","name":"Edebiyat Akımları ve Dünya Edebiyatı","cards":[{"f":"Azerbaycan edebiyatının önemli şairi Şehriyar hangi şiiriyle tanınır?","b":"Heyder Baba'ya Selam şiiriyle; Azerbaycan folklorundan yararlanmıştır."},{"f":"Bahtiyar Vahapzade'nin (Azerbaycan) şiirlerindeki ayırt edici özellik nedir?","b":"Kendine özgü bir hiciv ve olay anlatım tarzı vardır."},{"f":"Cengiz Aytmatov hangi Türk edebiyatına mensuptur ve neyle tanınır?","b":"Kırgızistan Türkleri edebiyatına; savaş ve aşkı sanatlı bir üslupla işleyen dünyaca ünlü romancıdır (Cemile, Beyaz Gemi)."},{"f":"İsmail Gaspıralı'nın (Kırım) düşünce alanındaki ünlü sözü nedir?","b":"Dilde, fikirde, işte birlik; bunu Tercüman gazetesiyle halka ulaştırmıştır."},{"f":"Cengiz Dağcı'nın (Kırım) romanlarının ortak özelliği nedir?","b":"Otobiyografiktir; II. Dünya Savaşı'nı ve Kırım Türklerinin kaderini anlatır, eserlerini Türkçe yazmıştır."},{"f":"Özker Yaşın ve Osman Türkay hangi Türk edebiyatının şairleridir?","b":"Kıbrıs Türkleri edebiyatının şairleridir."},{"f":"Hümanizm (insancıllık) akımının temel görüşü nedir?","b":"Bütün insanları kardeş sayar; evrensellik esastır, milli unsurlar değil Antik Yunan-Latin sanatı örnek alınır."},{"f":"Hümanizmin temsilcilerinden üçünü say.","b":"Dante, Petrarca, Boccaccio (ayrıca Rabelais, Montaigne, Cervantes, Shakespeare)."},{"f":"Klasisizm (kuralcılık) ne zaman, nerede ve nasıl doğmuştur?","b":"17. yüzyılda Fransa'da; «1660 Ekolü» olarak da bilinir, ilkelerini Boileau Şiir Sanatı'nda belirlemiştir."},{"f":"Klasisizmdeki «üç birlik kuralı» neyi ifade eder?","b":"Tiyatroda olay, yer ve zaman birliğini; eylem tek, mekân ve süre sınırlı olmalıdır."},{"f":"Klasisizmde sanat ve kişi anlayışı nasıldır?","b":"Sanat sanat içindir ilkesi benimsenmiş; halktan değil seçkin ve olgun kişiler işlenmiştir."},{"f":"Klasisizmin temsilcilerinden üçünü say.","b":"Corneille, Racine, Moliere (ayrıca La Fontaine, Boileau, Descartes, La Bruyere)."},{"f":"Klasisizmden etkilenen Türk sanatçılar kimlerdir?","b":"Şinasi, Ahmet Vefik Paşa, Direktör Ali Bey."},{"f":"Romantizm hangi ülkelerde, ne zaman doğmuştur?","b":"18. yy'ın ikinci yarısında İngiltere ve Almanya'da; 19. yy'ın ilk yarısında Fransa'da yaygınlaşmıştır."},{"f":"Romantizmin kurallarını hangi yapıt ortaya koymuştur?","b":"Victor Hugo'nun Cromwell adlı oyununun önsözü."},{"f":"Hernani Kavgası nedir?","b":"1830'da Hugo'nun Hernani oyunu sahnelenince romantikler ve klasikler arasında çıkan, romantiklerin zaferiyle sonuçlanan tartışma."},{"f":"Romantizmde sanat anlayışı klasisizme göre nasıl değişmiştir?","b":"Sanat için sanat yerine toplum için sanat; akıl-sağduyu yerine duygu ve hayal ön plana çıkmıştır."},{"f":"Romantizmde sıkça işlenen çatışma ve tema nedir?","b":"İyi-kötü, ak-kara çatışması ve hürriyet isteği; tesadüf ve olağanüstülüklere de yer verilir."},{"f":"Romantizmin temsilcilerinden üçünü say.","b":"Victor Hugo, Lamartine, Chateaubriand (ayrıca A. de Musset, J.J. Rousseau, Byron, Goethe, Schiller, Puşkin)."},{"f":"Romantizmden etkilenen Türk sanatçılardan üçünü say.","b":"Namık Kemal, Ahmet Mithat Efendi, Abdülhak Hamit Tarhan (ayrıca Şemsettin Sami, Recaizade Mahmut Ekrem-şiir)."},{"f":"Realizm (gerçekçilik) nasıl ve ne zaman ortaya çıkmıştır?","b":"19. yy'ın ikinci yarısında Fransa'da, romantizme tepki olarak; yaşamı olduğu gibi aktarma ilkesindendir."},{"f":"Realizmin ilk örneği sayılan roman hangisidir?","b":"Gustave Flaubert'in Madame Bovary romanı."},{"f":"Realizmde anlatım ve gözlem nasıldır?","b":"Gözleme önem verilmiş, belgeden yararlanılmıştır; nesnellik esastır, sanatçı duygularını katmaz."},{"f":"Realizm zamanla hangi iki biçime bürünmüştür?","b":"Eleştirel gerçekçilik ve toplumcu (sosyalist) gerçekçilik."},{"f":"Realizmin temsilcilerinden üçünü say.","b":"Balzac, Stendhal, Flaubert (ayrıca Dostoyevski, Tolstoy, Çehov, Gogol, Dickens)."},{"f":"Realizmden etkilenen Türk sanatçılardan üçünü say.","b":"Recaizade Mahmut Ekrem, Halit Ziya Uşaklıgil, Refik Halit Karay (ayrıca Samipaşazade Sezai, Mehmet Rauf, Yakup Kadri, Halide Edip)."},{"f":"Natüralizmin kurucusu kimdir, görüşlerini hangi kitapta açıklamıştır?","b":"Emile Zola; Deneysel Roman adlı kitabında."},{"f":"Natüralizm hangi bilimsel görüşlerden etkilenmiştir?","b":"Determinizm ve Darwin'in Evrim Teorisi'nden; aynı nedenler aynı koşullarda aynı sonucu doğurur ilkesi benimsenmiştir."},{"f":"Natüralizmde yazarın tutumu nasıldır?","b":"Kişiliğini gizler, sadece gözlemlediklerini yazar; insanı fizyolojik yapısı, soyaçekimi ve çevresiyle ele alır."},{"f":"Natüralizmin temsilcilerinden ikisini say.","b":"Emile Zola, Alphonse Daudet (ayrıca Goncourt Kardeşler, Maupassant, Steinbeck)."},{"f":"Natüralizmden etkilenen Türk sanatçılar kimlerdir?","b":"Nabizade Nazım, Hüseyin Rahmi Gürpınar, Selahattin Enis."},{"f":"Parnasizm adı nereden gelir?","b":"Yunanistan'da şiir perilerinin yaşadığına inanılan Parnassos dağından."},{"f":"Parnasizm şiirde neyi savunur?","b":"Sanat için sanat ilkesini; gerçekçi/tasvirci şiiri ve biçim kusursuzluğunu (özellikle sone) esas alır."},{"f":"Parnasizmin temsilcilerinden ikisini say.","b":"Gautier, Heredia (ayrıca Banville, Lisle, Coppee, Prudhomme)."},{"f":"Parnasizmden etkilenen Türk sanatçılar kimlerdir?","b":"Tevfik Fikret, Yahya Kemal Beyatlı, Cenap Şahabettin."},{"f":"Sembolizm (simgecilik) ne zaman, nasıl doğmuştur?","b":"1885-1900 arası Fransa'da, parnasizme tepki olarak; adı Jean Moreas'ın bildirisiyle konmuştur."},{"f":"Sembolizmde şiirin anlatım yolu nasıldır?","b":"Gerçek değil, gerçeğin uyandırdığı etki anlatılır; duygular mecaz, istiare ve alegori gibi simgelerle işlenir."},{"f":"Sembolizmde müziğin (musikinin) önemi nedir?","b":"Musiki ve ahenk şiirde çok önemlidir; şiir dili müzikle bütünleştirilmeye çalışılmıştır."},{"f":"Sembolizmin temsilcilerinden ikisini say.","b":"Baudelaire, Verlaine (ayrıca Mallarme, Rimbaud, Valery, Poe)."},{"f":"Sembolizmden etkilenen Türk sanatçılardan ikisini say.","b":"Cenap Şahabettin, Ahmet Haşim (ayrıca Ahmet Muhip Dıranas, Cahit Sıtkı Tarancı, Ahmet Hamdi Tanpınar)."},{"f":"Empresyonizm (izlenimcilik) hangi sanat dalında ve nerede doğmuştur?","b":"19. yüzyılda Fransa'da resim sanatında doğmuş, sonra edebiyata yayılmıştır."},{"f":"Empresyonizmde sanatçı neyi anlatır?","b":"Nesnel gerçeği değil, o gerçeğin kendisinde uyandırdığı izlenimi; sanat için sanat benimsenir."},{"f":"Ekspresyonizm (dışavurumculuk) neyi öne çıkarır?","b":"Doğanın olduğu gibi temsilini değil, sanatçının duygularını ve iç dünyasını; 20. yy başında ortaya çıkmıştır."},{"f":"Ekspresyonizmin temsilcilerinden ikisini say.","b":"Franz Kafka, T.S. Eliot (ayrıca O'Neil, James Joyce)."},{"f":"Egzistansiyalizm (varoluşçuluk) temelde neyi sorgular?","b":"Bireyin varoluşunun anlamını; insanın kendi değerlerini kendisinin yarattığını savunur."},{"f":"Egzistansiyalizmi felsefi ve edebi olarak sistemleştiren düşünür kimdir?","b":"Jean Paul Sartre."},{"f":"Egzistansiyalist eserlerde sık işlenen tema nedir?","b":"Yabancılaşma; kötümserlik, hiçlik, bunaltı ve özgürlük teması sıkça işlenir."},{"f":"Egzistansiyalizmin temsilcilerinden üçünü say.","b":"Jean Paul Sartre, Albert Camus, Franz Kafka (ayrıca Simone de Beauvoir, A. Gide, Nietzsche)."},{"f":"Sürrealizm (gerçeküstücülük) kimin öncülüğünde doğmuştur?","b":"Andre Breton; Freud'un psikanaliz yöntemini edebiyata uygulamıştır."},{"f":"Sürrealizmde şiirin kaynağı nedir?","b":"Akıl ve bilinç değil; rüyalar, sayıklamalar ve kendinden geçme halleri (bilinçaltı)."},{"f":"Sürrealizmin temsilcilerinden ikisini say.","b":"Andre Breton, Paul Eluard (ayrıca Louis Aragon, Soupault, Prevert)."},{"f":"Sürrealizm Türk edebiyatında hangi toplulukları etkilemiştir?","b":"Garipçiler ve II. Yeniciler'i."},{"f":"Dadaizm hangi olaya tepki olarak, kim tarafından ortaya konmuştur?","b":"I. Dünya Savaşı'nın yıkıcı ortamına tepki olarak; bildirgesi 1918'de Tristan Tzara tarafından yayımlanmıştır."},{"f":"Dadaizmde sözcük seçimi ve edebi geleneğe tavır nasıldır?","b":"Her türlü edebi gelenek ve kurala karşıdır; sözcükler rastgele seçilir, şiir serbest çağrışımlara dayanır."},{"f":"Kübizm hangi sanat dalında doğmuş, kimin etkisiyle şiire yansımıştır?","b":"20. yy başında Fransa'da resim sanatında doğmuş, ressam Picasso'nun etkisiyle şiire yansımıştır."},{"f":"Kübist şiirin biçim özelliği nedir?","b":"Gerçeği akıl-mantıkla değil hayal gücüyle aktarır; noktalama işaretlerini kaldırmıştır."},{"f":"Fütürizm (gelecekçilik) kimin öncülüğünde ortaya çıkmıştır?","b":"İtalyan yazar Marinetti; geçmişten kopuş, yenilik ve değişikliğe yöneliş anlamındadır."},{"f":"Fütürizmin temsilcilerinden ikisini say.","b":"Marinetti, Mayakovski (ayrıca Nazım Hikmet)."},{"f":"Letrizm (harfçilik) ne zaman ve kimin öncülüğünde ortaya çıkmıştır?","b":"II. Dünya Savaşı'ndan sonra, Romen asıllı İsidore Isou'nun öncülüğünde."},{"f":"Letrizmin temel görüşü nedir?","b":"Harf ötesinde bir şey yoktur; aklımızda harf olmayan ya da harf olmayacak hiçbir şey yoktur."},{"f":"Homeros hangi destanların şairidir?","b":"İlyada ve Odysseia; epik destan türünün ilk ve en önemli temsilcisidir (Yunan)."},{"f":"Sophokles'in tragedyalarından ikisini say.","b":"Kral Oidipus ve Antigone (Yunan tragedya şairi)."},{"f":"Aristophanes hangi türde tanınır?","b":"Komedya; ilk büyük komedya şairidir (Kuşlar, Eşek Arıları)."},{"f":"Dante'nin başyapıtı hangisidir?","b":"İlahi Komedya; İtalyan Rönesans edebiyatının kurucusu sayılır."},{"f":"Boccaccio'nun veba salgınını çerçeve olay yapan eseri hangisidir?","b":"Decameron (On Gün)."},{"f":"Cervantes'in Don Kişot romanı neden önemlidir?","b":"Modern romanın başlangıcı sayılır; gerçekle hayal çatışmasını şövalyelik eleştirisiyle işler."},{"f":"Shakespeare'in en tanınmış tiyatro yapıtlarından üçünü say.","b":"Hamlet, Macbeth, Romeo ve Juliet (Rönesans İngiliz edebiyatı)."},{"f":"Chaucer'ın İngiliz edebiyatındaki önemli eseri hangisidir?","b":"Canterbury Hikâyeleri."},{"f":"Charles Dickens hangi tür romanlarıyla tanınır?","b":"Toplumsal ortamı işleyen, hem büyüklerin hem çocukların sevdiği romanlar (Oliver Twist, David Copperfield)."},{"f":"James Joyce'un modern romana getirdiği yenilik nedir?","b":"Bilinç akışı tekniği; kronolojik zaman akışını bırakmıştır (Ulysses, Dubliner'lar)."},{"f":"Goethe'nin en önemli tiyatro ve roman eserleri hangileridir?","b":"Faust (tiyatro) ve Genç Werther'in Acıları (roman); Alman romantizminin temsilcisidir."},{"f":"Franz Kafka'nın eserlerindeki başlıca tema nedir?","b":"Yabancılaşma; bireyin çağına, ailesine ve işine yabancılaşması (Dönüşüm, Dava, Şato)."},{"f":"Victor Hugo'nun en tanınmış romanlarından ikisi hangileridir?","b":"Sefiller ve Notre Dame'ın Kamburu."},{"f":"Balzac'ın romanlarını topladığı büyük seri hangi adla anılır?","b":"İnsanlık Komedyası (Goriot Baba, Eugenie Grandet gibi romanları içerir)."},{"f":"Stendhal'in realizmi temsil eden romanı hangisidir?","b":"Kızıl ile Kara."},{"f":"Flaubert neden realizmin kurucusu sayılır?","b":"Gözlemlerini kendi duygu ve düşüncelerine yer vermeden, olduğu gibi aktarmıştır (Madame Bovary)."},{"f":"Maupassant kısa hikâye türüne nasıl bir katkı yapmıştır?","b":"Maupassant tarzı (olay) öykücülüğünü geliştirmiştir; giriş-gelişme-sonuç düzenine dayanır."},{"f":"Emile Zola'nın natüralizmi örnekleyen romanı hangisidir?","b":"Germinal; maden işçilerinin çalışma koşullarını anlatır."},{"f":"Baudelaire'in sembolizmin öncüsü sayılan eseri hangisidir?","b":"Kötülük Çiçekleri."},{"f":"Jean Paul Sartre'ın varoluşçuluğu örnekleyen romanı hangisidir?","b":"Bulantı."},{"f":"Albert Camus'nün en tanınmış romanlarından ikisi hangileridir?","b":"Yabancı ve Veba."},{"f":"Jules Verne hangi türde eser vermiştir?","b":"Bilim kurgu; Denizler Altında Yirmi Bin Fersah, Seksen Günde Devri Alem gibi eserleri vardır."},{"f":"Puşkin Rus edebiyatında hangi akımın temsilcisidir?","b":"Romantizm; Yüzbaşının Kızı adlı eseriyle tanınır."},{"f":"Gogol'ün feodal düzeni eleştirdiği romanı hangisidir?","b":"Ölü Canlar."},{"f":"Dostoyevski'nin vicdan azabını işlediği romanı hangisidir?","b":"Suç ve Ceza."},{"f":"Tolstoy'un savaş ve toplumsal yaşamı geniş bir panoramada anlattığı romanı hangisidir?","b":"Savaş ve Barış."},{"f":"Çehov'un hikâyeciliğe getirdiği «Çehov tarzı» ne demektir?","b":"Olayların kronolojik değil, durumların kesitler halinde, sade bir üslupla anlatıldığı öykü tarzı."},{"f":"Maksim Gorki hangi akımın temsilcisidir?","b":"Toplumcu gerçekçilik; Ana adlı romanıyla tanınır."},{"f":"Henrik Ibsen neden «modern tiyatronun kurucusu» sayılır?","b":"Avrupa'da modern tiyatronun kurucularından sayılır (Bir Bebek Evi, Peer Gynt)."},{"f":"Mark Twain'in mizahi üslupla yazdığı ünlü romanı hangisidir?","b":"Tom Sawyer'in Maceraları."},{"f":"Hemingway'in en tanınmış kısa romanı hangisidir?","b":"İhtiyar Adam ve Deniz."},{"f":"Steinbeck'in toplumcu gerçekçiliği örnekleyen romanlarından ikisi hangileridir?","b":"Gazap Üzümleri ve Fareler ve İnsanlar."}]},{"id":"edb-14","name":"Yapıtlar ve Kahramanlar","cards":[{"f":"«Acımak» kimin eseridir, konusu nedir?","b":"Reşat Nuri Güntekin'in romanı; öğretmen Zehra'nın babasının ölümüyle katılaşıp acımasızlaşmasını, sonra pişmanlığını anlatır."},{"f":"«Aganta Burina Burinata» kimin eseridir, konusu nedir?","b":"Halikarnas Balıkçısı'nın romanı (1946); denizci Mahmut üzerinden deniz sevgisini ve gemicilik yaşamını anlatan ilk yapıtıdır."},{"f":"«Akif Bey» hangi türde ve kimin eseridir?","b":"Namık Kemal'in tiyatro yapıtı; deniz subayı Akif Bey'in eşi Dilruba'nın aldatılması ve ölümüyle sonuçlanan dramını anlatır."},{"f":"«Anayurt Oteli» kimin eseridir, konusu nedir?","b":"Yusuf Atılgan'ın romanı (1973); otel katibi Zebercet'in yalnızlığını ve saplantılı bekleyişini anlatan psikolojik romandır."},{"f":"«Ankara» kimin eseridir, konusu nedir?","b":"Yakup Kadri Karaosmanoğlu'nun romanı (1934); Selma Hanım üzerinden Kurtuluş Savaşı'ndan Cumhuriyet'e toplumsal değişimi anlatır."},{"f":"«Aşk-ı Memnu» kimin eseridir, kahramanları kimlerdir?","b":"Halit Ziya Uşaklıgil'in romanı (1900); Bihter, Behlül, Adnan Bey ve Nihal arasındaki yasak aşk dramını anlatır."},{"f":"«Araba Sevdası» kimin eseridir, konusu nedir?","b":"Recaizade Mahmut Ekrem'in romanı (1896); alafranga züppe Bihruz Bey'in Periveş'e olan gülünç aşkını anlatan yergi romanıdır."},{"f":"«Ateşten Gömlek» kimin eseridir, konusu nedir?","b":"Halide Edip Adıvar'ın romanı (1922); İzmir'in işgali ve Kurtuluş Savaşı'nda Ayşe'nin mücadelesini anlatır."},{"f":"«Ayaşlı ve Kiracıları» kimin eseridir, konusu nedir?","b":"Memduh Şevket Esendal'ın romanı (1934); Ankara'da bir apartmanda kiracı olan sıradan insanların gündelik yaşamını anlatır."},{"f":"«Bereketli Topraklar Üzerinde» kimin eseridir, konusu nedir?","b":"Orhan Kemal'in romanı (1954); Çukurova'ya çalışmaya gelen İflahsızın Yusuf, Köse Hasan ve Pehlivan Ali'nin öyküsüdür."},{"f":"«Beş Şehir» kimin eseridir, türü nedir?","b":"Ahmet Hamdi Tanpınar'ın (1946) deneme türündeki yapıtı; Ankara, Erzurum, Konya, Bursa ve İstanbul'u konu alır."},{"f":"«Bir Düğün Gecesi» kimin eseridir, konusu nedir?","b":"Adalet Ağaoğlu'nun romanı (1979); bir düğün gecesinde 12 Mart dönemi aydınlarının hesaplaşmasını anlatır."},{"f":"«Bir Gün Tek Başına» kimin eseridir, konusu nedir?","b":"Vedat Türkali'nin romanı (1975); 27 Mayıs 1960 öncesi özgürlük arayışını ve Kenan-Günsel aşkını anlatır."},{"f":"«Bizim Köy» kimin eseridir, önemi nedir?","b":"Mahmut Makal'ın köy notları (1950); Demirci köyündeki gündelik yaşamı anlatarak köy edebiyatı çığırını açan yapıttır."},{"f":"«Cemo» kimin eseridir, konusu nedir?","b":"Kemal Bilbaşar'ın romanı (1966); Doğu Anadolu'da ağa-devlet çatışmasında güzel Cemo'nun trajedisini anlatır."},{"f":"«Cezmi» kimin eseridir, önemi nedir?","b":"Namık Kemal'in romanı (1880); Türk edebiyatının ilk tarihi romanıdır; İran seferinde Adil Giray ile Şehriyar'ın aşkını anlatır."},{"f":"«Çalıkuşu» kimin eseridir, konusu nedir?","b":"Reşat Nuri Güntekin'in romanı (1922); öğretmen Feride'nin Anadolu'da öğretmenlik ve aşk serüvenini anlatır."},{"f":"«Çıkrıklar Durunca» kimin eseridir, konusu nedir?","b":"Sadri Ertem'in romanı (1931); Avrupa tekstilinin yerli dokuma tezgahlarını çökertmesini anlatan toplumcu-gerçekçi romandır."},{"f":"«Devlet Ana» kimin eseridir, konusu nedir?","b":"Kemal Tahir'in romanı (1967); Ertuğrul ve Osman Bey dönemini, Osmanlı Devleti'nin kuruluşunu anlatır."},{"f":"«Diyorlar ki» kimin eseridir, türü nedir?","b":"Ruşen Eşref Ünaydın'ın röportaj türündeki yapıtı (1918); dönemin ünlü sanatçılarıyla yapılan söyleşilerden oluşur."},{"f":"«Dokuzuncu Hariciye Koğuşu» kimin eseridir, konusu nedir?","b":"Peyami Safa'nın romanı (1930); hasta bir çocuğun hastane günlerini ve Nüzhet'e duyduğu aşkı anlatan yarı otobiyografik romandır."},{"f":"«Eylül» kimin eseridir, konusu nedir?","b":"Mehmet Rauf'un romanı (1901); Süreyya ile Necip arasındaki yasak aşkı işleyen, ilk psikolojik roman örneklerinden sayılır."},{"f":"«Fahim Bey ve Biz» kimin eseridir, konusu nedir?","b":"Abdülhak Şinasi Hisar'ın romanı (1941); hayalperest, başarısız girişimci Fahim Bey'in portresini anlatır."},{"f":"«Fatih-Harbiye» kimin eseridir, konusu nedir?","b":"Peyami Safa'nın romanı (1931); Neriman'ın Doğu (Fatih) ile Batı (Harbiye) kültürleri arasındaki bocalamasını anlatır."},{"f":"«Felatun Bey ile Rakım Efendi» kimin eseridir, konusu nedir?","b":"Ahmet Mithat Efendi'nin romanı (1875); alafranga Felatun Bey ile çalışkan Rakım Efendi'yi karşılaştırır."},{"f":"«Finten» kimin eseridir, türü nedir?","b":"Abdülhak Hamit Tarhan'ın (1916) tiyatro yapıtı; Londra'da geçen, manzum parçalar içeren bir dramdır."},{"f":"«Gulyabani» kimin eseridir, konusu nedir?","b":"Hüseyin Rahmi Gürpınar'ın romanı (1912); bir konakta korku ve batıl inançları konu alan romandır."},{"f":"«Handan» kimin eseridir, konusu nedir?","b":"Halide Edip Adıvar'ın romanı (1912); psikolojik açıdan güçlü kadın kahraman Handan'ın mutsuz evliliğini anlatır."},{"f":"«Hanımın Çiftliği» kimin eseridir, konusu nedir?","b":"Orhan Kemal'in romanı (1961); Çukurova'da ağalık düzenini ve Güllü'nün mücadelesini anlatır."},{"f":"«Huzur» kimin eseridir, kahramanları kimlerdir?","b":"Ahmet Hamdi Tanpınar'ın romanı (1949); Mümtaz, Nuran, İhsan ve Suat'ın aşk ilişkilerini ve toplumsal bunalımı anlatır."},{"f":"«Hüküm Gecesi» kimin eseridir, konusu nedir?","b":"Yakup Kadri Karaosmanoğlu'nun romanı (1927); II. Meşrutiyet dönemi siyasi çekişmelerini gazeteci Ahmet Kerim üzerinden anlatır."},{"f":"«İbişin Rüyası» kimin eseridir, konusu nedir?","b":"Tarık Buğra'nın romanı (1970); Nahit'in ünlü kantocu Hatice'ye duyduğu karşılıksız aşkı ve Hatice'nin intiharını anlatır."},{"f":"«İnce Memed» kimin eseridir, konusu nedir?","b":"Yaşar Kemal'in romanı (1955); ağa zulmüne başkaldıran eşkıya İnce Memed'in sevgilisi Hatçe ile yaşadığı mücadeleyi anlatır."},{"f":"«İntibah» kimin eseridir, önemi nedir?","b":"Namık Kemal'in romanı (1876); Türk edebiyatının ilk edebi romanı sayılır; Ali Bey'in Mahpeyker'e duyduğu tutkulu aşkı anlatır."},{"f":"«Kalpaklılar-Doludizgin» kimin eseridir, konusu nedir?","b":"Samim Kocagöz'ün roman dizisi (1962-1963); Kurtuluş Savaşı'nda İzmir'in işgalini ve Gerede-Düzce'deki direnişi anlatır."},{"f":"«Kalp Ağrısı» kimin eseridir, konusu nedir?","b":"Halide Edip Adıvar'ın romanı (1924); Zeyno'nun genç bir üniversiteli olan Kenan'a duyduğu aşkını ve Milli Mücadele yıllarını anlatır."},{"f":"«Kaplumbağalar» kimin eseridir, konusu nedir?","b":"Fakir Baykurt'un romanı (1967); köylü Kır Abbas'ın hazine arazisini satın alma mücadelesini anlatır."},{"f":"«Karabibik» kimin eseridir, önemi nedir?","b":"Nabizade Nazım'ın romanı (1890); Türk edebiyatında realizmin ilk başarılı örneklerinden, ilk köy romanı sayılır."},{"f":"«Kayıp Aranıyor» kimin eseridir, konusu nedir?","b":"Sait Faik Abasıyanık'ın tek romanı (1953); emekli Konsolos Vildan Bey'in kızı Nevin'in babasının gizli geçmişini araştırmasını anlatır."},{"f":"«Kerem ile Aslı» hangi türdendir, konusu nedir?","b":"16. yüzyıldan gelen bir halk hikayesidir; Kerem ile Aslı'nın imkansız aşkını ve Kerem'in sevgilisi için yanışını anlatır."},{"f":"«Keşanlı Ali Destanı» kimin eseridir, önemi nedir?","b":"Haldun Taner'in oyunu (1964); Türkiye'nin ilk epik tiyatro denemesi kabul edilir; gecekondulu kabadayı Keşanlı Ali'yi anlatır."},{"f":"«Kırık Hayatlar» kimin eseridir, konusu nedir?","b":"Halit Ziya Uşaklıgil'in romanı (1924); doktor Ömer Behiç'in ailesindeki aşk hayal kırıklıklarını ve evlilik dışı ilişkileri anlatır."},{"f":"«Kiralık Konak» kimin eseridir, konusu nedir?","b":"Yakup Kadri Karaosmanoğlu'nun romanı (1922); Naim Efendi'nin konağı üzerinden üç kuşak çatışmasını ve Batılılaşmayı anlatır."},{"f":"«Koçyiğit Köroğlu» kimin eseridir, türü nedir?","b":"Ahmet Kutsi Tecer'in oyunu (1969); Köroğlu halk destanını konu alan bir tiyatro yapıtıdır."},{"f":"«Kurtlar Sofrası» kimin eseridir, konusu nedir?","b":"Attila İlhan'ın iki ciltlik romanı (1963-1964); Kurtuluş Savaşı sonrası kadrolaşma ve yozlaşmayı Mahmut Ersoy üzerinden anlatır."},{"f":"«Kuyucaklı Yusuf» kimin eseridir, konusu nedir?","b":"Sabahattin Ali'nin romanı (1937); kaymakam Selahattin Bey'in evlatlığı Yusuf'un haksızlıklara karşı verdiği mücadeleyi anlatır."},{"f":"«Küçük Ağa» kimin eseridir, konusu nedir?","b":"Tarık Buğra'nın romanı (1963); Kuvayı Milliyeci Mehmet Reşit Efendi'nin (İstanbullu Hoca/Küçük Ağa) Akşehir'deki direnişini anlatır."},{"f":"«Kürk Mantolu Madonna» kimin eseridir, konusu nedir?","b":"Sabahattin Ali'nin romanı (1943); Raif Efendi'nin ressam Maria Puder'e duyduğu derin ve içine kapanık aşkını anlatır."},{"f":"«Mai ve Siyah» kimin eseridir, konusu nedir?","b":"Halit Ziya Uşaklıgil'in romanı (1897); şair Ahmet Cemil'in idealleri ile hayatın gerçekleri arasındaki çatışmasını anlatır."},{"f":"«Matmazel Noraliya'nın Koltuğu» kimin eseridir, konusu nedir?","b":"Peyami Safa'nın romanı; Ferit'in maddecilik ile maneviyat arasında yaşadığı bunalımı ve manevi arayışını anlatır."},{"f":"«Memleket Hikayeleri» kimin eseridir, önemi nedir?","b":"Refik Halit Karay'ın öykü kitabı (1919); Anadolu'yu gerçekçi biçimde anlatan ilk öykülerden sayılır."},{"f":"«Murtaza» kimin eseridir, konusu nedir?","b":"Orhan Kemal'in romanı (1952); aşırı görev bilinciyle bekçilik yapan Murtaza'nın çevresiyle çatışmasını ve trajedisini anlatır."},{"f":"«Mürebbiye» kimin eseridir, konusu nedir?","b":"Hüseyin Rahmi Gürpınar'ın romanı (1899); yabancı mürebbiye Anjel'in evdeki ahlaksızlıklarını yergiyle anlatır."},{"f":"«Nur Baba» kimin eseridir, konusu nedir?","b":"Yakup Kadri Karaosmanoğlu'nun romanı (1922); bir tekke şeyhi olan Nur Baba'nın müritlerini istismar edişini anlatır."},{"f":"«Ölmez Otu» kimin eseridir, konusu nedir?","b":"Yaşar Kemal'in romanı (1968); zulüm gören köylü kadın Meryemce ve oğlu Uzunca Ali'nin öyküsünü anlatır."},{"f":"«Saatleri Ayarlama Enstitüsü» kimin eseridir, konusu nedir?","b":"Ahmet Hamdi Tanpınar'ın romanı (1961); Hayri İrdal'ın hayatı üzerinden toplumsal modernleşmeyi yeren bir hiciv romanıdır."},{"f":"«Sergüzeşt» kimin eseridir, önemi nedir?","b":"Sami Paşazade Sezai'nin romanı (1899); cariye Dilber'in trajedisini anlatır; Batılı öykücülüğe yakın realist örneklerdendir."},{"f":"«Seyahatname» kimin eseridir, türü nedir?","b":"Evliya Çelebi'nin 17. yüzyılda yazdığı 10 ciltlik gezi yazısıdır; İstanbul'dan başlayıp gezdiği ülke ve şehirleri anlatır."},{"f":"«Sinekli Bakkal» kimin eseridir, konusu nedir?","b":"Halide Edip Adıvar'ın romanı (1936); II. Abdülhamit dönemi İstanbul'unda Rabia'nın hayatını ve sanatını anlatır."},{"f":"«Sodom ve Gomore» kimin eseridir, konusu nedir?","b":"Yakup Kadri Karaosmanoğlu'nun romanı (1928); işgal altındaki İstanbul'da değer yozlaşmasını Sami Bey ailesi üzerinden anlatır."},{"f":"«Şair Evlenmesi» kimin eseridir, önemi nedir?","b":"İbrahim Şinasi'nin oyunu (1859); Türk edebiyatının Batılı anlamda ilk tiyatro yapıtıdır; görücü usulü evliliği eleştirir."},{"f":"«Şık» kimin eseridir, konusu nedir?","b":"Hüseyin Rahmi Gürpınar'ın romanı (1889); alafranga züppe Şatırzade Şöhret Bey'in gülünç hallerini yergiyle anlatır."},{"f":"«Şipsevdi» kimin eseridir, konusu nedir?","b":"Hüseyin Rahmi Gürpınar'ın romanı (1911); alafrangalık hevesindeki Meftun Bey'in çıkarcılığını ve çöküşünü anlatır."},{"f":"«Taaşşuk-ı Talat ve Fitnat» kimin eseridir, önemi nedir?","b":"Şemsettin Sami'nin romanı (1872); Türk edebiyatının ilk yerli romanıdır; Talat ile Fitnat'ın görücü usulüne karşı aşkını anlatır."},{"f":"«Tutunamayanlar» kimin eseridir, konusu nedir?","b":"Oğuz Atay'ın romanı (1973); Selim Işık ve arkadaşı Turgut Özben üzerinden topluma uyumsuzluğu anlatan modernist romandır."},{"f":"«Vatan yahut Silistre» kimin eseridir, önemi nedir?","b":"Namık Kemal'in oyunu (1873); sahnelenen ilk Türk tiyatro yapıtıdır; İslam Bey'in Silistre savunmasındaki vatan sevgisini anlatır."},{"f":"«Vurun Kahpeye» kimin eseridir, konusu nedir?","b":"Halide Edip Adıvar'ın romanı (1926); öğretmen Aliye'nin işbirlikçilikle suçlanıp linç edilerek öldürülmesini anlatır."},{"f":"«Yaban» kimin eseridir, konusu nedir?","b":"Yakup Kadri Karaosmanoğlu'nun romanı (1932); sakat gazi Ahmet Celal'in bir Anadolu köyünde yaşadığı yabancılaşmayı anlatır."},{"f":"«Yaprak Dökümü» kimin eseridir, konusu nedir?","b":"Reşat Nuri Güntekin'in romanı (1930); Ali Rıza Bey ailesinin çocuklarının kötü yollara sapmasıyla dağılışını anlatır."},{"f":"«Yer Demir Gök Bakır» kimin eseridir, konusu nedir?","b":"Yaşar Kemal'in romanı (1963); yoksul köylülerin efsanevi bir kurtarıcı bekleyişini anlatır; Dağın Öte Yüzü üçlemesindendir."},{"f":"«Yeşil Gece» kimin eseridir, konusu nedir?","b":"Reşat Nuri Güntekin'in romanı (1928); softa çevresine karşı mücadele eden öğretmen Şahin'in Anadolu'daki direnişini anlatır."},{"f":"«Yılanların Öcü» kimin eseridir, konusu nedir?","b":"Fakir Baykurt'un romanı (1959); köyde su ve toprak yüzünden çıkan Irazca ile oğlu Kara Bayram'ın çatışmasını anlatır."},{"f":"«Yılkı Atı» kimin eseridir, konusu nedir?","b":"Abbas Sayar'ın romanı (1970); yaşlanınca sürüden kovulan Doru kısrağın hayatta kalma mücadelesini anlatır."},{"f":"«Yorgun Savaşçı» kimin eseridir, konusu nedir?","b":"Kemal Tahir'in romanı (1965); Mondros Ateşkesi'nden Kurtuluş Savaşı'na uzanan dönemi Yüzbaşı Cemil üzerinden anlatır."},{"f":"«Zehra» kimin eseridir, önemi nedir?","b":"Nabizade Nazım'ın romanı (1896); Türk edebiyatında ilk psikolojik roman denemesi sayılır; kıskançlık temalıdır."},{"f":"«Feride» hangi eserin kahramanıdır?","b":"Reşat Nuri Güntekin'in «Çalıkuşu» romanının kahramanıdır; Anadolu'da öğretmenlik yapan idealist genç kızdır."},{"f":"«Bihter» ve «Behlül» hangi eserin kahramanlarıdır?","b":"Halit Ziya Uşaklıgil'in «Aşk-ı Memnu» romanının kahramanlarıdır; yasak aşk yaşarlar."},{"f":"«Ali Bey» ve «Mahpeyker» hangi eserin kahramanlarıdır?","b":"Namık Kemal'in «İntibah» romanının kahramanlarıdır; Türk edebiyatının ilk edebi romanı sayılır."},{"f":"«Rakım Efendi» ve «Felatun Bey» hangi eserin kahramanlarıdır?","b":"Ahmet Mithat Efendi'nin «Felatun Bey ile Rakım Efendi» romanının kahramanlarıdır."},{"f":"«Ahmet Celal» hangi eserin kahramanıdır?","b":"Yakup Kadri Karaosmanoğlu'nun «Yaban» romanının kahramanıdır; sakat bir gazidir, Anadolu'ya yabancılaşır."},{"f":"«Mümtaz» ve «Nuran» hangi eserin kahramanlarıdır?","b":"Ahmet Hamdi Tanpınar'ın «Huzur» romanının kahramanlarıdır."},{"f":"«Rabia» hangi eserin kahramanıdır?","b":"Halide Edip Adıvar'ın «Sinekli Bakkal» romanının kahramanıdır; II. Abdülhamit dönemi İstanbul'unda yaşar."},{"f":"«Hayri İrdal» hangi eserin kahramanıdır?","b":"Ahmet Hamdi Tanpınar'ın «Saatleri Ayarlama Enstitüsü» romanının kahramanıdır."}]},{"id":"edb-15","name":"Türk Edebiyatında İlkler ve Dergiler","cards":[{"f":"Dünya edebiyatında ilk roman örneği hangisidir?","b":"Rabelais'in «Gargantua» adlı yapıtıdır."},{"f":"Dünya edebiyatında ilk modern roman hangisidir?","b":"Cervantes'in «Don Kişot» adlı romanıdır."},{"f":"Dünya edebiyatında ilk tarihi roman hangisidir?","b":"W. Scott'ın «Waverley» adlı romanıdır."},{"f":"Dünya edebiyatında ilk psikolojik roman hangisidir?","b":"Madam de La Fayette'in «Princesse de Cleves» adlı romanıdır."},{"f":"Dünya edebiyatında ilk öykü örneği hangisidir?","b":"G. Boccaccio'nun «Decameron» adlı yapıtıdır."},{"f":"Olay öyküsünün (Maupassant tarzı) öncüsü kimdir?","b":"Guy de Maupassant."},{"f":"Durum (kesit) öyküsünün öncüsü kimdir?","b":"A. Çehov."},{"f":"Deneme türünün kurucusu ve ikinci önemli ismi kimlerdir?","b":"Kurucusu Montaigne'dir; ikinci önemli isim Bacon'dır."},{"f":"Dünya edebiyatında ilk biyografi yazarı kimdir?","b":"Plutarkhos."},{"f":"Tarih türünün kurucusu kimdir?","b":"Heredot."},{"f":"Dünya edebiyatında ilk büyük destan şairi kimdir?","b":"Homeros."},{"f":"Dünya edebiyatında ilk trajedi sanatçısı kimdir?","b":"Aiskhylos."},{"f":"Dünya edebiyatında ilk büyük komedya sanatçısı kimdir?","b":"Aristophanes."},{"f":"Batı edebiyatında ilk fabl örneği kime aittir?","b":"Aisopos'un (Ezop) «Fabllar» adlı yapıtına."},{"f":"Doğu edebiyatında ilk fabl örneği kime aittir?","b":"Beydaba'nın «Kelile ve Dimne» adlı yapıtına."},{"f":"Klasisizmin kuramcısı kimdir?","b":"Boileau; «Şiir Sanatı» adlı yapıtıyla."},{"f":"Romantizmin kuramcısı kimdir?","b":"Victor Hugo; «Cromwell» adlı yapıtının önsözüyle."},{"f":"Dünya edebiyatında ilk realist roman hangisidir?","b":"G. Flaubert'in «Madam Bovary» adlı romanıdır."},{"f":"Natüralizmin kuramcısı kimdir?","b":"Emile Zola."},{"f":"Dünyada bilinen ilk destan hangisidir?","b":"Sümerlerin «Gılgamış Destanı»dır."},{"f":"Türklerin bilinen ilk alfabesi hangisidir?","b":"Göktürk (Orhun) alfabesidir."},{"f":"Bilinen ilk Türk şairi kimdir?","b":"Aprınçur Tigin."},{"f":"Türklerin bilinen en eski destanı hangisidir?","b":"Alper Tunga Destanı."},{"f":"Türkçenin ilk yazılı belgeleri nelerdir?","b":"Orhun Yazıtları (Orhun Abideleri); Türk adının geçtiği ilk metinlerdir."},{"f":"İslami dönem Türk edebiyatının ilk edebi eser örneği hangisidir?","b":"Yusuf Has Hacip'in «Kutadgu Bilig»idir; ilk didaktik mesnevi örneğidir."},{"f":"Türkçenin bilinen ilk sözlüğü ve ilk dil bilgisi kitabı hangisidir?","b":"Kaşgarlı Mahmud'un «Divanü Lügati't-Türk»üdür."},{"f":"Dede Korkut hikayelerinden ilk bahseden eser hangisidir?","b":"Reşidüddin'in «Camiü't-Tevarih» adlı yapıtıdır."},{"f":"Divan edebiyatının ilk temsilcisi kabul edilen sanatçı kimdir?","b":"Hoca Dehhani."},{"f":"Tasavvuf konusunda yazılan ilk eser hangisidir?","b":"Ahmed Yesevi'nin «Divan-ı Hikmet»idir."},{"f":"Anadolu Türkçesiyle yazılan ilk eser hangisidir?","b":"Ahmet Fakih'in «Çarhname»sidir."},{"f":"Türkçe ilk manzum mevlit metnini kim yazmıştır?","b":"Süleyman Çelebi; «Vesiletü'n-Necat» adlı yapıtıyla."},{"f":"Tanzimat döneminde ilk çeviri roman hangisidir?","b":"Yusuf Kamil Paşa'nın, Fenelon'dan çevirdiği «Telemak»tır."},{"f":"İlk resmi gazetemiz hangisidir?","b":"Takvim-i Vekayi (1831)."},{"f":"İlk Türk gazetecisi kimdir?","b":"Şinasi."},{"f":"Batılı anlamda ilk tiyatro yapıtımız hangisidir?","b":"Şinasi'nin «Şair Evlenmesi» adlı oyunudur (1859)."},{"f":"İlk makalemiz hangisidir?","b":"Şinasi'nin Tercüman-ı Ahval gazetesindeki «Mukaddime» başlıklı yazısıdır."},{"f":"İlk özel gazetemiz hangisidir?","b":"Şinasi ve Agah Efendi'nin çıkardığı Tercüman-ı Ahval'dir."},{"f":"Sahnelenen ilk tiyatro yapıtımız hangisidir?","b":"Namık Kemal'in «Vatan yahut Silistre»sidir (1873)."},{"f":"İlk öykü örneklerimiz hangileridir?","b":"Ahmet Mithat Efendi'nin «Letaif-i Rivayat» adlı yapıtıdır."},{"f":"Batılı anlamda ilk öykü örneklerimiz hangileridir?","b":"Sami Paşazade Sezai'nin «Küçük Şeyler» adlı yapıtıdır."},{"f":"Batılı anlamda ilk eleştiri yazısı ve yapıtımız hangisidir?","b":"Namık Kemal'in «Lisan-ı Osmani Edebiyatı Hakkında Bazı Mülahazat-ı Şamildir» yazısı; ilk eleştiri yapıtı «Tahrib-i Harabat»tır."},{"f":"İlk edebi romanımız hangisidir?","b":"Namık Kemal'in «İntibah» adlı romanıdır (1876)."},{"f":"Türk edebiyatında ilk tarihi roman hangisidir?","b":"Namık Kemal'in «Cezmi» adlı romanıdır (1880)."},{"f":"İlk polisiye romanımız hangisidir?","b":"Ahmet Mithat Efendi'nin «Esrar-ı Cinayat» adlı romanıdır."},{"f":"Batılı anlamda ilk antolojimiz hangisidir?","b":"Ziya Paşa'nın «Harabat» adlı üç ciltlik yapıtıdır."},{"f":"Türk edebiyatının ilk köy romanı hangisidir?","b":"Nabizade Nazım'ın «Karabibik» adlı romanıdır (1890)."},{"f":"Türk edebiyatında ilk realist roman hangisidir?","b":"Recaizade Mahmut Ekrem'in «Araba Sevdası» adlı romanıdır (1896)."},{"f":"İlk kadın romancımız kimdir?","b":"Fatma Aliye Hanım."},{"f":"Türk edebiyatında ilk mensur şiir örneği hangisidir?","b":"Halit Ziya Uşaklıgil'in «Mensur Şiirler»idir."},{"f":"Türk edebiyatında ilk psikolojik roman hangisidir?","b":"Mehmet Rauf'un «Eylül» adlı romanıdır (1901)."},{"f":"Şiirde anjambmanı ilk kullanan şairimiz kimdir?","b":"Tevfik Fikret."},{"f":"Çocuklar için yazılmış ilk şiir kitabımız hangisidir?","b":"Tevfik Fikret'in «Şermin» adlı yapıtıdır."},{"f":"İlk edebi beyanname (bildiri) yayımlayan topluluk hangisidir?","b":"Fecriati topluluğudur."},{"f":"Röportaj türünün ilk örneği hangisidir?","b":"Ruşen Eşref Ünaydın'ın «Diyorlar ki» adlı yapıtıdır (1918)."},{"f":"«Milli Edebiyat» ifadesini ilk kez hangi dergi kullanmıştır?","b":"Genç Kalemler dergisi."},{"f":"Cumhuriyet dönemi köy romancılığının ilk örneği hangisidir?","b":"Yakup Kadri Karaosmanoğlu'nun «Yaban» adlı romanıdır (1932)."},{"f":"Serbest ölçüyü Türk şiirinde ilk kez kullanan şair kimdir?","b":"Nazım Hikmet."},{"f":"Türk tiyatrosunun ilk epik oyunu hangisidir?","b":"Haldun Taner'in «Keşanlı Ali Destanı» adlı yapıtıdır (1964)."},{"f":"Sahneye çıkan ilk Türk kadın oyuncu kimdir?","b":"Afife Jale."},{"f":"«A Dergisi» (1956-1960) hakkında ne biliyorsun?","b":"Yönetmeni Edip Özyürek'tir, 29 sayı çıkmıştır; İkinci Yeni akımına paralel, çağdaş sanat akımlarına açık bir dergidir."},{"f":"«Ağaç» dergisi (1936) kimin öncülüğünde çıkmıştır?","b":"Necip Fazıl Kısakürek'in; milli, ruhçu, Anadolucu bir sanat anlayışını benimsemiştir, 17 sayı çıkmıştır."},{"f":"«Aile» dergisi (1947-1952) hakkında ne biliyorsun?","b":"Vedat Nedim Tör'ün sahibi ve sorumlu yönetmeni olduğu; edebiyat, sağlık, gezi, çocuk ve aile mutluluğu konularını kapsayan dergidir."},{"f":"«Akbaba» dergisi hakkında ne biliyorsun?","b":"Yusuf Ziya ve Orhan Seyfi'nin çıkardığı (1922-1977), Türkiye'nin en uzun soluklu mizah-karikatür dergisidir."},{"f":"«Ay Dede» dergisi (1922) hakkında ne biliyorsun?","b":"Refik Halit Karay tarafından çıkarılan, Kurtuluş Savaşı'na karşı çıkan mizah dergisidir."},{"f":"«Büyük Doğu» dergisi (1943-1955) hakkında ne biliyorsun?","b":"Necip Fazıl Kısakürek'in dergisidir; İslamcı-mistik dünya görüşüyle politik mücadele aracı olmuştur, 30 sayı çıkmıştır."},{"f":"«Çınaraltı» dergisi (1941-1944) hakkında ne biliyorsun?","b":"Orhan Seyfi ve Yusuf Ziya'nın çıkardığı Türkçü fikir ve sanat dergisidir."},{"f":"«Dergah» dergisi hakkında ne biliyorsun?","b":"1921-1923'te Mustafa Nihat Özön tarafından çıkarılmış; 1990'da Ezel Erverdi tarafından yeniden çıkarılmıştır."},{"f":"«Diriliş» dergisi kimin çıkardığı bir dergidir?","b":"Sezai Karakoç'un; İslami-mistik duyarlılıktaki şiir ve düşünce dergisidir."},{"f":"«Genç Kalemler» dergisi (1910-1912) hakkında ne biliyorsun?","b":"Ömer Seyfettin ve Ali Canip'in çıkardığı, Milli Edebiyatın dil savunuculuğunu yapan dergidir."},{"f":"«Hisar» dergisi hakkında ne biliyorsun?","b":"1950-1957 ve 1964-1980 yıllarında Munis Faik Ozansoy başkanlığında çıkmıştır."},{"f":"«Kadro» dergisi (1932-1934) hakkında ne biliyorsun?","b":"İmtiyaz sahibi Yakup Kadri'dir; Şevket Süreyya Aydemir, Burhan Belge, Vedat Nedim Tör'ün kadrosunda; devrimci, toplumcu, ulusal kurtuluşu savunur."},{"f":"«Mavera» dergisi (1976) kimler tarafından kurulmuştur?","b":"Cahit Zarifoğlu, Erdem Beyazıt, Rasim Özdenören, Alaeddin Özdenören ve Mehmet Akif İnan tarafından."},{"f":"«Papirüs» dergisi (1966-1970) kimin çıkardığı bir dergidir?","b":"Cemal Süreya'nın çıkardığı edebiyat dergisidir."},{"f":"«Resimli Ay» dergisi (1924-1930) hakkında ne biliyorsun?","b":"Zekeriya Sertel'in çıkardığı gerçekçi bir halk dergisidir."},{"f":"«Türk Dili» dergisi (1951-...) hangi kurumun yayınıdır?","b":"Türk Dil Kurumu'nun (TDK) çıkardığı aylık dil ve edebiyat dergisidir."},{"f":"«Türk Edebiyatı» dergisinin (1972-...) kurucusu kimdir?","b":"Ahmet Kabaklı."},{"f":"«Türk Yurdu» dergisi (1911-1931) kimin yayın organıdır?","b":"Türk Yurdu Cemiyeti'nin yayın organıdır."},{"f":"«Ülkü» dergisi (1933-1950) hakkında ne biliyorsun?","b":"Ankara Halkevi'nin yayın organıdır; resmi ideolojinin yayıcısıdır, Fuat Köprülü yönetiminde köycülük düşüncesi ağır basar."},{"f":"«Varlık» dergisinin kurucuları kimlerdir?","b":"Yaşar Nabi Nayır, Nahit Sırrı Örik ve Sabri Esat Siyavuşgil; 1933'ten günümüze aksamadan yayımlanan en uzun ömürlü edebiyat dergisidir."},{"f":"«Yeni Dergi» (1964-1975) kimin çıkardığı bir dergidir?","b":"Mehmet Fuat'ın çıkardığı edebiyat dergisidir."},{"f":"«Sultanü'ş-şuara» (şairler sultanı) unvanı kime verilmiştir?","b":"Baki."},{"f":"«Izdırap şairi» kimdir?","b":"Fuzuli."},{"f":"«Zevk ve eğlence şairi» / «Lale devri şairi» kimdir?","b":"Nedim."},{"f":"«Hiciv üstadı» kimdir?","b":"Nefi."},{"f":"«Hacı Kalfa» lakaplı sanatçı kimdir?","b":"Katip Çelebi."},{"f":"«Vatan şairi» ve «Hürriyet şairi» kimdir?","b":"Namık Kemal."},{"f":"«Şair-i Azam» ve «Tezatlar şairi» kimdir?","b":"Abdülhak Hamit Tarhan."},{"f":"«Mistik şair» kimdir?","b":"Necip Fazıl Kısakürek."},{"f":"«Milli şair» / «Türk şairi» kimdir?","b":"Mehmet Emin Yurdakul."},{"f":"Sokağı edebiyata getiren romancı kimdir?","b":"Hüseyin Rahmi Gürpınar."},{"f":"«Server Bedii» takma adını kullanan yazar kimdir?","b":"Peyami Safa."},{"f":"«Ağıtlar şairi» kimdir?","b":"Recaizade Mahmut Ekrem."},{"f":"«Bayrak şairi» kimdir?","b":"Arif Nihat Asya."},{"f":"«Evler şairi» kimdir?","b":"Behçet Necatigil."},{"f":"«Çimdik» takma adını kullanan yazar kimdir?","b":"Yusuf Ziya Ortaç."},{"f":"«Kirpi» takma adını kullanan yazar kimdir?","b":"Refik Halit Karay."},{"f":"«Yazı makinesi» ve «Hace-i evvel» lakaplı yazar kimdir?","b":"Ahmet Mithat Efendi."},{"f":"«Ölüm şairi» kimdir?","b":"Cahit Sıtkı Tarancı."},{"f":"«İstanbul öykücüsü» kimdir?","b":"Sait Faik Abasıyanık."},{"f":"«Halikarnas Balıkçısı» takma adını kullanan yazar kimdir?","b":"Cevat Şakir Kabaağaçlı."},{"f":"«Deli Ozan» ve «Çamdeviren» lakaplı şair kimdir?","b":"Faruk Nafiz Çamlıbel."},{"f":"«İstanbul şairi» kimdir?","b":"Yahya Kemal Beyatlı."},{"f":"«Ümmetçi şair» kimdir?","b":"Mehmet Akif Ersoy."},{"f":"Sokağı şiire getiren şair kimdir?","b":"Orhan Veli Kanık."},{"f":"«Anadolu şairi» kimdir?","b":"Ömer Bedrettin Uşaklı."},{"f":"«Akşam şairi» kimdir?","b":"Ahmet Haşim."},{"f":"Roman türünde hiç yapıtı olmayan önemli sanatçılar kimlerdir?","b":"Şinasi, Ziya Paşa, Ahmet Vefik Paşa, Tevfik Fikret, Cenap Şahabettin, Yahya Kemal, Mehmet Akif, Ahmet Haşim gibi şairler roman yazmamıştır."},{"f":"Herhangi bir edebi topluluğa girmeyen «bağımsız» sanatçılarımızdan bazıları kimlerdir?","b":"Yahya Kemal Beyatlı, Mehmet Akif Ersoy, Hüseyin Rahmi Gürpınar, Ahmet Rasim gibi sanatçılar bağımsızdır."},{"f":"Türk edebiyatında en önemli «yapma destan» şairi kimdir?","b":"Fazıl Hüsnü Dağlarca."},{"f":"Şarkı türünde en çok eser veren (211 şarkısıyla) divan şairi kimdir?","b":"Enderunlu Vasıf."},{"f":"Türk edebiyatının en uzun ömürlü edebiyat dergisi hangisidir?","b":"Varlık dergisi (1933'ten günümüze kesintisiz yayımlanır)."},{"f":"Türk edebiyatında en fazla gazel yazan padişah kimdir?","b":"Kanuni Sultan Süleyman; «Muhibbi» mahlasıyla."},{"f":"Dokuz ciltlik hatıratıyla en çok anı yazan sanatçımız kimdir?","b":"Halit Ziya Uşaklıgil; ilk 5 cildi «Kırk Yıl», 6-7-8. cildi «Saray ve Ötesi», sonuncusu «Bir Acı Hikaye»dir."},{"f":"1940 sonrası «Garip» akımının öncüleri kimlerdir?","b":"Orhan Veli Kanık, Melih Cevdet Anday, Oktay Rifat Horozcu."},{"f":"«İkinci Yeni» akımının önemli isimlerinden bazıları kimlerdir?","b":"Turgut Uyar, Edip Cansever, Cemal Süreya, Ece Ayhan, İlhan Berk, Sezai Karakoç gibi şairler."},{"f":"Cumhuriyet'in ilanından 1940'a dek şiirde etkili iki temel yönelim nedir?","b":"Hececiler (Beş Hececiler ve izleyicileri) ve Serbestçiler (Nazım Hikmet öncülüğünde serbest ölçüyü kullananlar)."}]}]},{"subject":"Fizik","units":[{"id":"fiz-1","name":"Fizik Bilimine Giriş","cards":[{"f":"Fizik bilimi neyi inceler?","b":"Evrendeki olayları ve doğanın işleyişini yasalarla açıklayan temel bilim dalıdır."},{"f":"Fiziğin alt dalları nelerdir?","b":"Mekanik, termodinamik, elektromanyetizma, optik, katıhal fiziği, atom fiziği, nükleer fizik, yüksek enerji ve plazma fiziği."},{"f":"Mekanik hangi konularla ilgilenir?","b":"Cisimlerin hareketi, kuvvetler ve denge durumlarıyla ilgilenir."},{"f":"Termodinamik hangi konularla ilgilenir?","b":"Isı, sıcaklık ve enerji dönüşümleriyle ilgilenir."},{"f":"Elektromanyetizma neyi inceler?","b":"Elektrik ve manyetizma olaylarını ve aralarındaki ilişkiyi inceler."},{"f":"Optik neyi inceler?","b":"Işığın davranışını; yansıma, kırılma, görüntü oluşumu gibi olayları inceler."},{"f":"Atom fiziği ile nükleer fizik arasındaki fark nedir?","b":"Atom fiziği atomun yapısını, nükleer fizik atom çekirdeğiyle ilgili olayları (fisyon, füzyon) inceler."},{"f":"Plazma nedir?","b":"Gazın çok yüksek sıcaklıkta iyonlaşmış, elektrik yüklü tanecikler içeren dördüncü hâlidir."},{"f":"Fiziğin felsefeyle ilişkisine bir örnek nedir?","b":"Evrenin doğası ve bilginin kaynağı gibi sorular hem fizik hem felsefenin ilgi alanına girer."},{"f":"Fiziğin biyolojiyle ilişkisine bir örnek nedir?","b":"Kalp atışının elektriksel sinyalleri veya gözün optik sistemi gibi konular biyofizikle açıklanır."},{"f":"Fiziğin sanatla ilişkisine bir örnek nedir?","b":"Perspektif çiziminde ışığın davranışı ve müzikte ses dalgalarının frekans-tını ilişkisi örnek verilebilir."},{"f":"Fiziğin sporla ilişkisine bir örnek nedir?","b":"Bir atletin sıçrama açısı veya topun hareketi kuvvet ve hareket yasalarıyla açıklanır."},{"f":"Temel büyüklük nedir?","b":"Başka büyüklüklere bağlı olmayan, doğrudan tanımlanan büyüklüktür (uzunluk, kütle, zaman gibi)."},{"f":"Türetilmiş büyüklük nedir?","b":"Temel büyüklüklerin birleşiminden elde edilen büyüklüktür (hız, kuvvet, alan gibi)."},{"f":"SI birim sisteminde bazı temel büyüklüklerin birimleri nelerdir?","b":"Uzunluk (metre), kütle (kilogram), zaman (saniye), sıcaklık (kelvin), akım (amper)."},{"f":"Skaler büyüklük nedir?","b":"Sadece sayısal değer ve birimle tanımlanan, yönü olmayan büyüklüktür (kütle, sıcaklık, sürat gibi)."},{"f":"Vektörel büyüklük nedir?","b":"Büyüklüğün yanında yönü de belirtilmesi gereken büyüklüktür (hız, kuvvet, yer değiştirme gibi)."},{"f":"SI birim sistemi neden kullanılır?","b":"Bilimsel ölçümlerde dünya genelinde ortak bir dil sağlamak için kullanılan uluslararası birim sistemidir."},{"f":"MEB programında sayılan bilim araştırma merkezleri hangileridir?","b":"TÜBİTAK, TAEK, ASELSAN, CERN, NASA, ESA."},{"f":"TÜBİTAK nedir?","b":"Türkiye'nin bilimsel ve teknolojik araştırmalarını desteklemek için kurulan resmi kurumudur."},{"f":"CERN nedir?","b":"Avrupa'da kurulu, parçacık fiziği alanında büyük hızlandırıcılarla araştırma yapan uluslararası merkezdir."},{"f":"NASA ve ESA hangi alanda çalışır?","b":"NASA (ABD) ve ESA (Avrupa), uzay araştırmaları ve uzay teknolojileri geliştiren kurumlardır."},{"f":"Bilimsel araştırmalarda etik ilkelere uymak neden önemlidir?","b":"Verilerin dürüst paylaşılması ve başkalarının emeğine saygı, bilimin güvenilirliğini korur."},{"f":"Fiziksel niceliklerin sınıflandırılmasında iki temel ayrım nedir?","b":"Temel–türetilmiş ayrımı ve skaler–vektörel ayrımıdır."}]},{"id":"fiz-2","name":"Madde ve Özellikleri","cards":[{"f":"Kütle nedir?","b":"Bir cismin sahip olduğu madde miktarının ölçüsüdür; bulunduğu yere göre değişmez."},{"f":"Hacim nedir?","b":"Bir cismin uzayda kapladığı boşluğun ölçüsüdür."},{"f":"Kütlenin yaygın birimleri nelerdir?","b":"Miligram, gram, kilogram ve tondur."},{"f":"Hacmin yaygın birimleri nelerdir?","b":"mL, L, cm³, dm³ ve m³'tür."},{"f":"Özkütle nasıl tanımlanır?","b":"Bir maddenin birim hacminin kütlesidir; d = kütle / hacim formülüyle bulunur."},{"f":"Özkütlenin birimi nedir?","b":"SI'da kg/m³'tür; günlük kullanımda sıkça g/cm³ de kullanılır."},{"f":"Saf maddelerin özkütlesi nasıl bir özelliktir?","b":"Sabit sıcaklık ve basınçta her saf madde için karakteristik (ayırt edici) bir değerdir."},{"f":"Karışımların özkütlesi neye göre değişir?","b":"Karışımı oluşturan maddelerin oranına göre değişir; karışımın karakteristik sabit bir özkütlesi yoktur."},{"f":"Archimedes özkütle alanında neyle bilinir?","b":"Bir tacın saf altından yapılıp yapılmadığını, cismi suya batırarak taşan su hacminden anlamıştır."},{"f":"el-Hazini'nin özkütle bilimine katkısı nedir?","b":"Maddelerin özkütlesini ölçmek için hassas teraziler ve yöntemler geliştiren Ortaçağ İslam bilginidir."},{"f":"Özkütleden hangi meslek alanlarında faydalanılır?","b":"Kuyumculuk, porselen yapımı ve ebru sanatı gibi alanlarda faydalanılır."},{"f":"Kuyumculukta özkütle nasıl kullanılır?","b":"Bir metalin gerçek altın olup olmadığı, özkütlesi bilinen saf altınla karşılaştırılarak anlaşılabilir."},{"f":"Dayanıklılık neyi ifade eder?","b":"Bir cismin dış etkilere (basınç, yük gibi) karşı biçimini koruyabilme direncidir."},{"f":"Dayanıklılık hangi geometrik orana bağlıdır?","b":"Cismin kesit alanının hacmine oranına bağlıdır; bu oran arttıkça dayanıklılık artar."},{"f":"Adezyon nedir?","b":"Farklı cins moleküller arasındaki çekim kuvvetidir; örneğin suyun cam yüzeye yapışması."},{"f":"Kohezyon nedir?","b":"Aynı cins moleküller arasındaki çekim kuvvetidir; örneğin su moleküllerinin birbirini çekmesi."},{"f":"Su cam üzerinde neden yayılır ama cıva yayılmaz?","b":"Suda adezyon kohezyondan büyüktür (yayılır); cıvada kohezyon adezyondan büyüktür (damlacık kalır)."},{"f":"Yüzey gerilimi nedir?","b":"Sıvı yüzeyindeki moleküllerin kohezyon kuvvetiyle bir zar gibi davranmasıdır."},{"f":"Yüzey gerilimine bir günlük hayat örneği nedir?","b":"Bazı böceklerin su üzerinde batmadan yürüyebilmesi veya bir iğnenin su yüzeyinde durabilmesi."},{"f":"Yüzey gerilimini hangi etkenler azaltır?","b":"Sıcaklığın artması ve deterjan gibi yüzey aktif maddelerin eklenmesi yüzey gerilimini azaltır."},{"f":"Kılcallık nedir?","b":"Adezyon-kohezyon dengesine bağlı olarak sıvının ince borularda yükselmesi veya alçalmasıdır."},{"f":"Kılcallığa bir doğa örneği nedir?","b":"Bitkilerde suyun kökten gövde ve yapraklara kılcal borularla taşınmasıdır."},{"f":"Kılcal boruda su yükselir, cıva neden alçalır?","b":"Suda adezyon kohezyondan büyük olduğu için yükselir; cıvada kohezyon adezyondan büyük olduğu için alçalır."}]},{"id":"fiz-3","name":"Hareket ve Kuvvet","cards":[{"f":"Öteleme hareketi nedir?","b":"Cismin her noktasının aynı anda aynı yönde, birbirine paralel yollar izlediği harekettir."},{"f":"Dönme hareketi nedir?","b":"Cismin sabit bir eksen etrafında döndüğü harekettir."},{"f":"Titreşim hareketi nedir?","b":"Bir cismin denge konumu etrafında tekrarlanan ileri geri hareketidir."},{"f":"Konum nedir?","b":"Bir cismin, seçilen bir referans noktasına göre bulunduğu yerdir."},{"f":"Alınan yol ile yer değiştirme arasındaki fark nedir?","b":"Yol, izlenen gerçek mesafenin (skaler) toplamıdır; yer değiştirme, başlangıç ve bitiş arasındaki vektörel mesafedir."},{"f":"Sürat ile hız arasındaki fark nedir?","b":"Sürat skaler bir büyüklüktür (sadece değer); hız vektöreldir (değer ve yön içerir)."},{"f":"Ortalama hız nasıl tanımlanır?","b":"Toplam yer değiştirmenin, bu yer değiştirmenin gerçekleştiği toplam zamana oranıdır."},{"f":"Anlık hız nedir?","b":"Bir cismin belirli bir andaki hızıdır."},{"f":"İvme nedir?","b":"Hızın birim zamandaki değişim miktarıdır."},{"f":"İvme ile hız aynı yönde olursa ne olur, zıt yönde olursa ne olur?","b":"Aynı yönde ise cisim hızlanır; zıt yönde ise cisim yavaşlar."},{"f":"Hareketin göreli olması ne demektir?","b":"Bir cismin hareketli mi durgun mu olduğu, seçilen referans noktasına göre değişebilir."},{"f":"Kuvvet nedir?","b":"Bir cismin hareket durumunu (hızını veya yönünü) değiştirebilen veya şeklini bozabilen etkidir."},{"f":"Temas gerektiren kuvvete örnek nedir?","b":"İtme, çekme ve sürtünme kuvveti; cisimlerin doğrudan birbirine değmesini gerektirir."},{"f":"Temas gerektirmeyen kuvvete örnek nedir?","b":"Kütle çekim kuvveti, elektriksel kuvvet ve manyetik kuvvet; cisimler değmeden etkileşir."},{"f":"Doğadaki dört temel kuvvet nedir?","b":"Kütle çekim kuvveti, elektromanyetik kuvvet, güçlü nükleer kuvvet ve zayıf nükleer kuvvettir."},{"f":"Kütle çekim kuvveti hangi değişkenlere bağlıdır?","b":"Cisimlerin kütlelerine ve aralarındaki uzaklığa bağlıdır."},{"f":"Dengelenmiş kuvvetlerin etkisindeki cisim nasıl hareket eder?","b":"Net kuvvet sıfır olduğundan cisim durgun kalır veya sabit hızla düz bir çizgide hareket etmeye devam eder."},{"f":"Dengelenmemiş (net) kuvvetin etkisindeki cisme ne olur?","b":"Cisim ivme kazanır; hızı büyüklük veya yön olarak değişir."},{"f":"Eylemsizlik ilkesi (Newton'ın 1. yasası) ne der?","b":"Bir cisme net bir kuvvet etki etmediği sürece cisim hareket durumunu (durgunluk veya sabit hız) korur."},{"f":"Newton'ın 2. yasası neyi ilişkilendirir?","b":"Bir cisme etki eden net kuvveti, cismin kütlesi ve kazandığı ivme ile ilişkilendirir."},{"f":"Etki-tepki yasası (Newton'ın 3. yasası) ne der?","b":"Bir cisim başka bir cisme kuvvet uygularsa, ikinci cisim de birincisine eşit büyüklükte zıt yönlü kuvvet uygular."},{"f":"İbn-i Sina'nın hareket konusuna katkısı nedir?","b":"Eylemsizliğe yakın fikirler öne sürerek Newton'dan önce hareketle ilgili önemli gözlemler yapmıştır."},{"f":"Sürtünme kuvveti nedir?","b":"Temas hâlindeki iki yüzeyin birbirinin hareketine karşı gösterdiği dirençtir."},{"f":"Statik sürtünme ile kinetik sürtünme arasındaki fark nedir?","b":"Statik sürtünme cisim harekete geçmeden önceki direnç, kinetik sürtünme hareket sırasındaki dirençtir; statik genelde kinetikten büyüktür."},{"f":"Sürtünme kuvvetinin bir avantajı ve bir dezavantajı nedir?","b":"Avantaj: yürüyebilme ve araç lastiklerinin yol tutması. Dezavantaj: makine parçalarının aşınması ve enerji kaybı."}]},{"id":"fiz-4","name":"Enerji","cards":[{"f":"Fizikte iş nasıl tanımlanır?","b":"Bir kuvvetin, uygulandığı cismi kendi doğrultusunda yer değiştirmesi sonucu yaptığı etkidir."},{"f":"Fiziksel iş ile günlük dildeki iş arasındaki fark nedir?","b":"Fizikte kuvvet cismi hareket ettirmezse iş sıfırdır; günlük dilde harcanan her çaba iş sayılır."},{"f":"Güç nedir?","b":"Birim zamanda yapılan işin miktarıdır."},{"f":"İş ile enerji arasındaki ilişki nedir?","b":"İş yapmak, bir cisme veya sistemden enerji aktarmak ya da almak anlamına gelir."},{"f":"Kinetik enerji nedir?","b":"Hareket eden bir cismin sahip olduğu enerjidir; kütle ve hıza bağlıdır."},{"f":"Yer çekimi potansiyel enerjisi nedir?","b":"Bir cismin bulunduğu konum (yükseklik) nedeniyle sahip olduğu enerjidir."},{"f":"Esneklik potansiyel enerjisi nedir?","b":"Bir yayın veya esnek cismin sıkışması ya da gerilmesi sonucu depoladığı enerjidir."},{"f":"Mekanik enerji nedir?","b":"Bir sistemin kinetik enerjisi ile potansiyel enerjisinin (yer çekimi + esneklik) toplamıdır."},{"f":"Enerjinin korunumu ilkesi ne der?","b":"Enerji yoktan var edilemez, var olan enerji yok edilemez; sadece bir biçimden diğerine dönüşür."},{"f":"Sürtünme enerji korunumunu nasıl etkiler?","b":"Sürtünme nedeniyle enerjinin bir kısmı ısıya dönüşür; enerji kaybolmaz, sadece istenmeyen biçime dönüşür."},{"f":"Bir enerji dönüşümüne örnek veriniz.","b":"Elektrik enerjisinin bir ampulde ışık ve ısı enerjisine dönüşmesi."},{"f":"Canlılar fiziksel iş yapmadan enerji harcayabilir mi?","b":"Evet; örneğin ağır bir cismi sabit tutarken kas gerginliği nedeniyle enerji harcanır ama fiziksel iş sıfırdır."},{"f":"Verim nedir?","b":"Bir sisteme verilen enerjinin, yararlı işe dönüşen kısmının oranıdır."},{"f":"Verim neden hiçbir zaman %100 olamaz?","b":"Enerjinin bir kısmı her zaman sürtünme veya ısı gibi istenmeyen biçimlere kaçınılmaz olarak dönüşür."},{"f":"Enerji kimlik belgesi neyi gösterir?","b":"Bir binanın veya sistemin enerji tasarrufu ve verimlilik düzeyini gösteren belgedir."},{"f":"Yenilenebilir enerji kaynağına örnek veriniz.","b":"Güneş enerjisi, rüzgâr enerjisi, hidroelektrik ve jeotermal enerji."},{"f":"Yenilenemez enerji kaynağına örnek veriniz.","b":"Kömür, petrol, doğal gaz ve nükleer yakıt (uranyum)."},{"f":"Nükleer enerji neden yenilenemez kaynak sayılır?","b":"Kullanılan uranyum gibi yakıtlar sınırlıdır ve insan ömrü ölçeğinde yenilenmez."},{"f":"Enerji kaynağı seçiminde hangi kriterler göz önünde bulundurulur?","b":"Maliyet, erişilebilirlik, üretim kolaylığı, toplumsal, teknolojik ve çevresel etkiler."},{"f":"Enerji tasarrufu neden önemlidir?","b":"Sınırlı kaynakların daha uzun süre kullanılabilmesini ve çevresel etkilerin azalmasını sağlar."},{"f":"Mekanik iş hesaplanırken hangi kuvvet bileşeni dikkate alınır?","b":"Yalnızca hareketle aynı doğrultuda olan kuvvet bileşeni dikkate alınır."},{"f":"Yer çekimi potansiyel enerjisi hangi değişkenlere bağlıdır?","b":"Cismin kütlesine, bulunduğu yüksekliğe ve yer çekimi ivmesine bağlıdır."},{"f":"Esneklik potansiyel enerjisi hangi değişkenlere bağlıdır?","b":"Yayın esneklik (yay) sabitine ve yayın sıkışma/gerilme miktarına bağlıdır."},{"f":"Fiziksel güç ile günlük dildeki güç kavramı aynı mıdır?","b":"Hayır; fizikte güç birim zamanda yapılan iştir, günlük dilde güç genellikle kuvvet veya kudret anlamında kullanılır."}]},{"id":"fiz-5","name":"Isı ve Sıcaklık","cards":[{"f":"Isı nedir?","b":"Sıcaklık farkı nedeniyle bir maddeden diğerine aktarılan enerjidir."},{"f":"Sıcaklık nedir?","b":"Bir maddenin taneciklerinin ortalama kinetik enerjisinin göstergesidir."},{"f":"Isı ile sıcaklık birbirinden nasıl ayrılır?","b":"Isı transfer edilen enerji miktarıdır (joule); sıcaklık bir durumun ölçüsüdür (derece, kelvin)."},{"f":"İç enerji nedir?","b":"Bir maddeyi oluşturan taneciklerin toplam kinetik ve potansiyel enerjisidir."},{"f":"Sıcaklık birimleri nelerdir?","b":"Celsius (°C), Fahrenheit (°F) ve Kelvin (K)."},{"f":"Termometre çeşitlerine örnek veriniz.","b":"Cıvalı/alkollü termometre, dijital termometre, kızılötesi (temassız) termometre, bimetal termometre."},{"f":"Öz ısı (özgül ısı) nedir?","b":"Bir maddenin 1 gramının sıcaklığını 1°C artırmak için gereken ısı miktarıdır."},{"f":"Isı sığası nedir?","b":"Bir cismin tamamının sıcaklığını 1°C artırmak için gereken ısı miktarıdır; kütleye bağlıdır."},{"f":"Öz ısı ile ısı sığası arasındaki fark nedir?","b":"Öz ısı maddenin cinsine özgü sabit bir değerdir; ısı sığası cismin kütlesine bağlı olarak değişir."},{"f":"Denizler karalardan neden geç ısınıp geç soğur?","b":"Suyun öz ısısı topraktan çok yüksek olduğu için aynı ısıyı alıp verirken sıcaklığı daha yavaş değişir."},{"f":"Hâl değişimi nedir?","b":"Bir maddenin katı, sıvı, gaz hâlleri arasında dönüşüm geçirmesidir."},{"f":"Hâl değişimi sırasında sıcaklık ne olur?","b":"Madde ısı alıp verse de hâl değişimi tamamlanana kadar sıcaklık sabit kalır."},{"f":"Isıl denge nedir?","b":"Farklı sıcaklıktaki iki cismin temas ettiğinde ısı alışverişi sonucu aynı sıcaklığa ulaşması durumudur."},{"f":"Isının üç iletim yolu nedir?","b":"İletim (kondüksiyon), taşınım (konveksiyon) ve ışınım (radyasyon)."},{"f":"Isı iletimi (kondüksiyon) nedir?","b":"Isının madde içinde tanecikten taneciğe, doğrudan temasla aktarılmasıdır."},{"f":"Isı taşınımı (konveksiyon) nedir?","b":"Sıvı veya gazlarda ısınan bölgenin yükselip soğuk bölgenin yer değiştirmesiyle ısının taşınmasıdır."},{"f":"Isı ışınımı (radyasyon) nedir ve neden özeldir?","b":"Elektromanyetik dalgalarla ısı aktarımıdır; boşlukta da gerçekleşebilen tek ısı iletim yoludur."},{"f":"Soğuk bölgelerde duvarların kalın, pencerelerin küçük yapılmasının nedeni nedir?","b":"İletim yoluyla ısı kaybını azaltarak enerji tasarrufu sağlamaktır."},{"f":"Hissedilen sıcaklık ile gerçek sıcaklık neden farklı olabilir?","b":"Nem ve rüzgâr gibi etkenler vücuttan ısı kaybı hızını değiştirerek algılanan sıcaklığı etkiler."},{"f":"Küresel ısınmanın temel nedeni nedir?","b":"Sera gazı salımlarının artmasıyla atmosferin daha fazla ısı tutmasıdır."},{"f":"Genleşme nedir?","b":"Bir maddenin ısınınca hacminin artmasıdır; büzülme ise soğuyunca hacminin azalmasıdır."},{"f":"Su donunca hacmi nasıl değişir?","b":"Çoğu maddenin aksine su donunca genleşir, hacmi artar ve özkütlesi azalır."},{"f":"Buz suda neden yüzer?","b":"Donan suyun özkütlesi sıvı sudan daha küçük olduğu için buz suyun üzerinde yüzer."},{"f":"Isı yalıtımının aile bütçesine katkısı nedir?","b":"Isı kaybını azaltarak ısınma/soğutma masraflarını düşürür ve enerji tasarrufu sağlar."}]},{"id":"fiz-6","name":"Elektrostatik","cards":[{"f":"Elektrik yükü nedir?","b":"Maddenin, elektriksel kuvvet uygulama ve elektriksel kuvvetten etkilenme özelliğidir."},{"f":"Elektrikle yüklenmenin üç yolu nedir?","b":"Sürtünme ile yüklenme, dokunma ile yüklenme ve etki (indüksiyon) ile yüklenme."},{"f":"Sürtünme ile yüklenme nasıl gerçekleşir?","b":"İki farklı cismin birbirine sürtülmesiyle elektronların bir cisimden diğerine geçmesiyle oluşur."},{"f":"Dokunma ile yüklenme nasıl gerçekleşir?","b":"Yüklü bir cismin nötr bir cisme doğrudan temas etmesiyle yükün bir kısmının aktarılmasıyla oluşur."},{"f":"Etki (indüksiyon) ile yüklenme nasıl gerçekleşir?","b":"Yüklü bir cisim, nötr bir cisme dokunmadan yaklaşarak onun üzerinde yük dağılımı oluşturur."},{"f":"Yük korunumu ilkesi ne der?","b":"Yüklenme sırasında yük yoktan var edilmez veya yok edilmez; sadece bir cisimden diğerine aktarılır."},{"f":"Elektrikle yüklenmede hangi tanecikler hareket eder?","b":"Genellikle elektronlar hareket eder; protonlar atom çekirdeğinde sabit kalır."},{"f":"Elektroskop ne işe yarar?","b":"Bir cismin yüklü olup olmadığını ve yük cinsini belirlemeye yarayan alettir."},{"f":"İletken madde nedir?","b":"İçindeki yüklerin (elektronların) serbestçe hareket edebildiği maddedir."},{"f":"Yalıtkan madde nedir?","b":"İçindeki yüklerin serbestçe hareket edemediği maddedir."},{"f":"İletken bir cisimde verilen yük nasıl dağılır?","b":"Yükler birbirini iterek cismin dış yüzeyine yayılır."},{"f":"Yalıtkan bir cisimde verilen yük nasıl dağılır?","b":"Yükler hareket edemediği için verildiği bölgede sabit kalır."},{"f":"Faraday kafesi ne işe yarar?","b":"İçindeki alanı dış elektrik alanlardan korur; hassas cihazları ekranlamada ve yıldırımdan korunmada kullanılır."},{"f":"Topraklama nedir ve neden önemlidir?","b":"Fazla elektrik yükünün toprağa aktarılmasıdır; elektrik çarpması ve yangın riskini azaltır."},{"f":"Coulomb Kuvveti neye bağlıdır?","b":"İki yükün büyüklüklerinin çarpımına ve aralarındaki uzaklığa bağlıdır."},{"f":"Coulomb Kuvveti uzaklıkla nasıl değişir?","b":"Uzaklığın karesiyle ters orantılı olarak azalır; uzaklık iki katına çıkarsa kuvvet dörtte birine iner."},{"f":"Elektrik alan nedir?","b":"Yüklü bir cismin çevresinde başka bir yüke kuvvet uygulayabildiği bölgedir."},{"f":"Elektrik alanın yönü nasıl belirlenir?","b":"Bölgeye konan pozitif bir test yükünün hareket edeceği yön ile belirlenir."},{"f":"Aynı cins yükler birbirine nasıl etki eder?","b":"Birbirini iter."},{"f":"Farklı cins yükler birbirine nasıl etki eder?","b":"Birbirini çeker."},{"f":"Nötr bir cisim ne demektir?","b":"Eşit sayıda pozitif ve negatif yük içeren, net yükü sıfır olan cisimdir."},{"f":"Şimşek olayı elektrostatikle nasıl açıklanır?","b":"Bulutlarda biriken elektrik yükünün, yer ile bulut arasında ani boşalmasıyla oluşur."}]},{"id":"fiz-7","name":"Elektrik ve Manyetizma","cards":[{"f":"Elektrik akımı nedir?","b":"Yüklerin (iletkenlerde serbest elektronların) bir iletken boyunca düzenli hareketidir."},{"f":"Elektrik akımının birimi nedir?","b":"Amperdir (A)."},{"f":"Potansiyel fark (gerilim) nedir?","b":"İki nokta arasında birim yükü taşımak için gereken enerjidir; birimi volttur (V)."},{"f":"Direnç nedir?","b":"Bir iletkenin, üzerinden geçen elektrik akımına gösterdiği zorluktur; birimi ohm'dur (Ω)."},{"f":"Katı, sıvı, gaz ve plazmada elektrik iletimi mümkün müdür?","b":"Evet. Katılarda serbest elektronlar, sıvılarda (çözeltilerde) iyonlar, gazlarda ve plazmada iyonlar ile elektronlar yük taşır."},{"f":"Bir iletkenin direnci hangi değişkenlere bağlıdır?","b":"İletkenin uzunluğuna, kesit alanına ve yapıldığı maddenin cinsine bağlıdır."},{"f":"Ohm Yasası neyi ilişkilendirir?","b":"Bir devredeki elektrik akımı, direnç ve potansiyel fark arasındaki ilişkiyi ifade eder."},{"f":"Ampermetre devreye nasıl bağlanır?","b":"Devreye seri bağlanır ve direnci çok küçük olmalıdır ki devreyi etkilemesin."},{"f":"Voltmetre devreye nasıl bağlanır?","b":"Ölçüm yapılacak elemana paralel bağlanır ve direnci çok büyük olmalıdır."},{"f":"Üreteçlerin seri bağlanmasının amacı nedir?","b":"Devredeki toplam gerilimi (elektromotor kuvveti) artırmaktır."},{"f":"Üreteçlerin paralel bağlanmasının amacı nedir?","b":"Üreteçlerin daha uzun süre dayanmasını (tükenme süresini uzatmayı) sağlamaktır."},{"f":"İç direnç nedir?","b":"Bir üretecin kendi iç yapısından kaynaklanan ve akıma karşı gösterdiği dirençtir."},{"f":"Galvani ve Volta arasındaki görüş ayrılığı neydi?","b":"Galvani elektriğin canlı dokudan geldiğini savundu; Volta farklı metallerin temasından kaynaklandığını gösterip ilk pili yaptı."},{"f":"Elektriksel güç nedir?","b":"Bir devre elemanının birim zamanda harcadığı veya ürettiği elektrik enerjisi miktarıdır."},{"f":"Bir lambanın parlaklığı neye bağlıdır?","b":"Lambanın harcadığı elektriksel güce bağlıdır; güç arttıkça parlaklık artar."},{"f":"Elektrik çarpmasına karşı hangi güvenlik önlemleri alınır?","b":"Islak elle prize dokunmamak, topraklama ve sigorta kullanmak, hasarlı kabloları kullanmamak."},{"f":"Mıknatısların aynı kutupları ve farklı kutupları nasıl etkileşir?","b":"Aynı kutuplar (K-K veya G-G) birbirini iter; farklı kutuplar (K-G) birbirini çeker."},{"f":"Manyetik alan çizgileri neyi gösterir?","b":"Mıknatısın çevresindeki manyetik alanın yönünü ve şiddetini gösterir; kuzeyden çıkıp güneye girer."},{"f":"Sağ el kuralı ne işe yarar?","b":"Akım taşıyan bir telin çevresinde oluşan manyetik alanın yönünü bulmaya yarar."},{"f":"Elektromıknatıs nedir?","b":"Üzerinden akım geçen bir tel sarımının oluşturduğu, akım kesilince manyetik özelliğini kaybeden mıknatıstır."},{"f":"Dünya'nın manyetik alanı pusulayı nasıl etkiler?","b":"Pusula iğnesi, Dünya'nın manyetik alanına göre yönelerek kuzey-güney yönünü gösterir."},{"f":"Hangi canlılar Dünya'nın manyetik alanından yön bulmak için yararlanır?","b":"Arılar, göçmen kuşlar ve bazı büyükbaş hayvanlar."}]},{"id":"fiz-8","name":"Basınç ve Kaldırma Kuvveti","cards":[{"f":"Basınç nedir?","b":"Birim yüzey alanına etki eden dik kuvvettir."},{"f":"Basıncın birimi nedir?","b":"Pascal'dır (Pa)."},{"f":"Katı basıncı hangi değişkenlere bağlıdır?","b":"Uygulanan kuvvete ve temas yüzey alanına bağlıdır."},{"f":"Basınç kaynama sıcaklığını nasıl etkiler?","b":"Basınç arttıkça kaynama sıcaklığı yükselir (düdüklü tencere); basınç azalınca düşer."},{"f":"Torricelli deneyi neyi gösterir?","b":"Cıva sütunu yardımıyla atmosfer basıncının varlığını ve büyüklüğünü gösteren deneydir."},{"f":"Torricelli deneyi kılcallıktan nasıl ayrılır?","b":"Torricelli atmosfer basıncını ölçer; kılcallık ise adezyon-kohezyon dengesiyle ilgili ayrı bir olaydır."},{"f":"Barometre ne ölçer?","b":"Atmosfer (hava) basıncını ölçer."},{"f":"Altimetre ne işe yarar?","b":"Hava basıncından yararlanarak bulunulan yüksekliği belirler."},{"f":"Manometre ne ölçer?","b":"Kapalı bir kaptaki gazın basıncını ölçer."},{"f":"Batimetre ne ölçer?","b":"Su derinliğini ölçer."},{"f":"Pascal Prensibi ne der?","b":"Kapalı bir kaptaki durgun sıvıya uygulanan basınç, sıvının her noktasına eşit olarak iletilir."},{"f":"Pascal Prensibi hangi araçlarda uygulanır?","b":"Hidrolik fren ve hidrolik kriko gibi sistemlerde uygulanır."},{"f":"Bernoulli İlkesi ne der?","b":"Bir akışkanın hızı arttıkça, o bölgedeki basıncı azalır."},{"f":"Bernoulli İlkesi'ne bir örnek veriniz.","b":"Rüzgârlı havada evlerin çatısının uçması; çatı üstündeki hızlı hava akımı basıncı düşürür."},{"f":"Uçaklar Bernoulli İlkesi'yle nasıl uçar?","b":"Kanat üstündeki hava alttakinden hızlı aktığı için üstte basınç düşer ve kaldırma kuvveti oluşur."},{"f":"Tansiyon neyi ölçer?","b":"Kan damarlarındaki kan basıncını ölçer."},{"f":"Akışkan basıncına karşı alınması gereken bir güvenlik önlemi nedir?","b":"Yüksek süratle hareket eden araçlara yakın durmamak; oluşan basınç farkı çekme etkisi yaratabilir."},{"f":"Archimedes İlkesi ne der?","b":"Bir akışkana batırılan cisme, cismin taşırdığı akışkanın ağırlığı kadar yukarı yönlü kaldırma kuvveti etki eder."},{"f":"Kaldırma kuvveti neye bağlıdır?","b":"Cismin taşırdığı akışkanın ağırlığına, dolayısıyla akışkanın özkütlesine ve taşırılan hacme bağlıdır."},{"f":"Bir cisim ne zaman yüzer?","b":"Özkütlesi sıvının özkütlesinden küçükse yüzer; yüzerken kaldırma kuvveti ağırlığına eşittir."},{"f":"Bir cisim ne zaman batar?","b":"Özkütlesi sıvının özkütlesinden büyükse batar; kaldırma kuvveti ağırlığından küçük kalır."},{"f":"Bir cisim ne zaman askıda kalır?","b":"Özkütlesi sıvının özkütlesine eşitse tamamen batmış hâlde dengede (askıda) kalır; kaldırma kuvveti ağırlığa eşittir."},{"f":"Basıncın günlük hayattaki bir etkisi nedir?","b":"Yüksek rakımda hava basıncının düşmesi nedeniyle suyun kaynama sıcaklığı düşer."}]},{"id":"fiz-9","name":"Dalgalar","cards":[{"f":"Dalga nedir?","b":"Bir titreşimin, madde taşınmadan ortam içinde enerji taşıyarak ilerlemesidir."},{"f":"Titreşim nedir?","b":"Bir cismin denge konumu etrafında tekrarlanan hareketidir."},{"f":"Dalga boyu nedir?","b":"Bir dalganın birbirini izleyen iki benzer noktası (örneğin iki tepe) arasındaki uzaklıktır."},{"f":"Periyot nedir?","b":"Bir tam titreşimin tamamlanması için geçen süredir."},{"f":"Frekans nedir?","b":"Birim zamandaki titreşim sayısıdır."},{"f":"Periyot ile frekans arasındaki ilişki nedir?","b":"Birbirinin çarpmaya göre tersidir; biri artarken diğeri azalır."},{"f":"Genlik nedir?","b":"Titreşen bir noktanın denge konumundan yaptığı en büyük uzaklaşma miktarıdır."},{"f":"Dalganın ilerleme hızı neye bağlıdır?","b":"İçinde ilerlediği ortamın özelliklerine bağlıdır; frekansa bağlı değildir."},{"f":"Dalganın frekansı neye bağlıdır?","b":"Dalgayı üreten kaynağa bağlıdır; ortam değişse de frekans değişmez."},{"f":"Dalgalar madde taşır mı?","b":"Hayır, dalgalar madde taşımaz; yalnızca enerji taşır."},{"f":"Dalgalar ortam ihtiyacına göre nasıl sınıflandırılır?","b":"Mekanik dalgalar (yayılmak için ortama ihtiyaç duyar) ve elektromanyetik dalgalar (boşlukta da yayılabilir) olarak sınıflandırılır."},{"f":"Enine dalga ile boyuna dalga arasındaki fark nedir?","b":"Enine dalgada titreşim yönü ilerleme yönüne diktir (ip, su yüzeyi); boyuna dalgada titreşim ilerleme yönüyle aynı doğrultudadır (ses, yay)."},{"f":"Atma nedir?","b":"Bir ortamda tek seferlik oluşturulan, tekrarlanmayan dalga bozulmasıdır."},{"f":"Periyodik dalga nedir?","b":"Kaynağın sürekli ve düzenli titreşimiyle oluşan, tekrarlanan dalgadır."},{"f":"Bir atma sabit uçtan yansırken nasıl davranır?","b":"Ters dönerek (fazı 180° kayarak) yansır."},{"f":"Bir atma serbest uçtan yansırken nasıl davranır?","b":"Aynı yönde (fazı korunarak) yansır."},{"f":"Dalga tepesi ve dalga çukuru nedir?","b":"Dalga tepesi en yüksek nokta, dalga çukuru en alçak noktadır."},{"f":"Su dalgaları hangi biçimlerde incelenir?","b":"Doğrusal su dalgaları ve dairesel su dalgaları olarak incelenir."},{"f":"Stroboskop ne işe yarar?","b":"Hareketi durmuş gibi göstererek su dalgalarının dalga boyunu ölçmede kullanılan bir araçtır."},{"f":"Ses yüksekliği ile ses şiddeti arasındaki fark nedir?","b":"Yükseklik frekansla, şiddet ise dalganın taşıdığı enerji (genlik) ile ilgilidir."},{"f":"Tını nedir?","b":"Aynı notayı çalan farklı enstrümanları birbirinden ayıran ses özelliğidir."},{"f":"Rezonans nedir?","b":"Bir sistemin kendi doğal frekansına eşit bir dış uyaranla titreştirildiğinde genliğinin aşırı artmasıdır."},{"f":"Yankı nasıl oluşur?","b":"Sesin bir yüzeyden yansıyıp, kulağın ayırt edebileceği bir gecikmeyle tekrar duyulmasıyla oluşur."},{"f":"Farabi'nin ses bilimine katkısı nedir?","b":"Ses dalgalarının yayılması ve müzik teorisi üzerine önemli çalışmalar yapmıştır."},{"f":"Deprem büyüklüğü ile şiddeti arasındaki fark nedir?","b":"Büyüklük depremin kaynağındaki enerjiyi tek bir sayıyla ifade eder; şiddet bölgeye göre değişen hasar etkisidir."},{"f":"Ses dalgaları hangi alanlarda kullanılır?","b":"Tıp (ultrason), denizcilik (sonar), sanat (müzik) ve coğrafya (yer araştırmaları) alanlarında kullanılır."}]},{"id":"fiz-10","name":"Optik","cards":[{"f":"Aydınlanma şiddeti nedir?","b":"Bir yüzeyin birim alanına düşen ışık miktarının göstergesidir."},{"f":"Işık şiddeti ve ışık akısı ile aydınlanma şiddeti arasında nasıl bir ilişki vardır?","b":"Kaynağın ışık şiddeti ve yaydığı ışık akısı arttıkça, aydınlatılan yüzeydeki aydınlanma şiddeti de artar."},{"f":"Gölge nedir?","b":"Işık kaynağının ışınlarının hiç ulaşamadığı, tam karanlık bölgedir."},{"f":"Yarı gölge nedir?","b":"Işık kaynağının ışınlarının bir kısmının ulaştığı, kısmen aydınlık bölgedir."},{"f":"Saydam madde nedir?","b":"Işığı büyük ölçüde geçiren, arkasındaki cisimlerin net görülmesini sağlayan maddedir."},{"f":"Yarı saydam madde nedir?","b":"Işığın bir kısmını geçiren, arkasındaki cisimlerin bulanık görülmesine yol açan maddedir."},{"f":"Saydam olmayan (opak) madde nedir?","b":"Işığı hiç geçirmeyen maddedir."},{"f":"Yansıma kanunları nedir?","b":"Gelme açısı yansıma açısına eşittir; gelen ışın, yansıyan ışın ve normal aynı düzlemdedir."},{"f":"Düzgün yansıma nedir?","b":"Pürüzsüz yüzeylerde paralel gelen ışınların paralel olarak yansımasıdır."},{"f":"Dağınık yansıma nedir?","b":"Pürüzlü yüzeylerde ışınların farklı yönlere dağılarak yansımasıdır."},{"f":"Düzlem aynada oluşan görüntünün özellikleri nelerdir?","b":"Cisimle aynı büyüklükte, sanaldır (perdeye düşürülemez) ve sağ-sol simetriktir."},{"f":"Çukur ayna günlük hayatta nerede kullanılır?","b":"Makyaj/tıraş aynasında ve araç farlarının reflektöründe kullanılır."},{"f":"Tümsek ayna günlük hayatta nerede kullanılır?","b":"Araç dikiz aynasında ve market güvenlik aynasında; geniş görüş açısı sağlar."},{"f":"Küresel aynada odak noktası nedir?","b":"Aynaya paralel gelen ışınların yansıdıktan sonra kesiştiği (veya kesişiyormuş gibi göründüğü) noktadır."},{"f":"Kırılma nedir?","b":"Işığın kırılma indisi farklı iki saydam ortam arasında geçerken doğrultusunun değişmesidir."},{"f":"Kırılma indisi nedir?","b":"Işığın boşluktaki hızının, ortamdaki hızına oranıdır; ortamın ışığı ne kadar yavaşlattığını gösterir."},{"f":"Kırılma indisi büyük olan bir ortamda ışık nasıl davranır?","b":"Işık bu ortamda daha yavaş ilerler."},{"f":"Tam yansıma hangi koşulda gerçekleşir?","b":"Işık, kırılma indisi büyük bir ortamdan küçük bir ortama, sınır açısından büyük açıyla geldiğinde tüm ışık yansır."},{"f":"Sınır açısı nedir?","b":"Kırılan ışının 90° açıyla yüzeye paralel çıktığı, tam yansımanın başladığı gelme açısıdır."},{"f":"Fiber optik teknolojisi hangi ilkeyle çalışır?","b":"Tam yansıma ilkesiyle çalışır; ışık kabloda sürekli yansıyarak ilerler."},{"f":"Serap olayı nasıl açıklanır?","b":"Sıcak havanın farklı yoğunluk katmanları oluşturmasıyla ışığın tam yansımaya uğramasıyla oluşan görsel yanılsamadır."},{"f":"Görünür uzaklık nedir?","b":"Farklı bir ortamda bulunan bir cismin, kırılma nedeniyle gerçek konumundan farklı bir yerde görünmesidir."},{"f":"İnce kenarlı (yakınsak) mercek nedir?","b":"Kendisine paralel gelen ışınları bir noktada toplayan, ortası kenarlarından kalın mercektir."},{"f":"Kalın kenarlı (ıraksak) mercek nedir?","b":"Kendisine paralel gelen ışınları birbirinden uzaklaştıran, ortası kenarlarından ince mercektir."},{"f":"Işık prizması ne işe yarar?","b":"Beyaz ışığı, renklerin farklı kırılma indisine sahip olması nedeniyle bileşen renklerine ayırır."},{"f":"Işıkta ana renkler ile boyada ana renkler nasıl farklıdır?","b":"Işıkta ana renkler kırmızı, yeşil, mavidir; boyada ana renkler camgöbeği, magenta, sarıdır."},{"f":"Bir cisim neden belirli bir renkte görünür?","b":"Üzerine düşen ışıktan o renk dışındaki renkleri soğurur, yalnızca kendi rengini yansıtır."},{"f":"Saf sarı ışık ile karışım sarı arasındaki fark nedir?","b":"Saf sarı tek dalga boyundan oluşurken, karışım sarı kırmızı ve yeşil ışığın birleşiminden oluşur; göze aynı görünür."}]}]},{"subject":"Kimya","units":[{"id":"kim-1","name":"Kimya Bilimi","cards":[{"f":"Simya ile kimya bilimi arasındaki temel fark nedir?","b":"Simya mistik inanışlara dayanır ve altın elde etmeyi amaçlar; kimya bilimsel yönteme dayanan sistematik bir bilim dalıdır."},{"f":"Kimyanın bilim olma sürecine katkı sağlayan bilim insanlarından ikisini say.","b":"Örnekler: Empedokles, Demokritos, Aristo, Câbir bin Hayyan, Ebubekir er-Râzî, Robert Boyle, Antoine Lavoisier."},{"f":"Câbir bin Hayyan hangi uygarlığın kimya bilimine katkı sağlayan bilim insanıdır?","b":"İslam uygarlığı; simyadan kimyaya geçiş sürecine katkı sağlamıştır."},{"f":"Ebubekir er-Razi kimya tarihinde neyle anılır?","b":"Simyadan kimyaya geçiş sürecine katkı sağlayan İslam alimlerinden biridir."},{"f":"Biyokimya neyi inceler?","b":"Canlı organizmalardaki kimyasal olayları ve yapıları inceleyen kimya dalı."},{"f":"Analitik kimya neyi inceler?","b":"Maddelerin bileşimini ve içerdiği maddelerin miktarını belirlemeyi inceleyen kimya dalı."},{"f":"Organik kimya neyi inceler?","b":"Karbon içeren bileşikleri inceleyen kimya dalı."},{"f":"Anorganik kimya neyi inceler?","b":"Karbon içermeyen (genelde metal/mineral kökenli) bileşikleri inceleyen kimya dalı."},{"f":"Polimer kimyası neyi inceler?","b":"Küçük birimlerin (monomer) tekrarıyla oluşan büyük moleküllü maddeleri (polimerleri) inceleyen kimya dalı."},{"f":"Element nedir?","b":"Aynı cins atomlardan oluşan, kimyasal yolla daha basit maddelere ayrıştırılamayan saf madde."},{"f":"Bileşik nedir?","b":"Farklı elementlerin belirli oranlarda kimyasal yollarla birleşmesiyle oluşan, kendine özgü özellikleri olan saf madde."},{"f":"H₂O bileşiğinin yaygın adı nedir?","b":"Su."},{"f":"NaCl bileşiğinin yaygın adı nedir?","b":"Sofra tuzu (sodyum klorür)."},{"f":"NaHCO₃ bileşiğinin yaygın adı nedir?","b":"Kabartma tozu / karbonat (sodyum bikarbonat)."},{"f":"CH₃COOH bileşiğinin yaygın adı nedir?","b":"Asetik asit; sulu çözeltisi sirke olarak bilinir."},{"f":"Ca(OH)₂ bileşiğinin yaygın adı nedir?","b":"Sönmüş kireç (kalsiyum hidroksit)."},{"f":"NaOH bileşiğinin yaygın adı nedir?","b":"Kostik (sodyum hidroksit)."},{"f":"CaO bileşiğinin yaygın adı nedir?","b":"Sönmemiş kireç (kalsiyum oksit)."},{"f":"H₂SO₄ bileşiğinin yaygın adı nedir?","b":"Zaç yağı (sülfürik asit)."},{"f":"HNO₃ bileşiğinin yaygın adı nedir?","b":"Kezzap (nitrik asit)."},{"f":"Yanıcı madde uyarı işareti neyi gösterir?","b":"Kolayca alev alabilen maddeleri; ateş ve kıvılcımdan uzak tutulmalıdır."},{"f":"Yakıcı (oksitleyici) madde uyarı işareti neyi gösterir?","b":"Yanmayı başlatan ya da şiddetlendiren (oksijen veren) maddeleri; yanıcı maddelerden uzak tutulmalıdır."},{"f":"Korozif (aşındırıcı) madde uyarı işareti neyi gösterir?","b":"Metalleri ve canlı dokuları aşındırabilen maddeleri; eldiven ve gözlük gerektirir."},{"f":"Patlayıcı madde uyarı işareti neyi gösterir?","b":"Ani ve şiddetli tepkimeyle patlayabilen maddeleri."},{"f":"Tahriş edici madde uyarı işareti neyi gösterir?","b":"Deri, göz veya solunum yollarında geçici rahatsızlık/kızarıklık yapabilen maddeleri."},{"f":"Zehirli (toksik) madde uyarı işareti neyi gösterir?","b":"Solunduğunda, yutulduğunda veya cilde temas ettiğinde sağlığa ciddi zarar veren maddeleri."},{"f":"Radyoaktif madde uyarı işareti neyi gösterir?","b":"İyonlaştırıcı radyasyon yayan, canlılara zarar verebilen maddeleri."},{"f":"Çevreye zararlı madde uyarı işareti neyi gösterir?","b":"Doğaya, su kaynaklarına ve canlılara zarar verebilecek maddeleri."},{"f":"Beherglas hangi amaçla kullanılır?","b":"Sıvıları karıştırmak, ısıtmak veya yaklaşık hacim ölçmek için kullanılan geniş ağızlı laboratuvar kabı."},{"f":"Balon joje ne için kullanılır?","b":"Belirli hacimde çözeltiyi hassas biçimde hazırlamak için kullanılan, tek çizgili ölçekli cam kap."},{"f":"Ayırma hunisi laboratuvarda ne için kullanılır?","b":"Birbiri içinde çözünmeyen sıvıları yoğunluk farkından yararlanarak ayırmak için kullanılır."},{"f":"Na, K, Ca, Mg, H₂O maddeleri insan sağlığı için neden önemlidir?","b":"Vücut fonksiyonları için gerekli temel element ve bileşiklerdir (elektrolit dengesi, kemik yapısı vb.)."},{"f":"Hg ve Pb gibi ağır metaller insan sağlığı açısından nasıl bir risk taşır?","b":"Vücutta birikerek sinir sistemi ve organlara zarar verebilen zehirli ağır metallerdir."}]},{"id":"kim-2","name":"Atom ve Periyodik Sistem","cards":[{"f":"Dalton atom modelinin özelliği nedir?","b":"Atomun bölünemez, içi dolu ve sert bir küre olduğunu öne sürer."},{"f":"Thomson atom modelinin özelliği nedir?","b":"Üzümlü kek modeli: pozitif yüklü küre içine gömülü elektronlar."},{"f":"Rutherford atom modelinin özelliği nedir?","b":"Atomun pozitif yükünün küçük bir çekirdekte toplandığını, çevresinde elektronların dolandığını öne sürer (gezegen modeli)."},{"f":"Bohr atom modelinin özelliği nedir?","b":"Elektronların belirli enerji seviyelerinde (katmanlarda) dolandığını; atomun ışın soğurma/yayma davranışını açıklar."},{"f":"Modern atom teorisi (bulut modeli) neyi öne sürer?","b":"Elektronların çekirdek çevresinde kesin bir yörüngede değil, bulunma olasılığı yüksek bölgelerde (elektron bulutu) bulunduğunu."},{"f":"Emisyon (yayma) nedir?","b":"Atomun yüksek enerji seviyesinden düşük seviyeye geçerken ışın (enerji) yayması."},{"f":"Absorbsiyon (soğurma) nedir?","b":"Atomun düşük enerji seviyesinden yüksek seviyeye geçerken ışın (enerji) soğurması."},{"f":"Protonun yükü ve atomdaki yeri nedir?","b":"+1 yüklü, çekirdekte bulunur."},{"f":"Nötronun yükü ve atomdaki yeri nedir?","b":"Yüksüzdür, çekirdekte bulunur."},{"f":"Elektronun yükü ve atomdaki yeri nedir?","b":"-1 yüklü, çekirdek dışında (katmanlarda) bulunur."},{"f":"Atom numarası neyi ifade eder?","b":"Bir atomun çekirdeğindeki proton sayısını."},{"f":"Kütle numarası neyi ifade eder?","b":"Bir atomun çekirdeğindeki proton ve nötron sayılarının toplamını."},{"f":"İzotop atomlar nedir?","b":"Proton sayısı aynı, nötron sayısı (dolayısıyla kütle numarası) farklı olan atomlar."},{"f":"İzoton atomlar nedir?","b":"Nötron sayısı aynı, proton sayısı farklı olan atomlar."},{"f":"İzobar atomlar nedir?","b":"Kütle numarası aynı, proton sayısı farklı olan atomlar."},{"f":"İzoelektronik tanecikler nedir?","b":"Elektron sayıları birbirine eşit olan atom veya iyonlar."},{"f":"Mendeleyev'in periyodik sisteme katkısı nedir?","b":"Elementleri artan atom kütlesine ve benzer özelliklerine göre bir tabloda düzenlemiştir."},{"f":"Moseley'in periyodik sisteme katkısı nedir?","b":"Elementleri atom numarasına (proton sayısına) göre sıralayarak periyodik sistemi geliştirmiştir."},{"f":"Periyodik sistemde elementler nasıl sınıflandırılır?","b":"Metal, ametal, yarı metal (metaloid) ve asal (soy) gazlar olarak sınıflandırılır."},{"f":"Metale örnek ver.","b":"Demir, sodyum, bakır, alüminyum."},{"f":"Ametale örnek ver.","b":"Oksijen, azot, klor, kükürt."},{"f":"Yarı metale (metaloide) örnek ver.","b":"Bor, silisyum, germanyum."},{"f":"Asal (soy) gaza örnek ver.","b":"Helyum, neon, argon."},{"f":"Aynı periyotta soldan sağa gidildikçe atom yarıçapı nasıl değişir?","b":"Azalır."},{"f":"Aynı grupta yukarıdan aşağıya gidildikçe atom yarıçapı nasıl değişir?","b":"Artar."},{"f":"İyonlaşma enerjisi nedir?","b":"Bir atomdan bir elektronu koparmak için gereken minimum enerji."},{"f":"Elektronegatiflik nedir?","b":"Bir atomun bağ elektronlarını kendine çekme gücü."},{"f":"Elektron ilgisi nedir?","b":"Bir atomun elektron alarak negatif iyon oluştururken açığa çıkan/soğurulan enerji eğilimi."},{"f":"Hidrojen elementinin simgesi nedir?","b":"H (atom numarası 1)."},{"f":"Helyum elementinin simgesi nedir?","b":"He (atom numarası 2)."},{"f":"Lityum elementinin simgesi nedir?","b":"Li (atom numarası 3)."},{"f":"Berilyum elementinin simgesi nedir?","b":"Be (atom numarası 4)."},{"f":"Bor elementinin simgesi nedir?","b":"B (atom numarası 5)."},{"f":"Karbon elementinin simgesi nedir?","b":"C (atom numarası 6)."},{"f":"Azot elementinin simgesi nedir?","b":"N (atom numarası 7). Na (sodyum) ile karıştırılmamalı."},{"f":"Oksijen elementinin simgesi nedir?","b":"O (atom numarası 8)."},{"f":"Flor elementinin simgesi nedir?","b":"F (atom numarası 9)."},{"f":"Neon elementinin simgesi nedir?","b":"Ne (atom numarası 10)."},{"f":"Sodyum elementinin simgesi nedir?","b":"Na (atom numarası 11), Latince natrium'dan gelir. N (azot) ile karıştırılmamalı."},{"f":"Magnezyum elementinin simgesi nedir?","b":"Mg (atom numarası 12)."},{"f":"Alüminyum elementinin simgesi nedir?","b":"Al (atom numarası 13)."},{"f":"Silisyum elementinin simgesi nedir?","b":"Si (atom numarası 14)."},{"f":"Fosfor elementinin simgesi nedir?","b":"P (atom numarası 15)."},{"f":"Kükürt elementinin simgesi nedir?","b":"S (atom numarası 16), Latince sulfur'dan gelir."},{"f":"Klor elementinin simgesi nedir?","b":"Cl (atom numarası 17)."},{"f":"Argon elementinin simgesi nedir?","b":"Ar (atom numarası 18)."},{"f":"Potasyum elementinin simgesi nedir?","b":"K (atom numarası 19), Latince kalium'dan gelir. Ca (kalsiyum) ile karıştırılmamalı."},{"f":"Kalsiyum elementinin simgesi nedir?","b":"Ca (atom numarası 20). K (potasyum) ile karıştırılmamalı."},{"f":"Krom elementinin simgesi nedir?","b":"Cr."},{"f":"Mangan elementinin simgesi nedir?","b":"Mn."},{"f":"Demir elementinin simgesi nedir?","b":"Fe, Latince ferrum'dan gelir."},{"f":"Kobalt elementinin simgesi nedir?","b":"Co."},{"f":"Nikel elementinin simgesi nedir?","b":"Ni."},{"f":"Bakır elementinin simgesi nedir?","b":"Cu, Latince cuprum'dan gelir. Ca (kalsiyum) ile karıştırılmamalı."},{"f":"Çinko elementinin simgesi nedir?","b":"Zn."},{"f":"Brom elementinin simgesi nedir?","b":"Br."},{"f":"Gümüş elementinin simgesi nedir?","b":"Ag, Latince argentum'dan gelir. Au (altın) ile karıştırılmamalı."},{"f":"Kalay elementinin simgesi nedir?","b":"Sn, Latince stannum'dan gelir."},{"f":"İyot elementinin simgesi nedir?","b":"I."},{"f":"Baryum elementinin simgesi nedir?","b":"Ba."},{"f":"Platin elementinin simgesi nedir?","b":"Pt."},{"f":"Altın elementinin simgesi nedir?","b":"Au, Latince aurum'dan gelir. Ag (gümüş) ile karıştırılmamalı."},{"f":"Cıva elementinin simgesi nedir?","b":"Hg, Latince hydrargyrum'dan gelir."},{"f":"Kurşun elementinin simgesi nedir?","b":"Pb, Latince plumbum'dan gelir."}]},{"id":"kim-3","name":"Kimyasal Türler Arası Etkileşimler","cards":[{"f":"Kimyasal tür nedir?","b":"Atom, iyon veya molekül gibi kimyasal etkileşimlerde yer alan temel yapı taşları."},{"f":"Kimyasal türler arası etkileşimler nasıl iki ana gruba ayrılır?","b":"Güçlü etkileşimler (atomlar arası, kimyasal bağlar) ve zayıf etkileşimler (moleküller arası)."},{"f":"Güçlü etkileşimlere örnek olarak hangi bağlar verilir?","b":"İyonik bağ, kovalent bağ, metalik bağ."},{"f":"Zayıf etkileşimlere örnek olarak neler verilir?","b":"Hidrojen bağı ve van der Waals kuvvetleri."},{"f":"İyonik bağ nasıl oluşur?","b":"Metal atomunun elektron vermesi, ametal atomunun elektron almasıyla oluşan zıt yüklü iyonlar arasındaki çekimle."},{"f":"Kovalent bağ nasıl oluşur?","b":"Ametal atomlarının bir veya daha fazla ortak elektron çifti paylaşmasıyla oluşur."},{"f":"Apolar kovalent bağ ne zaman oluşur?","b":"Aynı cins atomlar veya elektronegatiflik farkı çok küçük atomlar arasında (örn. H₂, Cl₂, O₂, N₂)."},{"f":"Polar kovalent bağ ne zaman oluşur?","b":"Farklı elektronegatifliğe sahip atomlar arasında; elektronlar bir atoma daha yakın paylaşılır (örn. HCl, H₂O)."},{"f":"Metalik bağ nasıl açıklanır?","b":"Elektron denizi modeliyle: metal katyonlarının serbest dolaşan elektronlar denizi içinde bir arada tutulmasıyla."},{"f":"NH₄⁺ iyonunun adı nedir?","b":"Amonyum iyonu."},{"f":"OH⁻ iyonunun adı nedir?","b":"Hidroksit iyonu."},{"f":"NO₃⁻ iyonunun adı nedir?","b":"Nitrat iyonu."},{"f":"SO₄²⁻ iyonunun adı nedir?","b":"Sülfat iyonu."},{"f":"CO₃²⁻ iyonunun adı nedir?","b":"Karbonat iyonu."},{"f":"PO₄³⁻ iyonunun adı nedir?","b":"Fosfat iyonu."},{"f":"CN⁻ iyonunun adı nedir?","b":"Siyanür iyonu."},{"f":"CH₃COO⁻ iyonunun adı nedir?","b":"Asetat iyonu."},{"f":"Değişken değerlikli metallere hangi örnekler verilir?","b":"Bakır (Cu), demir (Fe), civa (Hg), kalay (Sn), kurşun (Pb)."},{"f":"H₂O bileşiğinin sistematik adı nedir?","b":"Dihidrojen monoksit (yaygın adı su)."},{"f":"HCl bileşiğinin sistematik adı nedir?","b":"Hidrojen klorür."},{"f":"NH₃ bileşiğinin sistematik adı nedir?","b":"Azot trihidrür (yaygın adı amonyak)."},{"f":"Zayıf ve güçlü etkileşimler hangi esasa göre ayrılır?","b":"Bağ enerjisi büyüklüğüne göre; güçlü etkileşimler çok daha yüksek bağ enerjisine sahiptir."},{"f":"Van der Waals kuvvetleri şemsiye terimi hangi etkileşimleri kapsar?","b":"Dipol-dipol, iyon-dipol, dipol-indüklenmiş dipol, iyon-indüklenmiş dipol ve London kuvvetleri."},{"f":"Van der Waals kuvvetleri arasında en zayıfı hangisidir?","b":"London (dağılma) kuvvetleri."},{"f":"İyon-dipol, dipol-dipol ve London kuvvetleri arasında en güçlüsü hangisidir?","b":"İyon-dipol etkileşimi."},{"f":"Hidrojen bağı hangi atomlar arasında oluşur?","b":"H atomu ile F, O veya N gibi küçük ve çok elektronegatif bir atom arasında."},{"f":"Hidrojen bağı ile van der Waals kuvvetlerinin ilişkisi nasıldır?","b":"Hidrojen bağı, van der Waals kuvvetlerinden (dipol-dipol, London vb.) genellikle daha güçlü, zayıf etkileşimlerin en kuvvetlisidir."},{"f":"Aziz Sancar bu ünitede hangi konudaki çalışmasıyla anılır?","b":"DNA'nın onarımıyla ilgili Nobel ödüllü çalışması; hidrojen bağı konusuyla ilişkilendirilir."},{"f":"Tuz (NaCl) katısında tanecikleri bir arada tutan etkileşim nedir?","b":"İyonik bağ."},{"f":"Elmas katısında tanecikleri bir arada tutan etkileşim nedir?","b":"Kovalent bağ (kovalent ağ katı)."},{"f":"Çinko katısında tanecikleri bir arada tutan etkileşim nedir?","b":"Metalik bağ."},{"f":"Katı iyotta tanecikleri bir arada tutan etkileşim nedir?","b":"Zayıf etkileşimler (van der Waals/London kuvvetleri); iyot moleküler bir katıdır."}]},{"id":"kim-4","name":"Maddenin Hâlleri","cards":[{"f":"Erime nedir?","b":"Katı halden sıvı hale geçiş."},{"f":"Donma nedir?","b":"Sıvı halden katı hale geçiş."},{"f":"Buharlaşma nedir?","b":"Sıvı halden gaz hale geçiş."},{"f":"Yoğuşma nedir?","b":"Gaz halden sıvı hale geçiş."},{"f":"Süblimleşme nedir?","b":"Katı halden doğrudan gaz hale geçiş."},{"f":"Kırağılaşma (geri süblimleşme) nedir?","b":"Gaz halden doğrudan katı hale geçiş."},{"f":"Plazma nedir?","b":"Çok yüksek sıcaklıkta gazın iyonlaşmasıyla oluşan, maddenin dördüncü hâli."},{"f":"Viskozite nedir?","b":"Bir sıvının akmaya karşı gösterdiği direnç."},{"f":"Sıcaklık arttıkça sıvıların viskozitesi genellikle nasıl değişir?","b":"Azalır; sıvı daha akışkan hale gelir."},{"f":"Buhar basıncı nedir?","b":"Kapalı bir kapta sıvı ile dengede bulunan buharın yaptığı basınç."},{"f":"Kaynama neye bağlıdır?","b":"Dış basınca; sıvının buhar basıncı dış basınca eşitlendiğinde kaynama başlar."},{"f":"Nem nedir?","b":"Atmosferdeki su buharının varlığını ifade eden kavram."},{"f":"Katıların bağ türü tanıtımında kullanılan dört örnek katı hangileridir?","b":"Tuz (iyonik), iyot (moleküler), elmas (kovalent ağ), çinko (metalik)."},{"f":"Katıların tanecikleri arasındaki bağ gücü hangi özellikle ilişkilendirilir?","b":"Erime noktası ve sertlik gibi fiziksel özelliklerle."},{"f":"Gaz basıncı hangi birimlerle ifade edilir?","b":"atm (atmosfer) ve mmHg (cıva milimetresi)."},{"f":"Gaz hacmi hangi birimle ifade edilir?","b":"Litre (L)."},{"f":"Gaz sıcaklığı hangi birimlerle ifade edilir?","b":"Celsius (°C) ve Kelvin (K)."},{"f":"Gaz miktarı hangi birimle ifade edilir?","b":"Mol."},{"f":"LPG nedir?","b":"Sıvılaştırılmış petrol gazı."},{"f":"LNG nedir?","b":"Sıvılaştırılmış doğal gaz."},{"f":"Mutlak sıcaklık nedir?","b":"Kelvin cinsinden ölçülen, en düşük değeri mutlak sıfır (0 K) olan sıcaklık ölçeği."},{"f":"Bağıl nem neyi ifade eder?","b":"Havadaki mevcut su buharı miktarının, o sıcaklıkta taşınabilecek maksimum miktara oranını."},{"f":"Genleşme nedir?","b":"Maddenin sıcaklık artışıyla hacminin büyümesi."},{"f":"Akışkanlık hangi madde hâllerinin ortak özelliğidir?","b":"Sıvılar ve gazlar; şekil değiştirip akabilme özelliğidir."}]},{"id":"kim-5","name":"Doğa ve Kimya","cards":[{"f":"Sert su nedir?","b":"Kalsiyum ve magnezyum iyonlarını fazla miktarda içeren su."},{"f":"Yumuşak su nedir?","b":"Kalsiyum ve magnezyum iyonları az olan, sabunla kolay köpüren su."},{"f":"Sert suyun günlük hayattaki olumsuz etkisi nedir?","b":"Sabunla iyi köpürmez, musluk ve borularda kireçlenmeye yol açar."},{"f":"Su tasarrufunun önemi nedir?","b":"Sınırlı su kaynaklarının gelecek nesillere aktarılması ve ekosistemin korunması için gereklidir."},{"f":"Başlıca hava kirleticileri nelerdir?","b":"Azot oksitler, karbon dioksit ve kükürt oksitleri."},{"f":"Başlıca su ve toprak kirleticileri nelerdir?","b":"Plastikler, deterjanlar, organik sıvılar, ağır metaller, piller, endüstriyel atıklar."},{"f":"Sera etkisi nedir?","b":"Atmosferdeki bazı gazların güneşten gelen ısıyı tutarak dünyanın ısınmasına yol açması."},{"f":"Sera etkisine en çok katkı yapan gazlardan biri hangisidir?","b":"Karbon dioksit (CO₂)."},{"f":"Küresel ısınma nedir?","b":"Sera etkisinin artmasıyla dünya ortalama sıcaklığının zamanla yükselmesi."},{"f":"Asit yağmurlarına yol açan başlıca hava kirleticiler hangileridir?","b":"Kükürt oksitler ve azot oksitler."},{"f":"Piller çevreye nasıl zarar verir?","b":"İçerdikleri ağır metaller (kurşun, cıva vb.) toprağa ve suya karışarak kirlilik oluşturur."},{"f":"Deterjanların su kirliliğine etkisi nedir?","b":"Sulara karışarak sucul canlıların yaşamını olumsuz etkiler, köpük kirliliğine yol açar."},{"f":"Endüstriyel atıkların çevreye etkisi nedir?","b":"Su ve toprağa karışarak kimyasal kirliliğe neden olur."},{"f":"Kimyasal kirletici nedir?","b":"Doğaya (hava, su, toprak) zarar veren, doğal dengeyi bozan kimyasal madde."},{"f":"Atmosferin canlılar için önemi nedir?","b":"Solunum için gerekli gazları sağlar, zararlı güneş ışınlarını filtreler, sıcaklık dengesini korur."},{"f":"Musluk suyundaki kireçlenmenin nedeni nedir?","b":"Sudaki çözünmüş kalsiyum ve magnezyum bileşiklerinin (su sertliği) çökmesi."},{"f":"Organik sıvı kirleticilere örnek nedir?","b":"Petrol türevleri ve çözücüler gibi suya/toprağa karışan organik kimyasallar."},{"f":"Plastik atıkların çevredeki en büyük sorunu nedir?","b":"Doğada çok uzun sürede parçalanması (biyobozunur olmaması) ve birikerek kirliliğe yol açması."},{"f":"Ağır metal kirliliğine örnek hangi elementler verilebilir?","b":"Kurşun (Pb) ve cıva (Hg)."},{"f":"Kükürt oksitlerin başlıca kaynağı nedir?","b":"Kükürt içeren fosil yakıtların (kömür, petrol) yanması."},{"f":"Azot oksitlerin başlıca kaynağı nedir?","b":"Yüksek sıcaklıkta yanma süreçleri (motorlu taşıtlar, sanayi tesisleri)."},{"f":"Çevre kirliliğini azaltmada bireysel sorumluluk neden önemlidir?","b":"Küçük ölçekli tüketim ve atık tercihleri toplamda çevresel etkiyi azaltabilir."}]},{"id":"kim-6","name":"Kimyanın Temel Kanunları ve Kimyasal Hesaplamalar","cards":[{"f":"Kütlenin korunumu kanununu kim ortaya koymuştur?","b":"Antoine Lavoisier."},{"f":"Kütlenin korunumu kanunu ne der?","b":"Kapalı bir sistemde tepkimeye girenlerin toplam kütlesi, ürünlerin toplam kütlesine eşittir."},{"f":"Sabit oranlar kanunu ne der?","b":"Bir bileşiği oluşturan elementlerin kütlece birleşme oranı her zaman sabittir."},{"f":"Sabit oranlar kanununu kim ortaya koymuştur?","b":"Joseph Proust."},{"f":"Katlı oranlar kanunu ne der?","b":"Aynı iki element birden fazla bileşik oluşturuyorsa, sabit kütledeki elementle birleşen diğer elementin kütleleri arasında basit tam sayı oranı vardır."},{"f":"Katlı oranlar kanununu kim ortaya koymuştur?","b":"John Dalton."},{"f":"Demir(II) sülfür (FeS) elde etme deneyi hangi kanunu örnekler?","b":"Sabit oranlar kanunu; demir ve kükürt her zaman aynı kütle oranında birleşir."},{"f":"Bağıl atom kütlesi nasıl tanımlanır?","b":"Bir atomun kütlesinin, karbon-12 atomunun kütlesinin 1/12'sine oranıdır."},{"f":"İzotop atomların ortalama atom kütlesi neden tam sayı çıkmaz?","b":"Doğada bulunan izotopların oranlarına göre ağırlıklı ortalama alındığı için."},{"f":"Mol kavramı neyi ifade eder?","b":"Belirli sayıda (Avogadro sayısı kadar) tanecik içeren madde miktarı birimi."},{"f":"Yanma tepkimesi nedir?","b":"Bir maddenin oksijenle tepkimeye girmesi."},{"f":"Sentez (oluşum) tepkimesi nedir?","b":"İki veya daha fazla maddenin birleşerek tek bir ürün oluşturması."},{"f":"Analiz (ayrışma) tepkimesi nedir?","b":"Tek bir bileşiğin iki veya daha fazla maddeye ayrışması."},{"f":"Asit-baz tepkimesi nedir?","b":"Bir asit ile bir bazın tepkimeye girerek tuz ve su oluşturması (nötralleşme)."},{"f":"Çözünme-çökelme tepkimesi nedir?","b":"Çözelti içindeki iyonların birleşerek suda çözünmeyen katı bir ürün (çökelek) oluşturması."},{"f":"Kurşun(II) iyodür çökme deneyi hangi tepkime türüne örnektir?","b":"Çözünme-çökelme tepkimesi; sarı renkli PbI₂ çökeleği oluşur."},{"f":"Kimyasal tepkime denklemlerinde denkleştirme neden gereklidir?","b":"Kütlenin korunumu kanunu gereği, eşitliğin iki tarafındaki atom sayılarının eşit olması için."},{"f":"Sınırlayıcı bileşen nedir?","b":"Tepkimede ilk tükenen ve oluşabilecek ürün miktarını belirleyen maddedir."},{"f":"Yüzde verim neyi ifade eder?","b":"Gerçekte elde edilen ürün miktarının, teorik olarak beklenen miktara oranının yüzdesini."},{"f":"Kimyanın temel kanunları hangileridir?","b":"Kütlenin korunumu, sabit oranlar ve katlı oranlar kanunları."}]},{"id":"kim-7","name":"Karışımlar","cards":[{"f":"Homojen karışım nedir?","b":"Her noktasında aynı özelliği gösteren, bileşenlerin birbiri içinde tamamen dağıldığı karışım (çözelti)."},{"f":"Heterojen karışım nedir?","b":"Bileşenlerinin karışım içinde farklı bölgelerde ayırt edilebildiği karışım."},{"f":"Çözücü nedir?","b":"Çözeltide miktarca fazla bulunan, çözünmeyi sağlayan bileşen."},{"f":"Çözünen nedir?","b":"Çözeltide miktarca az bulunan, çözücü içinde dağılan bileşen."},{"f":"Süspansiyon nedir?","b":"Katı bir maddenin bir sıvı içinde çözünmeden dağıldığı heterojen karışım."},{"f":"Emülsiyon nedir?","b":"Birbiri içinde çözünmeyen iki sıvının oluşturduğu heterojen karışım (örn. süt, mayonez)."},{"f":"Aerosol nedir?","b":"Katı veya sıvı taneciklerin bir gaz içinde dağılmasıyla oluşan karışım (örn. sis, sprey)."},{"f":"Kolloid nedir?","b":"Tanecik boyutu homojen karışımdan büyük, heterojen karışımdan küçük olan, gözle ayırt edilemeyen dağılım."},{"f":"Adi karışım nedir?","b":"Bileşenleri, tanecik boyutu büyük olduğu için çıplak gözle veya basit yöntemlerle ayırt edilebilen heterojen karışım."},{"f":"Derişik çözelti nedir?","b":"Çözünen madde oranı yüksek olan çözelti."},{"f":"Seyreltik çözelti nedir?","b":"Çözünen madde oranı düşük olan çözelti."},{"f":"Kütlece yüzde derişim nasıl tanımlanır?","b":"100 g çözeltide çözünmüş olan maddenin gram cinsinden miktarı."},{"f":"Hacimce yüzde derişim nasıl tanımlanır?","b":"100 mL çözeltide çözünenin hacimce oranı."},{"f":"ppm birimi neyi ifade eder?","b":"Çözeltide milyonda bir birim cinsinden çok küçük derişimleri."},{"f":"Çözünme sürecinde hangi etkileşimler rol oynar?","b":"Polarlık, hidrojen bağı ve çözücü-çözünen benzerliği (benzer benzeri çözer ilkesi)."},{"f":"Çözeltilerin donma/kaynama noktası saf çözücüden nasıl farklıdır?","b":"Derişime bağlı olarak değişir; donma noktası düşer, kaynama noktası yükselir."},{"f":"Mıknatısla ayırma hangi fiziksel farktan yararlanır?","b":"Manyetik özellik (mıknatısa çekilme) farkından."},{"f":"Eleme, süzme ve diyaliz hangi fiziksel farktan yararlanır?","b":"Tanecik boyutu farkından."},{"f":"Ayırma hunisi ve yüzdürme hangi fiziksel farktan yararlanır?","b":"Yoğunluk farkından."},{"f":"Basit damıtma ve ayrımsal damıtma hangi fiziksel farktan yararlanır?","b":"Kaynama noktası farkından."},{"f":"Özütleme, kristallendirme ve ayrımsal kristallendirme hangi fiziksel farktan yararlanır?","b":"Çözünürlük farkından."},{"f":"Basit damıtma ile ayrımsal damıtma arasındaki fark nedir?","b":"Basit damıtma tek bileşeni ayırır; ayrımsal damıtma kaynama noktaları birbirine yakın birden fazla sıvıyı ayırır."},{"f":"Özütleme (ekstraksiyon) nedir?","b":"Bir karışımdaki bileşenin uygun bir çözücüyle çekilerek ayrılması."},{"f":"Ayrımsal kristallendirme ne zaman tercih edilir?","b":"Çözünürlükleri sıcaklıkla farklı değişen iki katıyı birbirinden ayırmak için."},{"f":"Diyaliz yönteminde hangi tür zar kullanılır?","b":"Yarı geçirgen zar; küçük tanecikler geçer, büyük tanecikler geçemez."}]},{"id":"kim-8","name":"Asitler, Bazlar ve Tuzlar","cards":[{"f":"Asitlerin ortak özelliklerinden biri nedir?","b":"Ekşi tat, turnusolü kırmızıya çevirme, metallerle tepkimeye girip hidrojen gazı çıkarma."},{"f":"Bazların ortak özelliklerinden biri nedir?","b":"Ele kayganlık hissi verme, turnusolü maviye çevirme, acı tat."},{"f":"Asitler suda çözündüğünde moleküler düzeyde ne oluşturur?","b":"H₃O⁺ (hidronyum) iyonu."},{"f":"Bazlar suda çözündüğünde moleküler düzeyde ne oluşturur?","b":"OH⁻ (hidroksit) iyonu."},{"f":"İndikatör (belirteç) nedir?","b":"Ortamın asit mi baz mı olduğunu renk değişimiyle gösteren madde."},{"f":"Kırmızı lahana suyu neden indikatör olarak kullanılabilir?","b":"Asidik ve bazik ortamlarda farklı renkler alarak ortamın asitlik-bazlığını gösterir."},{"f":"pH kağıdı ne işe yarar?","b":"Bir çözeltinin asitlik-bazlık derecesini renk değişimiyle yaklaşık olarak ölçmeye yarar."},{"f":"pH değeri küçüldükçe ortam nasıl olur?","b":"Daha asidik olur."},{"f":"pH değeri büyüdükçe ortam nasıl olur?","b":"Daha bazik olur."},{"f":"CO₂, SO₂ ve N₂O₅ suyla tepkimeye girdiğinde nasıl davranır?","b":"Asit gibi davranan çözeltiler oluşturur."},{"f":"NH₃ ve CaO suyla tepkimeye girdiğinde nasıl davranır?","b":"Baz gibi davranan çözeltiler oluşturur."},{"f":"Nötralleşme tepkimesinin ürünleri nelerdir?","b":"Tuz ve su."},{"f":"Sodyum hidroksit ile sülfürik asit tepkimeye girerse hangi tuz oluşur?","b":"Sodyum sülfat."},{"f":"Aktif metal nedir?","b":"Asitlerle kolayca tepkimeye girip hidrojen gazı çıkaran, reaktifliği yüksek metal (örn. sodyum, potasyum)."},{"f":"Soy metal nedir?","b":"Asitlerle kolay kolay tepkimeye girmeyen, reaktifliği çok düşük metal (örn. altın, platin)."},{"f":"Yarı soy metal nedir?","b":"Aktif metal ile soy metal arası reaktiflikte olan metal (örn. bakır, gümüş)."},{"f":"Amfoter metal nedir?","b":"Hem asitlerle hem bazlarla tepkimeye girebilen metal (örn. alüminyum, çinko)."},{"f":"Hangi asit camı ve porseleni aşındırabilir?","b":"Hidroflorik asit (HF)."},{"f":"Derişik sülfürik asidin tehlikeli özelliği nedir?","b":"Güçlü nem çekme (higroskopik) özelliği ve çözünürken yüksek ısı açığa çıkarması."},{"f":"Çamaşır suyu ile tuz ruhu (HCl) neden birlikte kullanılmamalıdır?","b":"Karıştıklarında zehirli klor gazı açığa çıkabilir."},{"f":"Asit yağmurlarının tarihi eserlere etkisi nedir?","b":"İçerdiği asitler taş ve metal yapıları aşındırarak zamanla tahrip eder."},{"f":"Kostiğin (NaOH) cilt ve saça etkisi nasıldır?","b":"Yakıcı ve tahriş edicidir, dokulara zarar verebilir."},{"f":"Sodyum klorürün kullanım alanı nedir?","b":"Sofra tuzu olarak gıdalarda, ayrıca endüstride kullanılır."},{"f":"Sodyum karbonatın kullanım alanı nedir?","b":"Çamaşır sodası olarak temizlikte ve cam üretiminde kullanılır."},{"f":"Sodyum bikarbonatın kullanım alanı nedir?","b":"Kabartma tozu olarak gıdalarda, ayrıca mide asidini nötralleştirmede kullanılır."},{"f":"Kalsiyum karbonatın kullanım alanı nedir?","b":"Kireçtaşı/mermer olarak inşaatta, ayrıca mide ilaçlarında kullanılır."},{"f":"Amonyum klorürün kullanım alanı nedir?","b":"Nişadır olarak lehimlemede ve bazı pillerde kullanılır."},{"f":"Alüminyumun amfoterlik özelliği ne anlama gelir?","b":"Hem asitlerle hem bazlarla tepkimeye girerek çözünebilmesi."}]},{"id":"kim-9","name":"Kimya Her Yerde","cards":[{"f":"Yüzey aktif madde (surfaktan) nedir?","b":"Bir ucu suyu seven (polar), bir ucu yağı seven (apolar) yapısıyla kiri sudan uzaklaştırabilen madde."},{"f":"Sabun ve deterjanların kirleri temizleme prensibi nedir?","b":"Apolar uçlarıyla yağ/kiri, polar uçlarıyla suyu tutarak kirin suyla uzaklaştırılmasını sağlarlar."},{"f":"Ağartıcı olarak yaygın kullanılan madde hangisidir?","b":"Çamaşır suyu (sodyum hipoklorit)."},{"f":"Hijyen amacıyla kullanılan temizlik maddelerine örnek nedir?","b":"Çamaşır suyu, kireç kaymağı."},{"f":"Monomer nedir?","b":"Polimer zincirini oluşturan tekrar eden küçük yapı birimi."},{"f":"Polimer nedir?","b":"Çok sayıda monomerin birbirine bağlanmasıyla oluşan büyük moleküllü madde."},{"f":"Kauçuğun başlıca kullanım alanı nedir?","b":"Lastik ve esnek malzeme üretimi."},{"f":"Polietilen (PE) nerelerde kullanılır?","b":"Poşet ve plastik şişe üretiminde."},{"f":"Polietilen tereftalat (PET) nerelerde kullanılır?","b":"İçecek şişelerinde."},{"f":"Kevlar hangi özelliğiyle bilinir ve nerede kullanılır?","b":"Çok yüksek dayanıklılığıyla; kurşun geçirmez yelek gibi koruyucu malzemelerde kullanılır."},{"f":"Polivinil klorür (PVC) nerelerde kullanılır?","b":"Boru ve kablo kaplamalarında."},{"f":"Teflon (politetraflor eten) nerede kullanılır?","b":"Yapışmaz tava kaplamalarında."},{"f":"Polistiren (PS) nerelerde kullanılır?","b":"Köpük ambalaj malzemelerinde."},{"f":"Polimer, kağıt, cam ve metal geri dönüşümünün faydası nedir?","b":"Doğal kaynakların korunması ve ülke ekonomisine katkı sağlaması."},{"f":"Kozmetik ürünlerde zararlı olabilecek kimyasallara hangi ürünler örnek verilir?","b":"Parfüm, saç boyası, kalıcı dövme boyası, jöle."},{"f":"İlaçların piyasadaki başlıca formları nelerdir?","b":"Hap, şurup, iğne, merhem."},{"f":"Yanlış/gereksiz ilaç kullanımının zararı nedir?","b":"İnsan sağlığına, ülke ekonomisine ve çevreye zarar verir."},{"f":"Hazır gıdalarda bulunabilen katkı türleri nelerdir?","b":"Koruyucular, renklendiriciler, emülsiyonlaştırıcılar, tatlandırıcılar."},{"f":"Pastörizasyon nedir?","b":"Gıdalardaki zararlı mikroorganizmaları belirli sıcaklıkta ısıtarak azaltma işlemi."},{"f":"UHT süt nedir?","b":"Çok yüksek sıcaklıkta kısa süreli ısıtılarak dayanıklı hale getirilmiş süt."},{"f":"Katı yağlara örnek nedir?","b":"Tereyağı, margarin."},{"f":"Sıvı yağlara örnek nedir?","b":"Zeytinyağı, ayçiçek yağı, mısır özü yağı, fındık yağı."},{"f":"Sızma zeytinyağı ne anlama gelir?","b":"İlk sıkımda, herhangi bir işlem/rafinasyon görmeden elde edilen zeytinyağı."},{"f":"Rafine yağ nedir?","b":"Arıtma işlemlerinden geçirilerek koku, renk ve tat açısından saflaştırılmış yağ."},{"f":"Şampuan, diş macunu, katı ve sıvı sabun neden kişisel temizlik ürünüdür?","b":"Yüzey aktif maddeler içererek kir ve yağı temizlemeye yardımcı olurlar."},{"f":"Hazır gıda etiketlerinde nelere dikkat edilmelidir?","b":"Üretim ve son kullanma tarihine, içerik ve katkı maddesi bilgisine."},{"f":"Oyuncak ve tekstil ürünlerinde kullanılan polimer malzemelerin olası zararı nedir?","b":"İçerdikleri bazı kimyasallar (ör. yumuşatıcılar) sağlığa zarar verebilir."},{"f":"Apolar grup kavramı hangi bağlamda geçer?","b":"Sabun/deterjan moleküllerinin yağı tutan, suyu sevmeyen kısmı."},{"f":"Polar uç kavramı hangi bağlamda geçer?","b":"Sabun/deterjan moleküllerinin suyu tutan, suyu seven kısmı."},{"f":"Vinterize yağ ne anlama gelir?","b":"Soğukta bulanıklaşmaması için düşük sıcaklıkta katılaşan bileşenleri ayrılmış yağ."}]}]},{"subject":"Biyoloji","units":[{"id":"biy-1","name":"Canlıların Ortak Özellikleri","cards":[{"f":"Canlıların ortak özellikleri nelerdir?","b":"Hücresel yapı, beslenme, solunum, boşaltım, hareket, uyarılara tepki, metabolizma, homeostazi, uyum, organizasyon, üreme, büyüme ve gelişme."},{"f":"Metabolizma nedir?","b":"Hücrede gerçekleşen yapım (anabolik) ve yıkım (katabolik) tepkimelerinin tümüdür."},{"f":"Anabolizma ile katabolizma arasındaki fark nedir?","b":"Anabolizma enerji harcayarak küçük moleküllerden büyük molekül yapar; katabolizma büyük molekülleri parçalayıp enerji açığa çıkarır."},{"f":"Homeostazi nedir?","b":"Canlının dış ortam değişse bile iç ortamını (sıcaklık, pH, su-tuz dengesi vb.) sabit tutabilme yeteneğidir."},{"f":"Canlı organizasyon basamakları küçükten büyüğe nasıl sıralanır?","b":"Hücre, doku, organ, sistem, organizma, popülasyon, komünite, ekosistem, biyom, biyosfer."},{"f":"Boşaltım neden canlıların ortak bir özelliğidir?","b":"Metabolizma sonucu oluşan zararlı ya da fazla atık maddelerin vücuttan uzaklaştırılması gerekir."},{"f":"Büyüme ile gelişme arasındaki fark nedir?","b":"Büyüme hücre sayısı ve boyut artışıdır; gelişme ise yapısal ve işlevsel olgunlaşmadır (farklılaşmadır)."},{"f":"Canlılarda uyum (adaptasyon) ne demektir?","b":"Canlının yaşadığı ortamda hayatta kalmasını ve üremesini kolaylaştıran özellikler kazanmasıdır."},{"f":"Üreme neden canlıların ortak özelliği sayılır?","b":"Türün nesiller boyunca devamını sağlayan temel yaşamsal olaydır."},{"f":"Solunum canlılar için neden gereklidir?","b":"Besinlerdeki kimyasal enerjiyi hücrenin kullanabileceği ATP enerjisine dönüştürmek için gereklidir."},{"f":"Hareket özelliği sadece yer değiştirme midir?","b":"Hayır; bitkilerde yer değiştirme olmasa da ışığa yönelme gibi yer değiştirmeyen hareketler görülür."},{"f":"Canlıların hücresel yapıda olması ne anlama gelir?","b":"Her canlı en az bir hücreden oluşur; hücre yaşamın en küçük yapısal ve işlevsel birimidir."},{"f":"Kontrollü bir deneyde bağımsız değişken nedir?","b":"Deneyi yapanın kasıtlı olarak değiştirdiği, etkisi araştırılan değişkendir."},{"f":"Kontrollü bir deneyde bağımlı değişken nedir?","b":"Bağımsız değişkene bağlı olarak değişen ve ölçülen sonuçtur."},{"f":"Kontrol grubu ne işe yarar?","b":"Test edilen değişken dışında her koşulun aynı tutulduğu, karşılaştırma yapılan gruptur."},{"f":"Robert Hooke hücre teorisine nasıl katkı sağlamıştır?","b":"Mikroskopla mantar dokusunu inceleyip küçük boşlukları ilk kez hücre olarak adlandırmıştır."},{"f":"Rudolf Virchow'un hücre teorisine katkısı nedir?","b":"Her hücrenin daha önceden var olan bir hücrenin bölünmesiyle oluştuğunu ileri sürmüştür."},{"f":"Metabolizma hızını etkileyen faktörlere örnek ver.","b":"Vücut sıcaklığı, hormon düzeyi, yaş ve fiziksel aktivite düzeyi metabolizma hızını etkiler."},{"f":"Canlılarda uyarılara tepki özelliğine örnek ver.","b":"Bitkinin ışığa doğru yönelmesi veya bir hayvanın ani sese tepki olarak kaçması."},{"f":"Biyoloji bilimi neyi inceler?","b":"Canlıları, canlıların yapısını, işlevlerini ve birbirleriyle-çevreyle ilişkilerini inceleyen bilim dalıdır."},{"f":"Bir hücrenin organizasyon özelliği ne demektir?","b":"Hücre içindeki yapı ve organellerin uyum içinde, düzenli bir bütün oluşturmasıdır."},{"f":"Canlılarda büyüme hangi temel hücresel olayla gerçekleşir?","b":"Hücre sayısının mitoz bölünmeyle artması ve/veya hücre hacminin büyümesiyle gerçekleşir."}]},{"id":"biy-2","name":"Canlıların Temel Bileşenleri","cards":[{"f":"Su canlılar için neden önemlidir?","b":"Polar bir moleküldür, iyi bir çözücüdür, hücre içi tepkimelerin ortamını oluşturur ve sıcaklık dengesine yardımcı olur."},{"f":"İnorganik ve organik bileşik arasındaki fark nedir?","b":"İnorganik bileşikler (su, mineral, asit, baz, tuz) canlıların dışarıdan hazır aldığı maddelerdir; organik bileşikler (karbonhidrat, protein, lipit, vitamin, nükleik asit) karbon iskeletlidir ve canlılar tarafından üretilebilir."},{"f":"Mineraller yakıldığında neden kül olarak kalır?","b":"Mineraller inorganik olduğu için yanmaz; organik kısım yanınca geriye mineral kalıntısı (kül) kalır."},{"f":"Kalsiyumun canlılar için önemi nedir?","b":"Kemik ve diş yapısına katılır; kas kasılması ve kanın pıhtılaşmasında rol oynar."},{"f":"Demir eksikliği hangi rahatsızlığa yol açar?","b":"Kansızlığa (anemi) yol açar; demir, hemoglobinin oksijen taşıyan yapısında bulunur."},{"f":"İyot eksikliğinde hangi hastalık görülür?","b":"Guatr görülür; iyot tiroid bezinin hormon üretimi için gereklidir."},{"f":"Sodyum ve potasyum canlılarda hangi işlevde önemlidir?","b":"Sinir hücrelerinde uyartı iletimini ve hücre içi-dışı su/madde dengesini sağlarlar."},{"f":"Fosforun canlılardaki önemi nedir?","b":"Kemik ve diş yapısına katılır; ayrıca ATP ve nükleik asitlerin (DNA, RNA) yapısında bulunur."},{"f":"Florun canlılar için önemi nedir?","b":"Diş minesini güçlendirerek diş çürümesine karşı koruma sağlar."},{"f":"Karbonhidratların yapı taşı nedir?","b":"Monosakkaritlerdir (basit şekerler); örnek: glikoz."},{"f":"Monosakkarit-disakkarit-polisakkarit farkı nedir?","b":"Monosakkarit tek şeker biriminden, disakkarit iki birimin, polisakkarit çok sayıda birimin birleşmesinden oluşur."},{"f":"Hayvan ve mantar hücreleri fazla glikozu nasıl depolar?","b":"Glikojen şeklinde depolar."},{"f":"Bitkiler fazla glikozu nasıl depolar?","b":"Nişasta şeklinde depolar."},{"f":"Selülozun görevi nedir?","b":"Bitki hücre duvarının yapı taşıdır; insan sindirim sisteminde sindirilemeyen bir lif kaynağıdır."},{"f":"Proteinlerin yapı taşı nedir ve aralarında hangi bağ bulunur?","b":"Amino asitlerdir; amino asitler arasında peptit bağı bulunur."},{"f":"Bazı amino asitler için vücutta üretilemez ifadesi ne anlama gelir?","b":"Bu amino asitler besinlerle dışarıdan alınmak zorundadır; vücut kendisi sentezleyemez."},{"f":"Enzimlerin temel özellikleri nelerdir?","b":"Protein yapılı biyokatalizördürler, tepkimeye özgüdürler, tepkime sonunda yapıları değişmez ve tekrar kullanılabilirler."},{"f":"Enzim aktivitesini etkileyen faktörler nelerdir?","b":"Sıcaklık, ortam pH'ı ve madde (substrat/enzim) derişimi enzim aktivitesini etkiler."},{"f":"Enzimler yüksek sıcaklıkta neden görev yapamaz hale gelir?","b":"Yüksek sıcaklık enzimin yapısını bozar (denatürasyon), bu yüzden görevini yapamaz."},{"f":"Yağda çözünen vitaminler hangileridir?","b":"A, D, E ve K vitaminleridir; fazlası vücutta (karaciğer ve yağ dokusunda) depolanabilir."},{"f":"Suda çözünen vitaminler hangileridir?","b":"B grubu vitaminleri ve C vitaminidir; vücutta depolanmaz, fazlası idrarla atılır."},{"f":"D vitamini eksikliğinde ne görülür?","b":"Kemik gelişim bozukluğu (raşitizm) görülebilir."},{"f":"Nükleik asitlerin yapı taşı nedir?","b":"Nükleotidlerdir (şeker, fosfat ve azotlu bazdan oluşur)."},{"f":"DNA tüm canlı türlerinde ortak olan hangi özelliğe sahiptir?","b":"Tüm canlı türlerinde bulunur ve aynı çeşit nükleotidlerden yapılmıştır."},{"f":"DNA ile RNA arasındaki temel fark nedir?","b":"DNA çift zincirli ve şekeri deoksiribozdur; RNA tek zincirli ve şekeri ribozdur."},{"f":"ATP canlılar için neden önemlidir?","b":"Hücrenin yaşamsal faaliyetlerinde kullandığı temel enerji taşıyıcı molekülüdür."},{"f":"Hormonların canlılardaki görevi nedir?","b":"Belirli bezlerden salgılanıp kana karışan, hedef organlarda özel etkiler oluşturan kimyasal habercilerdir."}]},{"id":"biy-3","name":"Hücre ve Madde Geçişleri","cards":[{"f":"Hücre teorisine göre canlılığın temel birimi nedir?","b":"Hücredir; tüm canlılar hücrelerden oluşur."},{"f":"Prokaryot hücre ile ökaryot hücre arasındaki temel fark nedir?","b":"Prokaryot hücrede zarla çevrili çekirdek ve zarlı organel bulunmaz; ökaryot hücrede bulunur."},{"f":"Hangi canlı grupları prokaryot hücre yapısındadır?","b":"Bakteriler ve arkeler prokaryot hücre yapısındadır."},{"f":"Ribozomun görevi nedir?","b":"Protein sentezi yapar; hem prokaryot hem ökaryot hücrelerde bulunan zarsız bir yapıdır."},{"f":"Mitokondrinin görevi nedir?","b":"Oksijenli solunum yaparak hücrenin ihtiyaç duyduğu ATP'nin büyük kısmını üretir."},{"f":"Golgi aygıtının görevi nedir?","b":"Endoplazmik retikulumdan gelen madde ve proteinleri işler, paketler ve hücre içindeki bölgelere gönderir."},{"f":"Lizozomun görevi nedir?","b":"Hayvan hücrelerinde hücre içi sindirimi gerçekleştirir."},{"f":"Kloroplastın görevi nedir?","b":"Işık enerjisini kullanarak fotosentezle besin (organik madde) ve oksijen üretir."},{"f":"Hücre iskeletinin görevi nedir?","b":"Hücrenin şeklinin oluşmasını ve korunmasını sağlar; hücre bölünmesi gibi olaylarda da görev alır."},{"f":"Sentrozom hangi hücrelerde bulunur ve görevi nedir?","b":"Hayvan hücrelerinde bulunur; hücre bölünmesinde görev alır."},{"f":"Kofulun (vakuolün) görevi nedir?","b":"Su, besin ve atık maddelerin depolanmasını veya dışarı atılmasını sağlar."},{"f":"Bitki ve hayvan hücresi arasındaki üç temel fark nedir?","b":"Bitki hücresinde hücre duvarı, büyük koful ve kloroplast bulunur; hayvan hücresinde bunlar bulunmaz."},{"f":"Mitokondri ve kloroplastın ortak özelliği nedir?","b":"İkisi de çift zarla çevrilidir ve kendilerine ait DNA'ya sahiptir."},{"f":"Hücre zarının genel yapısı nasıldır?","b":"Akıcı mozaik model ile açıklanır; çift katlı yağ tabakası içine gömülü proteinlerden oluşur."},{"f":"Hücre zarının seçici geçirgen olması ne demektir?","b":"Bazı maddelerin serbestçe, bazılarının ise sınırlı ya da hiç geçmediği bir zar özelliğidir."},{"f":"Difüzyon nedir?","b":"Küçük moleküllerin yoğun olduğu ortamdan az yoğun olduğu ortama, enerji harcanmadan geçişidir."},{"f":"Osmoz nedir?","b":"Suyun yarı geçirgen bir zardan az yoğun (hipotonik) ortamdan çok yoğun (hipertonik) ortama geçişidir."},{"f":"Aktif taşıma difüzyondan nasıl farklıdır?","b":"Aktif taşımada madde derişim farkına karşı, ATP harcanarak taşınır; difüzyonda enerji harcanmaz."},{"f":"İzotonik ortama bırakılan bir hücrede su alışverişi nasıl olur?","b":"Hücre içi ve dışı yoğunluk eşit olduğu için gözle görülür bir değişiklik olmaz."},{"f":"Hipotonik ortama konan bir hayvan hücresine ne olur?","b":"Hücre su alır, şişer ve aşırı su alımı hücrenin patlamasına (hemolize) yol açabilir."},{"f":"Hipertonik ortama konan bir bitki hücresine ne olur?","b":"Hücre su kaybeder, sitoplazma hücre çeperinden ayrılır (plazmoliz)."},{"f":"Turgor hali nedir?","b":"Bitki hücresinin hipotonik ortamda su alarak şişkin ve diri bir hal almasıdır."},{"f":"Endositoz nedir?","b":"Hücrenin büyük parçacıkları, zarını içe katlayarak ATP harcayıp hücre içine almasıdır."},{"f":"Fagositoz ile pinositoz arasındaki fark nedir?","b":"Fagositoz katı parçacıkların, pinositoz ise sıvı damlacıklarının hücre içine alınmasıdır."},{"f":"Ekzositoz nedir?","b":"Hücre içindeki maddelerin kese içinde hücre zarına taşınıp dışarı atılmasıdır; ATP harcanır."},{"f":"Hücre zarından madde geçişini etkileyen faktörler nelerdir?","b":"Ortamın sıcaklığı, derişim (konsantrasyon) farkı ve zarın yüzey alanı madde geçiş hızını etkiler."}]},{"id":"biy-4","name":"Canlılar Dünyası ve Sınıflandırma","cards":[{"f":"Sınıflandırmada kullanılan basamaklar (büyükten küçüğe) nelerdir?","b":"Âlem, şube, sınıf, takım, aile (familya), cins, tür."},{"f":"Sistematik birimlerin en büyüğü hangisidir?","b":"Âlemdir; en fazla canlı türünü içine alan sınıflandırma basamağıdır."},{"f":"Tür nedir?","b":"Ortak bir atadan gelen, doğal koşullarda çiftleştiğinde verimli döller verebilen bireyler topluluğudur."},{"f":"İkili adlandırma sistemini kim geliştirmiştir?","b":"Carolus Linnaeus geliştirmiştir; canlı adı Cins türadı biçiminde yazılır (örn. Homo sapiens)."},{"f":"Sınıflandırmada cins basamağı ne ifade eder?","b":"Birbirine benzer ve ortak birçok özelliği olan türler topluluğudur."},{"f":"Canlıların sınıflandırılmasında kullanılan 6 alem hangileridir?","b":"Bakteriler, Arkeler, Protistler, Bitkiler, Mantarlar, Hayvanlar."},{"f":"Alemler daha büyük hangi gruplarda toplanır?","b":"Bakteri, Arke ve Ökaryot olmak üzere 3 büyük domain (üst âlem) grubunda toplanır."},{"f":"Bakteriler âleminin genel özellikleri nelerdir?","b":"Prokaryot ve tek hücrelidirler; DNA'ları halka şeklindedir, fazla karbonhidratı glikojen olarak depolarlar."},{"f":"Arkelerin bakterilerden ayrılan özelliği nedir?","b":"Arkelerin hücre duvarında peptidoglikan bulunmaz; genellikle sıra dışı (aşırı) ortamlarda yaşarlar."},{"f":"Protistler âleminin genel özelliği nedir?","b":"Ökaryot hücre yapısına sahiptirler; tek hücreli veya çok hücreli (örn. algler) olabilirler."},{"f":"Bitkiler âleminin genel özellikleri nelerdir?","b":"Ökaryot, çok hücreli, hücre duvarı selülozdan yapılı, fotosentezle kendi besinini üreten canlılardır."},{"f":"Bitkiler fotosentez ürünü glikozu nasıl depolar?","b":"Nişasta olarak depolar."},{"f":"Mantarlar âleminin genel özellikleri nelerdir?","b":"Ökaryot, hücre duvarı kitin yapılıdır, glikojen depolar ve hazır organik maddeyle beslenir."},{"f":"Mantarların doğadaki en önemli görevlerinden biri nedir?","b":"Organik atıkları inorganik maddelere dönüştüren ayrıştırıcı olarak madde döngüsüne katkı sağlarlar."},{"f":"Hayvanlar âleminin genel özellikleri nelerdir?","b":"Ökaryot, çok hücreli, hücre duvarı yok, hazır besinle (heterotrof) beslenen canlılardır."},{"f":"Hayvanlar âlemi sınıflandırılırken dikkate alınan ilk ölçüt nedir?","b":"Omurga varlığıdır; hayvanlar bu ölçüte göre omurgalı ve omurgasız olarak ikiye ayrılır."},{"f":"Omurgasız hayvan gruplarına örnek ver (en az 4).","b":"Süngerler, sölenterler, solucanlar, yumuşakçalar, eklem bacaklılar, derisi dikenliler."},{"f":"Omurgalı hayvan gruplarını sırala.","b":"Balıklar, iki yaşamlılar, sürüngenler, kuşlar, memeliler."},{"f":"Bitkiler âlemi hangi iki ana gruba ayrılır?","b":"Tohumsuz (sporlu) bitkiler ve tohumlu bitkiler; tohumlu bitkiler de açık tohumlu ve kapalı tohumlu olarak ayrılır."},{"f":"Virüsler neden bir canlı âlemine dahil edilmez?","b":"Hücresel yapıya sahip değildirler, tek başlarına metabolizma yürütemez ve üreyemezler."},{"f":"Virüsler nasıl çoğalır?","b":"Ancak girdikleri bir konak hücrenin yapılarını (enzim, ribozom, ATP vb.) kullanarak çoğalabilirler."},{"f":"Virüslerin neden olduğu hastalıklara örnek ver.","b":"Kuduz, hepatit, grip, uçuk ve AIDS virüslerin neden olduğu hastalıklardandır."},{"f":"Virüslere karşı neden antibiyotik etkisizdir?","b":"Antibiyotikler bakterilere özgü yapı ve enzim sistemlerini hedef alır; virüslerde böyle bir sistem yoktur."},{"f":"Canlıların sınıflandırılmasına bilim insanları neden farklı ölçüt kullanır?","b":"Canlı çeşitliliği çok büyük olduğu için sınıflandırma zamanla yeni bulgularla sınanır, düzeltilir ve yenilenir."}]},{"id":"biy-5","name":"Hücre Bölünmeleri ve Üreme","cards":[{"f":"Hücre bölünmesi canlılar için neden gereklidir?","b":"Büyüme, gelişme, onarım (yara iyileşmesi) ve üreme için gereklidir."},{"f":"Mitoz sonucunda kaç yavru hücre oluşur ve bunlar ana hücreyle nasıl bir ilişkidedir?","b":"2 yavru hücre oluşur; bu hücreler ana hücre ile genetik olarak aynıdır (kromozom sayısı korunur)."},{"f":"İnterfazda hücrede temel olarak ne gerçekleşir?","b":"Hücre büyür ve bölünme öncesi DNA kendini eşler (replikasyon yapar)."},{"f":"Mitozun evrelerini sırayla say.","b":"Profaz, metafaz, anafaz, telofaz; öncesinde interfaz vardır."},{"f":"Profaz evresinde ne olur?","b":"Kromatin iplikler kısalıp kalınlaşarak kromozomları oluşturur, çekirdek zarı kaybolmaya başlar."},{"f":"Metafaz evresinde ne olur?","b":"Kromozomlar hücrenin ortasına (ekvatoral düzleme) dizilir."},{"f":"Anafaz evresinde ne olur?","b":"Kardeş kromatidler birbirinden ayrılıp hücrenin zıt kutuplarına çekilir."},{"f":"Telofaz evresinde ne olur?","b":"Çekirdek zarı yeniden oluşur ve sitoplazma bölünmesi (sitokinez) başlar."},{"f":"Hücre bölünmesinin kontrolden çıkması hangi hastalıkla ilişkilidir?","b":"Kanserle ilişkilidir; kontrolsüz ve düzensiz hücre çoğalması sonucu oluşur."},{"f":"Eşeysiz üreme çeşitlerine örnek ver (en az 4).","b":"Bölünerek üreme, tomurcuklanma, sporla üreme, rejenerasyon, partenogenez, bitkilerde vejetatif üreme."},{"f":"Partenogenez nedir?","b":"Döllenmemiş yumurta hücresinin gelişerek doğrudan yeni bir birey oluşturmasıdır (bazı arı ve karınca türlerinde görülür)."},{"f":"Rejenerasyon nedir?","b":"Bir canlının kopan bir parçasından yeni bir birey oluşturabilmesidir (örn. planarya)."},{"f":"Vejetatif üreme nedir?","b":"Bitkilerin kök, gövde veya yaprak gibi kısımlarından eşeysiz olarak yeni birey oluşturmasıdır."},{"f":"Mayozun temel amacı nedir?","b":"Üreme hücrelerinin (gamet) oluşmasını sağlamak ve kromozom sayısını yarıya indirmektir."},{"f":"Mayoz sonunda kaç hücre oluşur ve kromozom sayıları nasıldır?","b":"4 yavru hücre oluşur; her biri ana hücrenin yarısı kadar kromozoma (haploit, n) sahiptir."},{"f":"Diploit (2n) ve haploit (n) ne demektir?","b":"Diploit kromozomların çift takım hâlinde bulunması, haploit ise tek takım hâlinde bulunmasıdır."},{"f":"Mayoza özgü olup mitozda görülmeyen olay nedir?","b":"Krossing over (parça değişimi); homolog kromozomlar arasında gerçekleşir ve genetik çeşitliliği artırır."},{"f":"Sinapsis ve tetrat kavramları neyi ifade eder?","b":"Sinapsis homolog kromozomların eşleşmesi, tetrat bu eşleşme sonucu oluşan dört kromatitlik yapıdır."},{"f":"Mitoz ile mayoz arasındaki temel fark nedir?","b":"Mitoz vücut hücrelerinde 2 hücre oluştururken, mayoz üreme ana hücrelerinde 4 hücre oluşturur ve genetik çeşitlilik sağlar."},{"f":"Eşeyli üreme neye dayanır?","b":"Mayoz ile oluşan gametlerin döllenme yoluyla birleşmesine dayanır."},{"f":"Döllenme (fertilizasyon) nedir?","b":"Erkek ve dişi üreme hücrelerinin (gametlerin) birleşerek zigotu oluşturmasıdır."},{"f":"Eşeyli üremenin eşeysiz üremeye göre avantajı nedir?","b":"Yavrularda genetik çeşitlilik sağlayarak türün değişen çevre koşullarına uyumunu kolaylaştırır."},{"f":"Eşeysiz üremenin avantajı nedir?","b":"Tek ebeveyn yeterlidir; hızlı ve kısa sürede çok sayıda birey üretilebilir."},{"f":"Bitkilerde çelikle üretme hangi üreme çeşidine örnektir?","b":"Vejetatif (eşeysiz) üremeye örnektir; tarım ve bahçecilikte yaygın kullanılır."}]},{"id":"biy-6","name":"Kalıtım","cards":[{"f":"Gregor Mendel neden önemlidir?","b":"Bezelye bitkileri üzerinde yaptığı deneylerle kalıtımın genler aracılığıyla nesilden nesile aktarıldığını ilk gösteren bilim insanıdır."},{"f":"Gen ve alel kavramlarını tanımla.","b":"Gen bir özelliği belirleyen kalıtım birimidir; alel ise bir genin farklı biçimlerinden her biridir."},{"f":"Genotip ve fenotip arasındaki fark nedir?","b":"Genotip bireyin sahip olduğu alel yapısıdır (örn. Aa); fenotip bu yapının dışa yansıyan gözlenebilir hâlidir."},{"f":"Homozigot ve heterozigot ne demektir?","b":"Homozigot bir özellik için aynı alellere (AA/aa), heterozigot farklı alellere (Aa) sahip olma durumudur."},{"f":"Baskın (dominant) ve çekinik (resesif) alel arasındaki fark nedir?","b":"Baskın alel heterozigot bireyde bile fenotipte görülür; çekinik alel yalnızca homozigot durumda görülür."},{"f":"Otozom ve gonozom arasındaki fark nedir?","b":"Otozomlar eşey belirlemeyen kromozomlardır; gonozomlar (eşey kromozomları) bireyin eşeyini belirler."},{"f":"Monohibrit çaprazlama nedir?","b":"Tek bir karakter (özellik) bakımından yapılan çaprazlamadır."},{"f":"Dihibrit çaprazlama nedir?","b":"İki farklı karakterin birlikte incelendiği çaprazlamadır."},{"f":"Aa x Aa (monohibrit) çaprazlamasının fenotip oranı nedir?","b":"3 baskın : 1 çekinik oranı elde edilir (genotipte 1:2:1)."},{"f":"Kontrol (test) çaprazlaması ne amaçla yapılır?","b":"Baskın fenotipli bir bireyin homozigot mu heterozigot mu olduğunu anlamak için, o birey homozigot çekinik bireyle çaprazlanır."},{"f":"Punnett karesi ne işe yarar?","b":"Bir çaprazlama sonucunda oluşabilecek genotip ve fenotip olasılıklarını görsel olarak hesaplamaya yarar."},{"f":"Eş baskınlık (kodominantlık) nedir?","b":"Heterozigot bireyde iki farklı alelin de, birbirine karışmadan fenotipte ayrı ayrı görülmesidir."},{"f":"Çok alellilik nedir, hangi örnekle ilişkilendirilir?","b":"Bir genin ikiden fazla alelinin bulunmasıdır; kan grubu (ABO sistemi) ile ilişkilendirilir."},{"f":"ABO kan grubu sisteminde kaç alel bulunur?","b":"Üç alel bulunur: I^A, I^B ve i."},{"f":"AB kan grubu hangi kalıtım şekline örnektir?","b":"Eş baskınlığa (kodominantlığa) örnektir; I^A ve I^B aleli birlikte, karışmadan ifade edilir."},{"f":"Eşeye bağlı kalıtım nedir?","b":"Genin eşey kromozomu (X ya da Y) üzerinde taşınmasıyla ortaya çıkan kalıtım şeklidir."},{"f":"Hemofili nasıl kalıtılır?","b":"X kromozomu üzerinde çekinik olarak kalıtılan bir kan pıhtılaşma bozukluğudur; erkeklerde daha sık görülür."},{"f":"Kısmi renk körlüğü nasıl kalıtılır?","b":"X kromozomu üzerinde çekinik olarak kalıtılır; bu yüzden erkeklerde kadınlara göre daha sık görülür."},{"f":"Eşeye bağlı kalıtım yalnızca X kromozomunda mı görülür?","b":"Hayır; eşeye bağlı kalıtım Y kromozomu üzerinde de görülebilir."},{"f":"Akraba evliliği kalıtsal hastalık riskini neden artırır?","b":"Akraba bireylerin ortak atadan gelen aynı çekinik aleli taşıma olasılığı daha yüksektir."},{"f":"Soyağacında kare ve daire hangi bireyi temsil eder?","b":"Kare erkek bireyi, daire ise dişi bireyi temsil eder."},{"f":"Genetik varyasyonun (çeşitliliğin) başlıca kaynakları nelerdir?","b":"Mutasyon, mayozdaki krossing over ve kromozomların bağımsız dağılımı ile döllenmede gametlerin rastgele birleşmesi."},{"f":"Mutasyon nedir?","b":"DNA'da meydana gelen, sonraki nesillere aktarılabilen kalıtsal değişikliklerdir."},{"f":"Biyolojik çeşitlilik neden bireylerin genotipiyle ilişkilidir?","b":"Popülasyondaki bireyler arasındaki genotip farklılıkları, biyolojik çeşitliliğin temel kaynağıdır."}]},{"id":"biy-7","name":"Ekosistem Ekolojisi ve Çevre Sorunları","cards":[{"f":"Ekosistem nedir?","b":"Belirli bir alandaki canlılar (biyotik) ile bunların cansız çevresinin (abiyotik) birlikte oluşturduğu bütündür."},{"f":"Popülasyon, komünite ve ekosistem arasındaki ilişki nedir?","b":"Popülasyon aynı türden bireyler topluluğu, komünite farklı popülasyonların bir aradalığı, ekosistem ise komünite ile abiyotik çevrenin bütünüdür."},{"f":"Üretici, tüketici ve ayrıştırıcıların ekosistemdeki rolleri nedir?","b":"Üreticiler organik madde üretir, tüketiciler hazır organik besinle beslenir, ayrıştırıcılar ölü madde ve atıkları inorganik maddeye dönüştürür."},{"f":"Besin zinciri ile besin ağı arasındaki fark nedir?","b":"Besin zinciri tek yönlü ve doğrusaldır; besin ağı birden çok besin zincirinin birbirine bağlanmasıyla oluşan karmaşık yapıdır."},{"f":"Enerji piramidinde enerji nasıl aktarılır?","b":"Enerjinin büyük bölümü her basamakta solunum ve ısı kaybıyla azalır; bir üst basamağa yalnızca küçük bir kısmı aktarılır."},{"f":"Madde döngüsü ile enerji akışı arasındaki fark nedir?","b":"Madde (karbon, azot, su vb.) ekosistemde tekrar tekrar kullanılarak döner; enerji ise tek yönlü akar ve sonunda ısı olarak kaybolur."},{"f":"Karbon döngüsünde fotosentez ve solunumun rolü nedir?","b":"Fotosentez atmosferdeki karbondioksiti organik maddeye bağlar; solunum bu karbonu tekrar karbondioksit olarak atmosfere verir."},{"f":"Azot döngüsünde bazı mikroorganizmaların rolü nedir?","b":"Atmosferdeki serbest azotu, bitkilerin kullanabileceği bileşiklere dönüştürürler (azot bağlanması)."},{"f":"Su döngüsünün canlılar için önemi nedir?","b":"Suyun buharlaşma, yoğuşma ve yağış yoluyla sürekli dönmesi, canlıların ihtiyaç duyduğu suyun sürekliliğini sağlar."},{"f":"Ayrıştırıcı canlılara örnek ver, görevleri nedir?","b":"Bakteri ve mantarlar başlıca ayrıştırıcılardır; ölü organizma ve atıkları inorganik maddeye dönüştürerek madde döngüsüne katkı sağlar."},{"f":"Biyolojik birikim (biyoakümülasyon) nedir?","b":"Doğada kolay parçalanmayan zararlı maddelerin besin zinciri boyunca üst basamaklara çıkıldıkça giderek yoğunlaşarak birikmesidir."},{"f":"Küresel iklim değişikliğinin başlıca nedeni nedir?","b":"İnsan etkinlikleriyle atmosfere salınan sera gazlarının artmasıyla dünya ortalama sıcaklığının yükselmesidir."},{"f":"Asit yağmurlarına ne sebep olur?","b":"Fosil yakıtların yanmasıyla açığa çıkan kükürt ve azot oksitlerin atmosferdeki suyla birleşip asidik yağışa dönüşmesidir."},{"f":"Erozyon nedir?","b":"Toprağın rüzgâr, su gibi doğal etkenlerle aşınıp taşınmasıdır; bitki örtüsünün azalması erozyonu hızlandırır."},{"f":"Güncel çevre sorunlarına örnek ver (en az 4).","b":"Hava kirliliği, su kirliliği, toprak kirliliği, küresel iklim değişikliği, erozyon, orman yangınları, ses ve radyoaktif kirlilik."},{"f":"Ekolojik ayak izi neyi ifade eder?","b":"Bir kişinin ya da toplumun tükettiği kaynakları üretmek ve atıklarını yok etmek için gereken biyolojik verimli alanın ölçüsüdür."},{"f":"Karbon ayak izi neyi ölçer?","b":"Bir bireyin veya faaliyetin doğrudan ya da dolaylı olarak atmosfere saldığı sera gazı miktarını ölçer."},{"f":"Su ayak izi neyi ifade eder?","b":"Bir bireyin veya ürünün üretiminde ya da tüketiminde kullanılan toplam su miktarını gösteren ölçüttür."},{"f":"Endemik tür nedir?","b":"Sadece belirli bir bölgede doğal olarak yetişen, dünyanın başka hiçbir yerinde doğal yayılışı bulunmayan türdür."},{"f":"Gen bankalarının amacı nedir?","b":"Nesli tükenme tehlikesindeki türlerin tohum, sperm veya doku gibi genetik materyallerini saklayarak biyolojik çeşitliliği korumaktır."},{"f":"Sürdürülebilirlik ne anlama gelir?","b":"Doğal kaynakların, gelecek nesillerin ihtiyaçlarını karşılama yeteneğini tehlikeye atmadan kullanılmasıdır."},{"f":"Biyolojik çeşitliliğin azalmasının başlıca nedenleri nelerdir?","b":"Doğal yaşam alanlarının tahribi, kirlilik, aşırı avlanma/biyokaçakçılık ve iklim değişikliği başlıca nedenlerdir."},{"f":"Biyokaçakçılık nedir?","b":"Nesli tehlike altındaki bitki ve hayvan türlerinin veya parçalarının yasa dışı yollarla toplanıp ticaretinin yapılmasıdır."},{"f":"Bir ekosistemde meydana gelen bir değişiklik neden önemlidir?","b":"Ekosistemdeki canlı-cansız denge birbirine bağlı olduğundan, bir değişiklik zincirleme biçimde diğer bileşenleri de etkileyebilir."}]}]}];
